window.KNOWLEDGE_DATA["chemistry-sp"] = {"subject":"chemistry","semester":"sp","stage":"special","label":"专题与压轴","chapters":[{"id":"chemistry-sp-c1","name":"工业工艺流程压轴","unit":"专题·工业工艺流程压轴","points":[{"id":"chemistry-sp-p01","name":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题干出现“粗盐提纯”且含可溶性杂质 CaCl₂、MgCl₂、Na₂SO₄，要求写出除杂试剂顺序","工艺流程里连续加入多种“过量”沉淀剂，最后过滤再加适量稀盐酸并蒸发结晶","题干考查“海水提镁”或“卤水制取 MgCl₂ / Mg”的多步转化流程"],"steps":["第一步（一一配对除杂）：盯准杂质离子选专属沉淀剂——SO₄²⁻ 用 BaCl₂，Mg²⁺ 用 NaOH，Ca²⁺ 用 Na₂CO₃（均需过量确保除尽）。","第二步（锁死两条顺序铁律）：① Na₂CO₃ 必须在 BaCl₂ 之后加入（顺带除掉过量 Ba²⁺）；② 稀盐酸必须在过滤之后加入（防止生成的沉淀重新溶解）。","第三步（收尾处理过量试剂）：过滤后滤液中仅剩 NaCl 及过量 NaOH、Na₂CO₃，加适量稀盐酸一次中和成 NaCl、H₂O 和 CO₂，再蒸发结晶（HCl 易挥发，稍过量也无妨）。"],"variants":["变式1（合并试剂省步骤）：用过量 Ba(OH)₂ 一步同时除去 SO₄²⁻ 和 Mg²⁺，随后仍须加过量 Na₂CO₃ 除 Ca²⁺ 与过量 Ba²⁺。","变式2（过滤后加稀盐酸的追问）：若未过滤就直接加稀盐酸，Mg(OH)₂、CaCO₃、BaCO₃ 沉淀会全部重新溶解，仅 BaSO₄ 不溶。","变式3（海水提镁流程）：海水加熟石灰 Ca(OH)₂ 沉淀 Mg²⁺ 比加 NaOH 成本低得多；Mg(OH)₂ 加稀盐酸变 MgCl₂ 溶液，蒸发浓缩得无水 MgCl₂ 再电解得 Mg。"],"parentGuide":{"ask":"粗盐除杂一共要加 BaCl₂、NaOH、Na₂CO₃ 和稀盐酸四种试剂，哪两种顺序绝对不能颠倒？为什么？","key":"孩子能说出“Na₂CO₃ 必须在 BaCl₂ 之后（用来除过量 Ba²⁺）”以及“稀盐酸必须在过滤之后（防止沉淀重新溶解）”这两条铁律，就算真正吃透。"},"examples":[{"title":"经典母题：粗盐除杂试剂顺序与加酸原理","q":"粗盐水中含 CaCl₂、MgCl₂、Na₂SO₄，加入过量 ①NaOH、②BaCl₂、③Na₂CO₃ 溶液后过滤，再向滤液中加适量稀盐酸，蒸发结晶。写出三种合理的试剂添加顺序，并解释为何稀盐酸稍过量不影响精盐纯度。","eye":"“Na₂CO₃ 兼除 Ca²⁺ 与过量 Ba²⁺”决定了 ③ 必在 ② 之后；① 的位置完全自由。","method":"Ba 在碳前、酸在滤后；① 插空排三序，HCl 蒸发自动飞。","steps":["第一步：先固定 ②BaCl₂ 在 ③Na₂CO₃ 之前，再把 ①NaOH 插入前、中、后三个空位，得三种顺序：①②③、②①③、②③①。","第二步：过滤后滤液含 NaCl、过量 NaOH 和过量 Na₂CO₃，加稀盐酸发生中和与产气反应全部转为 NaCl。","第三步：因为稀盐酸中的溶质 HCl 具有挥发性，蒸发结晶时过量的 HCl 会随水蒸气一起挥发除去，最终只留纯净 NaCl 晶体。"]},{"title":"高频变式：海水提镁工艺分析","q":"海水提镁流程：海水(含 MgCl₂) → 加石灰乳得 Mg(OH)₂ 沉淀 → 过滤洗涤 → 加稀盐酸得 MgCl₂ 溶液 → 制无水 MgCl₂ → 通电分解得 Mg 和 Cl₂。问：为什么工业上用石灰乳而不用 NaOH？写出加稀盐酸的化学方程式。","eye":"工业流程既看化学原理，更看原料成本（贝壳煅烧即可廉价得 CaO→Ca(OH)₂）。","method":"工业选试剂看“廉价易得”，富集提纯目的是把海水中极稀的 Mg²⁺ 浓缩提纯。","steps":["第一步：海边富含贝壳（主要成分 CaCO₃），高温煅烧加水即得廉价石灰乳 Ca(OH)₂，成本远低于 NaOH。","第二步：过滤出 Mg(OH)₂ 沉淀，实现了镁元素的富集与除杂。","第三步：写中和方程式：Mg(OH)₂＋2HCl＝MgCl₂＋2H₂O（注意配平 2HCl 与 2H₂O）。"]}]},"card":{"concept":["除粗盐中 CaCl2、MgCl2、Na2SO4：分别加过量 Na2CO3（除 Ca²⁺ 及过量 Ba²⁺）、NaOH（除 Mg²⁺）、BaCl2（除 SO4²⁻），过滤后向滤液加适量稀盐酸（除过量 OH⁻、CO3²⁻），最后蒸发结晶。","三大试剂顺序铁律：Na2CO3 必须在 BaCl2 之后加入！稀盐酸必须在过滤之后加入！","海水提镁主线：海水(MgCl2) → 加熟石灰(Ca(OH)2)得 Mg(OH)2↓ → 加稀盐酸得 MgCl2 → 电解熔融 MgCl2 得 Mg＋Cl2↑。"],"formula":["合法加药顺序共 3 种：① BaCl2→NaOH→Na2CO3；② BaCl2→Na2CO3→NaOH；③ NaOH→BaCl2→Na2CO3。"],"pitfall":["若在过滤“之前”加稀盐酸，生成的 CaCO3、BaCO3、Mg(OH)2 沉淀会重新溶解，杂质又回到溶液里！"],"example":{"q":"如图粗盐提纯除可溶性杂质流程，为什么过量 Na2CO3 必须在过量 BaCl2 之后加入？","a":"Na2CO3 不仅要除去原溶液中的 Ca²⁺，还要把前面引入的过量 Ba²⁺ 转化为 BaCO3 沉淀一并除去。","img":"./assets/knowledge/chemistry/sp/p01-flow.svg"}},"qids":["kp-chemistry-sp-p01-01","kp-chemistry-sp-p01-02","kp-chemistry-sp-p01-03","kp-chemistry-sp-p01-04","kp-chemistry-sp-p01-05","kp-chemistry-sp-p01-06","kp-chemistry-sp-p01-07","kp-chemistry-sp-p01-08","kp-chemistry-sp-p01-09"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]},{"id":"chemistry-sp-p02","name":"废液回收金属与矿石综合利用流程","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题干出现“工厂废液/电子废料回收铜（或银）”同时制取 FeSO₄、ZnSO₄ 等晶体","流程框图中出现“加过量某金属粉 → 过滤 → 滤渣加稀酸 → 过滤”的双过滤结构","工艺题追问“粉碎矿石、搅拌、适当升温、酸浸过量”等操作的目的"],"steps":["第一步（选金属：锁目标盐阳离子）：回收滤液目标是什么盐，就加过量该盐对应的金属（如要得 FeSO₄ 就加过量铁粉，绝不引入新金属离子）。","第二步（判滤渣：置换金属＋过量原金属）：因为第一步加了过量金属，滤渣里一定是“置换出的弱金属＋过量的强金属”混合物。","第三步（洗滤渣：选对应酸溶过量金属）：向滤渣加适量稀硫酸（对应硫酸盐）或稀盐酸（对应氯化物），溶解过量强金属留下纯弱金属，且所得滤液可与前滤液合并提纯晶体。"],"variants":["变式1（换目标盐）：从 CuSO₄ 与 ZnSO₄ 废液回收 Cu 和 ZnSO₄ 晶体 → 第一步改加过量锌粉，滤渣（Cu＋Zn）再加稀硫酸。","变式2（除过量铁粉的选酸陷阱）：目标晶体是 FeSO₄ 时，溶滤渣里的过量 Fe 必须用稀硫酸而不能用稀盐酸，否则滤液合并会引入 Cl⁻ 杂质。","变式3（磁铁物理分离）：若只回收 Cu 而不必合并滤液，滤渣（Cu＋Fe）也可用磁铁吸引直接分离出铁粉。"],"parentGuide":{"ask":"从 CuSO₄ 和 FeSO₄ 废液里回收铜，为什么第一步要加“过量”铁粉？滤渣里多出来的铁粉怎么去掉？","key":"孩子能回答“加过量铁粉是为了把 Cu²⁺ 彻底置换完且不引入新杂质”“滤渣含 Cu 和 Fe，加稀硫酸把铁溶解变成 FeSO₄，铜不反应就留下来了”，即完全掌握。"},"examples":[{"title":"经典母题：含 CuSO₄、FeSO₄ 废液回收 Cu 与 FeSO₄","q":"某废液含 CuSO₄、FeSO₄ 和少量 H₂SO₄，加入过量铁粉过滤得滤液 A 和滤渣 B；滤渣 B 加适量稀硫酸过滤得铜和滤液 C。写出滤渣 B 成分及两步中所有化学方程式。","eye":"注意废液里还藏着“少量 H₂SO₄”，第一步过量铁粉会同时发生两个反应！","method":"加过量目标金属换杂又除酸，再用同酸根稀酸洗出纯金属。","steps":["第一步：加过量铁粉发生两个反应：Fe＋CuSO₄＝FeSO₄＋Cu，Fe＋H₂SO₄＝FeSO₄＋H₂↑。","第二步：因铁粉过量，滤渣 B 必为 Cu 和 Fe 的混合物，滤液 A 为纯净 FeSO₄ 溶液。","第三步：滤渣 B 加适量稀硫酸溶解过量 Fe：Fe＋H₂SO₄＝FeSO₄＋H₂↑，过滤得纯 Cu，滤液 A 与 C 合并经蒸发浓缩、降温结晶得 FeSO₄ 晶体。"]},{"title":"高频变式：含 AgNO₃、Cu(NO₃)₂ 废液回收 Ag 与 Cu(NO₃)₂","q":"摄影废液含 AgNO₃ 和 Cu(NO₃)₂，想回收纯银并得到 Cu(NO₃)₂ 溶液，第一步应加入过量的什么金属？过滤后的滤渣如何分离得到纯银？","eye":"目标是 Cu(NO₃)₂ 溶液，所以只能加过量 Cu，不能加 Fe 或 Zn（否则引入新杂质）。","method":"滤液要谁的盐就加谁；滤渣含 Cu 和 Ag 均不与稀酸反应，加足量 AgNO₃ 溶液可将过量 Cu 转为 Cu(NO₃)₂ 并析出更多 Ag。","steps":["第一步：向废液加过量铜粉：Cu＋2AgNO₃＝Cu(NO₃)₂＋2Ag，过滤得纯净 Cu(NO₃)₂ 滤液和含 Ag、Cu 的滤渣。","第二步：Cu 和 Ag 均排在 H 后，都不与稀硫酸/稀盐酸反应，故不能用稀硫酸除 Cu。","第三步：向滤渣（Ag、Cu）中加入足量 AgNO₃ 溶液（或加热氧化后加稀硫酸），将过量 Cu 反应完，过滤洗涤即得纯净银。"]}]},"card":{"concept":["从含 CuSO4、FeSO4 的废液中回收金属铜并得 FeSO4 晶体：① 加“过量铁粉”（换出全部 Cu，不引新金属杂质）；② 过滤得滤渣（Cu＋过量 Fe）和滤液（FeSO4）；③ 滤渣加适量“稀硫酸”除过量 Fe，过滤洗净得纯 Cu！","流程常考三问：① 粉碎/搅拌/适当升温→增大接触面积、加快反应速率；② 过量试剂→使目标离子完全反应；③ 蒸发浓缩、冷却结晶→提取溶解度受温度影响大的晶体。"],"formula":["Fe＋CuSO4＝FeSO4＋Cu；Fe＋H2SO4＝FeSO4＋H2↑（切记用稀硫酸而不是稀盐酸，防引入 Cl⁻！）。"],"pitfall":["回收 FeSO4 晶体时，除过量铁粉必须用“稀硫酸”而绝不能用稀盐酸（否则引入 FeCl2 杂质）！"],"example":{"q":"从含 CuSO4 和 ZnSO4 的废液中回收金属铜和硫酸锌晶体，第一步应加入过量的哪种金属？","a":"加入过量锌粉（Zn＋CuSO4＝ZnSO4＋Cu），不引入新杂质；滤渣加稀硫酸除过量锌即可得纯铜。","img":"./assets/knowledge/chemistry/sp/p02-metal-flow.svg"}},"qids":["kp-chemistry-sp-p02-01","kp-chemistry-sp-p02-02","kp-chemistry-sp-p02-03","kp-chemistry-sp-p02-04","kp-chemistry-sp-p02-05","kp-chemistry-sp-p02-06","kp-chemistry-sp-p02-07","kp-chemistry-sp-p02-08","kp-chemistry-sp-p02-09"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]},{"id":"chemistry-sp-p03","name":"碳捕集、双碳工艺与物质循环利用","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["流程框图出现“碳捕捉、碳封存、碳达峰、碳中和、CO₂ 捕集与资源化利用”","流程图中有反向箭头（从后面设备指回前面设备），要求写出“可循环利用的物质”","题干给出新型催化反应（如 CO₂ 加 H₂ 制甲醇 CH₃OH、甲烷 CH₄ 或淀粉）要求配平方程式"],"steps":["第一步（抓“碱吸酸放”主线）：捕捉室用碱液（NaOH）吸收酸性气体 CO₂ 生成 Na₂CO₃；反应室用 CaO/Ca(OH)₂ 把 Na₂CO₃ 变回 NaOH 并沉淀出 CaCO₃；煅烧炉高温分解 CaCO₃ 释放高纯度 CO₂ 并再生 CaO。","第二步（一眼找循环物质）：顺着流程箭头找“闭环”——前面作为反应物被消耗、后面作为生成物又重新产出的物质（经典碳捕捉即 NaOH 和 CaO）。","第三步（读图写陌生方程式）：箭头进的是反应物、箭头出的是生成物、线上/框内文字是条件，按原子守恒配平并补全条件与 ↑↓。"],"variants":["变式1（能耗评价）：高温煅烧炉需要消耗大量能源，这是传统 NaOH-CaO 碳捕捉工艺的主要缺点，改进方向是太阳能供热或新型低能耗吸收剂。","变式2（碳资源化计算）：CO₂＋3H₂ ＝催化剂＝ CH₃OH＋H₂O 中，利用质量比 44 : 6 : 32 算耗氢量或甲醇产量，并强调 H₂ 来自风电/光电电解水（绿氢）才真正低碳。","变式3（物理操作目的）：喷淋/雾化 NaOH 溶液→增大接触面积提高吸收率；加压降温→使高纯度 CO₂ 液化便于储存运输。"],"parentGuide":{"ask":"在一张复杂的化工流程图里，怎么一眼判断哪些物质是可以“循环利用”的？","key":"孩子能说出“看回头箭头：前面反应消耗掉它，后面反应又把它重新生成出来（比如碳捕捉里的 NaOH 和 CaO）”，就说明看懂了流程本质。"},"examples":[{"title":"经典母题：NaOH-CaO 碳捕捉循环分析","q":"“碳捕捉”流程：捕捉室（NaOH 溶液吸 CO₂）→ 反应室（加 CaO 混合）→ 过滤得 NaOH 溶液回捕捉室、CaCO₃ 送高温煅烧炉 → 分解得 CaO 回反应室及高纯度 CO₂。写出反应室的两个化学方程式及循环物质。","eye":"反应室投入的是生石灰 CaO 和 Na₂CO₃ 水溶液，实际连续发生“先化合、后复分解”两步反应。","method":"生石灰入水必先变熟石灰，再与纯碱复分解再生烧碱。","steps":["第一步：CaO 与溶液中的水化合放热：CaO＋H₂O＝Ca(OH)₂。","第二步：生成的 Ca(OH)₂ 与 Na₂CO₃ 反应：Ca(OH)₂＋Na₂CO₃＝CaCO₃↓＋2NaOH。","第三步：对照回头箭头，捕捉室循环用 NaOH，反应室循环用 CaO（高温煅烧 CaCO₃ 再生）。"]},{"title":"高频变式：CO₂ 催化加氢制清洁燃料","q":"我国科学家实现了在催化剂作用下利用 CO₂ 和 H₂ 合成甲烷（CH₄）和水，写出该反应的化学方程式；若消耗 44 t CO₂，理论上需要 H₂ 的质量是多少？","eye":"陌生反应不慌张，明确反应物 CO₂＋H₂、生成物 CH₄＋H₂O，按 C→H→O 顺序配平。","method":"定一法配平有机物反应：先定 CH₄ 为 1，则 CO₂ 为 1、H₂O 为 2、H₂ 为 4。","steps":["第一步：配平方程式：CO₂＋4H₂ ＝催化剂＝ CH₄＋2H₂O（检查 C:1=1, O:2=2, H:8=4+4）。","第二步：算相对分子质量比：CO₂ 为 44，4H₂ 为 4×2＝8。","第三步：列比例 44/44 t＝8/x，解得理论上需要 H₂ 质量为 8 t。"]}]},"card":{"concept":["“碳捕捉”典型工艺：捕捉室（2NaOH＋CO2＝Na2CO3＋H2O）→ 反应室（CaO＋H2O＝Ca(OH)2，Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH）→ 高温煅烧炉（CaCO3＝(高温)CaO＋CO2↑）。","判断可循环利用物质：在流程图中，箭头指向前面步骤、既是后面反应的生成物又是前面反应的反应物（如碳捕捉中的 NaOH 和 CaO）！","双碳新途径：CO2 催化加氢制甲醇（CO2＋3H2＝CH3OH＋H2O），变废为宝实现碳资源化。"],"formula":["喷淋法吸收 CO2 优点：增大气体与碱液的接触面积，使 CO2 吸收更充分！"],"pitfall":["碳捕捉工艺中“喷淋”NaOH 溶液是增大接触面积；高温煅烧炉消耗大量能源是该工艺的主要缺点。"],"example":{"q":"如图“碳捕捉”工艺流程，整个过程中可以循环利用的两种物质是什么？","a":"氢氧化钠（NaOH）和氧化钙（CaO）。","img":"./assets/knowledge/chemistry/sp/p03-carbon.svg"}},"qids":["kp-chemistry-sp-p03-01","kp-chemistry-sp-p03-02","kp-chemistry-sp-p03-03","kp-chemistry-sp-p03-04","kp-chemistry-sp-p03-05","kp-chemistry-sp-p03-06","kp-chemistry-sp-p03-07","kp-chemistry-sp-p03-08","kp-chemistry-sp-p03-09"],"refs":["national-js-suzhou-2026-chemistry-q23","national-jx-2026-chemistry-q17"]}]},{"id":"chemistry-sp-c2","name":"框图推断与离子共存压轴","unit":"专题·框图推断与离子共存","points":[{"id":"chemistry-sp-p04","name":"题眼突破与初中常见“三角”转化框图推断","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["框图推断题出现字母 A、B、C、D、E、F 以及单向箭头“→”（转化）和双向短线“—”（反应）","题干藏有颜色、状态、俗名、组成元素相同、相对分子质量（如 100）、用途等关键描述","框图中出现三条边首尾相连的“三角转化”结构"],"steps":["第一步（死抓“题眼”破口）：先标出颜色题眼（红 Cu/Fe₂O₃、黑 C/CuO/Fe₃O₄/MnO₂/Fe 粉、蓝 Cu²⁺/Cu(OH)₂、浅绿 Fe²⁺、黄 Fe³⁺/红褐 Fe(OH)₃）、用途题眼（胃酸 HCl、改良酸性土壤 Ca(OH)₂、灭火/光合作用 CO₂、大理石 CaCO₃）。","第二步（套用四大高频三角）：见 C/CO/CO₂（碳三角）、CaCO₃/CaO/Ca(OH)₂（钙三角）、H₂O₂/H₂O/O₂（氧三角）、NaOH/Na₂CO₃/NaCl（钠三角），迅速推导相邻字母。","第三步（全图代入复验）：把推出来的每个物质代回框图每一条箭头和连线，逐一确认反应条件与现象全部自洽，最后看清题目要写“名称”还是“化学式”。"],"variants":["变式1（多答案/发散型推断）：如“黑色固体与酸反应得蓝色溶液”必为 CuO，但“能与酸和 CO₂ 均反应的碱”可能是 NaOH 也可能是 Ca(OH)₂，要结合后续生成沉淀锁定 Ca(OH)₂。","变式2（元素组成相同对子）：无色气体 CO/CO₂、无色液体 H₂O₂/H₂O、铁的氧化物 Fe₂O₃/Fe₃O₄、亚铁与铁盐 FeCl₂/FeCl₃。","变式3（高温分解反应突破口）：初中常见高温分解只有 CaCO₃ ＝高温＝ CaO＋CO₂↑；通电分解只有 2H₂O ＝通电＝ 2H₂↑＋O₂↑。"],"parentGuide":{"ask":"做框图推断题时，第一步应该从头按 A、B、C 顺序猜，还是先找什么？初中哪三个“转化三角”最常考？","key":"孩子能回答“绝不能盲猜，要先找颜色、俗名、用途、元素相同等题眼突破口，再顺藤摸瓜”，并脱口而出“碳三角、钙三角、氧三角”，就掌握了破题核心。"},"examples":[{"title":"经典母题：碳三角＋钙三角连环推断","q":"A、B、C、E、F 为初中常见物质，A 是大理石主要成分，B、C 组成元素相同且常温下均为无色气体，其中 B 可使澄清石灰水变浑浊。已知 A 高温分解得 B 和 E，B 与焦炭高温生成 C，E 与水反应剧烈放热得 F，F 与 B 反应又生成 A。写出 A、B、C、E、F 的化学式。","eye":"题眼1：A＝CaCO₃（大理石）；题眼2：B、C 组成元素相同的气体（CO₂/CO）；题眼3：E 与水放热（CaO）。","method":"双三角交汇点一定是 CO₂，由 CaCO₃ 高温分解直接切开全图。","steps":["第一步：由 A 是大理石主要成分确定 A＝CaCO₃，高温分解得 CaO 和 CO₂。","第二步：B 与 C 均为组成元素相同的气体且 B 与焦炭高温生 C，故 B＝CO₂、C＝CO，进而 E＝CaO。","第三步：CaO 与水剧烈放热生成 F＝Ca(OH)₂，Ca(OH)₂ 与 CO₂ 反应生成 CaCO₃↓＋H₂O，全图验证无误。"]},{"title":"高频变式：颜色题眼突破金属与酸碱盐推断","q":"黑色固体 A 与稀硫酸反应得蓝色溶液 B；B 与某碱溶液 C 反应生成蓝色沉淀 D 和白色沉淀 E（不溶于稀硝酸）。写出 A、B、C、D、E 的化学式及 B＋C 的化学方程式。","eye":"蓝色溶液 B 含 Cu²⁺（CuSO₄），同时生成蓝沉淀 Cu(OH)₂ 和不溶于酸的白沉淀 BaSO₄，瞬间锁定 C 为 Ba(OH)₂！","method":"双沉淀题眼最值钱：遇“蓝沉＋不溶酸白沉”直接想到 CuSO₄＋Ba(OH)₂。","steps":["第一步：黑色固体 A 溶于稀硫酸得蓝色溶液 B，故 A＝CuO，B＝CuSO₄。","第二步：B 与碱 C 反应同时生成蓝色沉淀 D＝Cu(OH)₂ 和不溶于稀硝酸的白色沉淀 E＝BaSO₄，推得碱 C＝Ba(OH)₂。","第三步：写方程式：CuSO₄＋Ba(OH)₂＝BaSO₄↓＋Cu(OH)₂↓（注意标全两个沉淀符号 ↓）。"]}]},"card":{"concept":["必背颜色题眼：黑色固体（C、CuO、Fe3O4、MnO2、铁粉）；红色固体（Cu、Fe2O3 红棕）；蓝色溶液 Cu²⁺；浅绿色 Fe²⁺；黄色 Fe³⁺；蓝色沉淀 Cu(OH)2；红褐色沉淀 Fe(OH)3。","必背俗名/用途题眼：胃酸主要成分 HCl；建筑材料/补钙剂 CaCO3；改良酸性土壤 Ca(OH)2；焙制糕点 NaHCO3；光合作用原料 CO2/H2O。","三大高频三角：碳三角（C/CO/CO2）、氧三角（H2O2/H2O/O2）、钙三角（CaCO3/CaO/Ca(OH)2）。"],"formula":["元素组成相同气体：CO 与 CO2；元素组成相同液体：H2O2 与 H2O！"],"pitfall":["推出所有物质后，一定要把化学式全部代回原框图箭头逐条验算，确保每一步反应都能真实发生！"],"example":{"q":"如图钙三角：A 是大理石主要成分，高温分解得 B 和气体，B 与水反应剧烈放热得 C，C 通入 CO2 又变回 A。写出 A、B、C 化学式。","a":"A：CaCO3，B：CaO，C：Ca(OH)2。","img":"./assets/knowledge/chemistry/sp/p04-infer.svg"}},"qids":["kp-chemistry-sp-p04-01","kp-chemistry-sp-p04-02","kp-chemistry-sp-p04-03","kp-chemistry-sp-p04-04","kp-chemistry-sp-p04-05","kp-chemistry-sp-p04-06","kp-chemistry-sp-p04-07","kp-chemistry-sp-p04-08","kp-chemistry-sp-p04-09"],"refs":[]},{"id":"chemistry-sp-p05","name":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["选择题或探究题问“下列各组离子在溶液中能大量共存的是”","题干附带“无色透明”“pH＝1/pH＝13”“遇酚酞变红”“遇石蕊变红”“加入铁粉有气泡”等前提条件","废液成分推断题给出一系列离子清单，通过滴加试剂现象反推一定含、一定不含、可能含哪些离子"],"steps":["第一步（先挖隐含离子与颜色）：把文字翻译成离子——“无色”直接划掉 Cu²⁺(蓝)、Fe²⁺(浅绿)、Fe³⁺(黄)、MnO₄⁻(紫红)；“pH＜7/遇石蕊红/加铁冒泡”说明藏着 H⁺；“pH＞7/遇酚酞红”说明藏着 OH⁻。","第二步（配对查四大死对头）：把隐含离子放进选项一起两两配对，只要能生成水（H⁺＋OH⁻）、气体（H⁺＋CO₃²⁻/HCO₃⁻；NH₄⁺＋OH⁻）或沉淀（Ba²⁺＋SO₄²⁻/CO₃²⁻；Ag⁺＋Cl⁻；Ca²⁺＋CO₃²⁻；Mg²⁺/Cu²⁺/Fe³⁺/Al³⁺＋OH⁻），立即排除！","第三步（审电中性与试剂干扰）：探究题里若推出一种离子，立刻划掉它的死对头；续检 Cl⁻ 前绝不能先加含 Cl⁻ 的试剂（如 BaCl₂、HCl）。"],"variants":["变式1（隐含“水电离/石蕊/pH”伪装）：如“加入紫色石蕊变蓝的溶液”等价于含大量 OH⁻，此时 NH₄⁺、Mg²⁺、Cu²⁺、H⁺ 全军覆没。","变式2（“无色”陷阱）：K⁺、Na⁺、Cl⁻、Cu²⁺ 彼此虽不反应，但只要题干写了“无色溶液”，含蓝色的 Cu²⁺ 依然不能选！","变式3（溶液呈电中性暗坑）：推断题若只剩阴离子全被排除或阳离子全被排除，必须利用“溶液整体呈电中性，至少含一种阳离子和一种阴离子”锁出必含离子（如 Na⁺ 或 K⁺）。"],"parentGuide":{"ask":"看到离子共存题说“无色透明、pH＝13 的溶液”，动笔排选项前必须先做哪两件事？","key":"孩子能说出“① 看到无色先踢掉 Cu²⁺、Fe²⁺、Fe³⁺、MnO₄⁻ 四个有色离子；② 看到 pH＝13 立刻往每个选项里加进 OH⁻ 再查会不会生成沉淀、气体或水”，就算完全通关。"},"examples":[{"title":"经典母题：隐含条件下的离子共存筛选","q":"在无色透明、能使无色酚酞溶液变红的溶液中，下列各组离子能大量共存的是：A. Na⁺、Fe³⁺、Cl⁻、NO₃⁻；B. K⁺、NH₄⁺、SO₄²⁻、NO₃⁻；C. Na⁺、K⁺、CO₃²⁻、Cl⁻；D. H⁺、Na⁺、SO₄²⁻、Cl⁻。","eye":"“无色”踢掉 Fe³⁺(黄)，“酚酞变红”隐含 OH⁻，把 OH⁻ 放进各组一试立判！","method":"先排颜色，再塞隐含离子（H⁺/OH⁻），最后查水气沉。","steps":["第一步：A 中 Fe³⁺ 呈黄色，且与隐含的 OH⁻ 生成红褐色 Fe(OH)₃↓，排除 A。","第二步：B 中 NH₄⁺ 与 OH⁻ 结合生成 NH₃↑＋H₂O，排除 B；D 中 H⁺ 与 OH⁻ 结合生成 H₂O，排除 D。","第三步：C 中 Na⁺、K⁺、CO₃²⁻、Cl⁻ 及隐含 OH⁻ 均无色且互不反应，故选 C。"]},{"title":"高频变式：溶液电中性推断必含离子","q":"某无色溶液可能含 Na⁺、Cu²⁺、Ba²⁺、CO₃²⁻、SO₄²⁻。滴加稀盐酸产生气泡，且原溶液滴加 BaCl₂ 产白沉淀。判断原溶液一定含什么离子？","eye":"滴稀盐酸冒泡→含 CO₃²⁻→踢掉 Ba²⁺；无色→踢掉 Cu²⁺；阳离子只剩 Na⁺，靠“电中性”锁定必含 Na⁺！","method":"阳离子排完只剩一个时，靠溶液电中性铁律它必然存在。","steps":["第一步：无色排除 Cu²⁺；加稀盐酸产生气泡证明一定含 CO₃²⁻。","第二步：Ba²⁺ 与 CO₃²⁻ 生成 BaCO₃ 沉淀不能共存，故一定不含 Ba²⁺。","第三步：此时所有阳离子中已排除 Cu²⁺ 和 Ba²⁺，因溶液必须呈电中性（有阴离子必有阳离子），故一定含有 Na⁺；而 SO₄²⁻ 无法确定（BaCO₃ 也是白沉淀）。"]}]},"card":{"concept":["审题先挖“隐含离子”：① pH＜7 / 遇石蕊变红 / 强酸性 → 隐含大量 H⁺；② pH＞7 / 遇酚酞变红 / 强碱性 → 隐含大量 OH⁻；③ 无色透明溶液 → 排除 Cu²⁺(蓝)、Fe²⁺(浅绿)、Fe³⁺(黄)、MnO4⁻(紫红)！","高频死对头离子清单：H⁺ 怕（OH⁻、CO3²⁻、HCO3⁻）；OH⁻ 怕（H⁺、NH4⁺、Mg²⁺、Fe³⁺、Cu²⁺、Al³⁺）；Ba²⁺ 怕（SO4²⁻、CO3²⁻）；Ca²⁺ 怕（CO3²⁻）；Ag⁺ 怕（Cl⁻、CO3²⁻、OH⁻）！"],"formula":["万能共存五剑客：K⁺、Na⁺、NO3⁻ 在初中水溶液中几乎不与任何离子反应！"],"pitfall":["看到“无色溶液”第一时间划掉含 Cu²⁺、Fe²⁺、Fe³⁺、MnO4⁻ 的选项！看到“pH＝13”立刻排除 NH4⁺、Mg²⁺、Cu²⁺、H⁺、HCO3⁻！"],"example":{"q":"在能使无色酚酞变红的溶液中，下列哪组离子能大量共存：A. NH4⁺、Na⁺、Cl⁻；B. K⁺、Na⁺、CO3²⁻、NO3⁻；C. H⁺、K⁺、SO4²⁻？","a":"选 B！酚酞变红隐含大量 OH⁻；A 中 NH4⁺＋OH⁻→NH3↑＋H2O，C 中 H⁺＋OH⁻→H2O，均不能共存。","img":"./assets/knowledge/chemistry/sp/p05-ions.svg"}},"qids":["kp-chemistry-sp-p05-01","kp-chemistry-sp-p05-02","kp-chemistry-sp-p05-03","kp-chemistry-sp-p05-04","kp-chemistry-sp-p05-05","kp-chemistry-sp-p05-06","kp-chemistry-sp-p05-07","kp-chemistry-sp-p05-08","kp-chemistry-sp-p05-09"],"refs":[]},{"id":"chemistry-sp-p06","name":"金属与混合盐溶液滤渣滤液成分压轴","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题干出现“向 AgNO₃ 和 Cu(NO₃)₂ 混合液加入一定量 Fe 粉（或 Zn 粉），充分反应后过滤”","或反过来“向某种盐溶液加入两种金属混合物（如 Zn 粉和 Fe 粉）”","考查滤渣成分、滤液溶质、滤液颜色、溶液质量增减趋势以及加酸/加盐检验现象"],"steps":["第一步（定顺序：远距离优先）：把参与的金属按活动性排成一排，距离最远的一对最先反应！如 Fe 加入 AgNO₃＋Cu(NO₃)₂ → ① Fe 先置换 Ag⁺，Ag⁺ 耗尽后 ② Fe 再置换 Cu²⁺。","第二步（画数轴分四区间/五节点）：沿加入金属质量从小到大标出两个临界点（Ag⁺ 恰耗尽、Cu²⁺ 恰耗尽），直接读出每个区间的滤渣和滤液成分。","第三步（抓两大铁律＋特征现象反推）：无论在哪段，滤渣必含最弱金属 Ag，滤液必含最强金属盐 Fe(NO₃)₂；滤渣加稀盐酸冒泡→过量 Fe（最右区间）；滤液加稀盐酸白沉淀→剩 Ag⁺（最左区间）；滤液呈蓝色→剩 Cu²⁺。"],"variants":["变式1（两金属入一盐）：向 Cu(NO₃)₂ 溶液加 Zn 粉和 Fe 粉 → 同样“远距离优先”，Zn 先置换 Cu²⁺，Zn 耗尽后 Fe 再置换 Cu²⁺。","变式2（溶液质量变化拐点）：Fe＋2AgNO₃→Fe(NO₃)₂＋2Ag（进 56 出 216，溶液质量大减）；Fe＋Cu(NO₃)₂→Fe(NO₃)₂＋Cu（进 56 出 64，溶液质量微减）；若是 Zn 换 Fe²⁺（进 65 出 56，溶液质量反而增大！）。","变式3（含不反应金属离子）：向 Mg(NO₃)₂、Cu(NO₃)₂、AgNO₃ 混合液加 Fe 粉 → Mg 比 Fe 活泼，Mg(NO₃)₂ 全程当“旁观者”永远留在滤液里！"],"parentGuide":{"ask":"往 AgNO₃ 和 Cu(NO₃)₂ 混合液里加铁粉，铁先和谁反应？如果滤渣滴稀盐酸有气泡，滤液里还有 Cu(NO₃)₂ 吗？","key":"孩子能脱口说出“远距离优先，铁先换银再换铜；滤渣加酸冒气泡说明铁粉有剩余，那银和铜早就被全换完了，滤液里只剩 Fe(NO₃)₂”，就彻底过关。"},"examples":[{"title":"经典母题：铁粉入混合盐四区间定位","q":"向 AgNO₃ 和 Cu(NO₃)₂ 混合溶液中加入一定量铁粉，充分反应后过滤。①若向滤液中滴加稀盐酸有白色沉淀生成，求滤渣和滤液成分；②若滤液呈浅绿色且滤渣加稀盐酸无气泡，求滤渣和滤液成分。","eye":"现象①“滤液加 HCl 产白沉”＝含 Ag⁺（落区间①）；现象②“滤液浅绿无蓝色＋渣无 Fe”＝恰把 Cu²⁺ 换完（落临界点③）。","method":"用特征检验反锁数轴区间，再照着区间抄滤渣滤液，零失误！","steps":["第一步：情况①滤液滴稀盐酸产 AgCl 白沉淀，说明 AgNO₃ 有剩余，Fe 极少只发生了第一步部分反应，故滤渣只有 Ag，滤液溶质为 Fe(NO₃)₂、Cu(NO₃)₂、AgNO₃。","第二步：情况②滤液呈浅绿色（不含蓝色的 Cu²⁺，也不可能含 Ag⁺），说明 Cu(NO₃)₂ 已被完全置换；又滤渣加稀盐酸无气泡，说明无剩余 Fe。","第三步：故情况②恰好处于“Cu²⁺ 刚换完、Fe 刚耗尽”的临界点，滤渣为 Ag 和 Cu，滤液溶质只有 Fe(NO₃)₂。"]},{"title":"高频变式：双金属投入单一盐溶液","q":"向一定量 AgNO₃ 溶液中加入等质量的锌粉和铁粉，充分反应后过滤，若滤液呈浅绿色，则滤渣中一定含有什么？滤液中一定含有的溶质是什么？","eye":"活动性 Zn＞Fe＞Ag，Zn 先与 AgNO₃ 反应；滤液显浅绿色说明 Fe 已经参与反应了，意味着 Zn 早已消耗殆尽！","method":"“浅绿色”代表 Fe²⁺ 已进溶液 → 前面更活泼的 Zn 必然 100% 耗尽。","steps":["第一步：反应顺序为 ① Zn＋2AgNO₃＝Zn(NO₃)₂＋2Ag，② Fe＋2AgNO₃＝Fe(NO₃)₂＋2Ag。","第二步：滤液呈浅绿色证明反应②已发生，故 Zn 一定全部转化为 Zn(NO₃)₂，且已有 Ag 析出。","第三步：因此滤渣中一定有 Ag（可能有剩余 Fe，一定无 Zn）；滤液中一定含 Zn(NO₃)₂ 和 Fe(NO₃)₂（可能有剩余 AgNO₃）。"]}]},"card":{"concept":["核心法则：“弱者先出，强者后出”（远距离优先置换）！例如向 AgNO3、Cu(NO3)2 混合液加 Zn 粉：先发生 Zn＋2AgNO3→2Ag，Ag⁺ 耗尽后才发生 Zn＋Cu(NO3)2→Cu！","五段临界点（向 AgNO3、Cu(NO3)2 加 Fe 粉）：① Fe 极少（Ag⁺ 剩余）：渣 Ag，液 Fe²⁺/Cu²⁺/Ag⁺；② 恰好换完 Ag⁺：渣 Ag，液 Fe²⁺/Cu²⁺；③ 换部分 Cu²⁺：渣 Ag/Cu，液 Fe²⁺/Cu²⁺；④ 恰好换完 Cu²⁺：渣 Ag/Cu，液 Fe²⁺；⑤ Fe 过量：渣 Ag/Cu/Fe，液 Fe²⁺。","必有规律：滤渣中“一定有最不活泼的 Ag”；滤液中“一定有加入金属对应的盐（Fe(NO3)2）”！"],"formula":["检验技巧：向滤渣加稀盐酸有气泡 → 加入金属过量！向滤液加稀盐酸有白色沉淀（AgCl）→ AgNO3 剩余！"],"pitfall":["若滤液呈“蓝色”，说明 Cu(NO3)2 一定有剩余，此时加入的铁粉/锌粉肯定已完全耗尽（滤渣绝不含铁/锌），但 AgNO3 可能剩余也可能刚好耗尽！"],"example":{"q":"向 AgNO3 和 Cu(NO3)2 混合液中加入一定量铁粉，充分反应后过滤，若滤液呈浅绿色且向滤渣加稀盐酸无气泡，滤渣中一定有什么？可能有什么？","a":"滤液呈浅绿色说明 Cu²⁺ 已全部反应完（无蓝色），加盐酸无气泡说明 Fe 无剩余，故滤渣恰好是 Ag 和 Cu（两者一定都有，一定无 Fe）！","img":"./assets/knowledge/chemistry/sp/p06-filtrate.svg"}},"qids":["kp-chemistry-sp-p06-01","kp-chemistry-sp-p06-02","kp-chemistry-sp-p06-03","kp-chemistry-sp-p06-04","kp-chemistry-sp-p06-05","kp-chemistry-sp-p06-06","kp-chemistry-sp-p06-07","kp-chemistry-sp-p06-08","kp-chemistry-sp-p06-09"],"refs":["national-js-suzhou-2026-chemistry-q19"]}]},{"id":"chemistry-sp-c3","name":"实验探究（变质/成分/除杂鉴别）压轴","unit":"专题·实验探究与除杂鉴别","points":[{"id":"chemistry-sp-p07","name":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["探究题出现“敞口放置一段时间的 NaOH 溶液/固体（或 Ca(OH)₂、生石灰 CaO）是否变质、变质程度如何”","题干要求证明某碱溶液是“部分变质”还是“完全变质”","实验评价题追问“为什么不能用 Ca(OH)₂ 代替 CaCl₂”“为什么 CaCl₂ 必须加过量”"],"steps":["第一步（区分两大问法）：问“是否变质”只需检 CO₃²⁻（加足量稀盐酸看气泡，或加 CaCl₂/BaCl₂/Ca(OH)₂ 看白沉淀）；问“变质程度”必须同时查清“有无 Na₂CO₃”和“有无 NaOH”。","第二步（部分 vs 完全变质两步铁律）：Step1 加“过量”中性钙/钡盐（CaCl₂ 或 BaCl₂ 溶液）→ 产生白沉淀证明含 Na₂CO₃，同时把显碱性的 CO₃²⁻ 除尽；Step2 静置取上层清液滴酚酞（或加 CuSO₄/MgCl₂）→ 变红（或产蓝/白沉淀）则部分变质，无变化则完全变质。","第三步（死守两大防错理由）：① 必须写“过量/足量”，防止残留 Na₂CO₃ 显碱性干扰酚酞；② 绝不能用 Ca(OH)₂ 或 Ba(OH)₂，因为反应会生成新 NaOH 造成假阳性！"],"variants":["变式1（固体变质检验溶解热法）：生石灰 CaO 变质先吸水变 Ca(OH)₂ 再吸 CO₂ 变 CaCO₃；加水测温度升高→仍含 CaO；加稀盐酸冒泡→含 CaCO₃；上层清液滴酚酞变红不能证明原样品含 Ca(OH)₂（因 CaO 遇水也会生成 Ca(OH)₂！）。","变式2（用稀盐酸看现象定部分变质）：向待测 NaOH 溶液中逐滴加稀盐酸，若“开始无气泡、滴一会儿才冒气泡”，说明先中和了 NaOH 再与 Na₂CO₃ 反应，也能证明是部分变质！","变式3（除去 NaOH 溶液中的少量 Na₂CO₃）：此时恰恰要加“适量 Ca(OH)₂ 溶液”再过滤（Ca(OH)₂＋Na₂CO₃＝CaCO₃↓＋2NaOH），把杂质直接变成目标物 NaOH——切忌和“检验变质程度”混淆！"],"parentGuide":{"ask":"检验 NaOH 溶液是不是“部分变质”，为什么不能直接滴酚酞？第一步为什么要加“过量 CaCl₂”而不是 Ca(OH)₂？","key":"孩子能说清“Na₂CO₃ 也显碱性会干扰酚酞，所以要先用过量中性的 CaCl₂ 把 Na₂CO₃ 沉淀除尽；Ca(OH)₂ 会引入 OH⁻（生成新 NaOH）反而制造干扰”，就是满分级理解。"},"examples":[{"title":"经典母题：NaOH 溶液变质程度完整验证","q":"设计实验检验敞口放置的 NaOH 溶液是部分变质还是完全变质，写出步骤、现象、结论及涉及的化学方程式。","eye":"检验“部分 vs 完全”的核心矛盾是：Na₂CO₃ 溶液也显碱性，会抢酚酞的戏！","method":"先过量中性钙钡盐除尽碳酸根，再取清液滴酚酞辨真碱。","steps":["第一步：取少量待测液于试管中，加入过量 BaCl₂（或 CaCl₂）溶液，观察到有白色沉淀产生（BaCl₂＋Na₂CO₃＝BaCO₃↓＋2NaCl），证明已变质且将 Na₂CO₃ 除尽。","第二步：静置（或过滤），向上层清液中滴加几滴无色酚酞溶液。","第三步：若溶液变红，说明含 NaOH，为部分变质；若溶液不变红（无色），说明不含 NaOH，为完全变质。"]},{"title":"高频变式：生石灰干燥剂变质成分探究","q":"一包久置的食品干燥剂（原成分 CaO），取少量加水搅拌发现烧杯壁明显发烫且底部有不溶物，再向不溶物滴稀盐酸有气泡。能否确定干燥剂中一定含有 CaO、Ca(OH)₂ 和 CaCO₃？","eye":"发烫→必含 CaO；不溶物加酸冒泡→必含 CaCO₃；但 Ca(OH)₂ 无法确定（发烫就是 CaO 与水生成了新 Ca(OH)₂）！","method":"遇到 CaO 加水，生成的 Ca(OH)₂ 会掩盖原样品里到底有没有 Ca(OH)₂。","steps":["第一步：加水发烫说明一定含有 CaO（CaO＋H₂O＝Ca(OH)₂ 放热）。","第二步：向不溶物滴稀盐酸产生气泡，说明一定含有 CaCO₃（CaCO₃＋2HCl＝CaCl₂＋H₂O＋CO₂↑）。","第三步：由于 CaO 加水本身就会生成 Ca(OH)₂，因此无法通过溶液显碱性判断原固体中是否原本就含有 Ca(OH)₂，故不能确定三者全都有。"]}]},"card":{"concept":["NaOH 变质原因：2NaOH＋CO2＝Na2CO3＋H2O。检验是否变质（检 CO3²⁻）：加过量稀盐酸（看气泡）或 CaCl2/BaCl2 溶液（看白沉淀）或 Ca(OH)2（看白沉淀）。","探究变质程度（部分变质 NaOH＋Na2CO3 vs 完全变质 Na2CO3）两步铁律：① 加“过量”中性钙盐/钡盐（CaCl2 或 BaCl2）检验并“除尽”Na2CO3；② 静置取上层清液滴加无色酚酞（变红→部分变质；不变色→完全变质）！","生石灰（CaO）变质：先吸水变 Ca(OH)2（放热），再吸 CO2 变 CaCO3（加酸冒气泡）。"],"formula":["除杂（NaOH 溶液中除少量 Na2CO3）：加适量 Ca(OH)2 溶液过滤（Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH）！"],"pitfall":["探究变质程度第一步绝不能用 Ca(OH)2 代替 CaCl2！因为 Ca(OH)2 与 Na2CO3 会新生成 NaOH，干扰原 NaOH 的检验！"],"example":{"q":"如图探究 NaOH 溶液变质程度，为什么第一步要加“过量”CaCl2 溶液而不是少量？","a":"确保将呈碱性的 Na2CO3 彻底转化为中性沉淀 CaCO3 除去，防止剩余 Na2CO3 使酚酞变红干扰 NaOH 检验。","img":"./assets/knowledge/chemistry/sp/p07-naoh.svg"}},"qids":["kp-chemistry-sp-p07-01","kp-chemistry-sp-p07-02","kp-chemistry-sp-p07-03","kp-chemistry-sp-p07-04","kp-chemistry-sp-p07-05","kp-chemistry-sp-p07-06","kp-chemistry-sp-p07-07","kp-chemistry-sp-p07-08","kp-chemistry-sp-p07-09"],"refs":[]},{"id":"chemistry-sp-p08","name":"反应后溶液中溶质成分猜想与验证","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["探究题描述某反应（如酸碱中和、盐与盐/碱/酸复分解）完成后，对“反应后滤液/废液中的溶质成分”提出猜想并设计实验验证","题干出现“甲同学猜想溶质为 C、A 和 B，请你评价该猜想是否合理”","题干要求选用“两种不同类别的试剂”验证过量反应物，或评价滴加 AgNO₃/BaCl₂ 能否证明含 HCl/H₂SO₄"],"steps":["第一步（三猜想建模，秒杀不合理猜想）：对于 A＋B→C＋沉淀/气体/水，反应后溶质一定有可溶生成物 C，且 A 和 B 会继续反应绝不能同时共存，故最多只有三种猜想：① 只有 C；② C＋A；③ C＋B。","第二步（看现象先缩范围）：若题干已有线索（如“酚酞呈无色”排除 NaOH 过量；“溶液显蓝色”确定 CuSO₄ 过量），直接把不可能的猜想划掉！","第三步（避共有离子选专属试剂）：永远不测必有的 C，只测过量反应物独有的特征离子！如 NaCl＋HCl 中不能用 AgNO₃ 测 Cl⁻（NaCl 也有 Cl⁻），必须用石蕊/Zn/Na₂CO₃/CuO 测 H⁺。"],"variants":["变式1（选两种不同类别试剂）：检验 H⁺ 的五大类试剂——① 酸碱指示剂（紫色石蕊/pH 试纸）；② 活泼金属（Zn/Fe/Mg）；③ 金属氧化物（CuO/Fe₂O₃）；④ 难溶碱（Cu(OH)₂）；⑤ 碳酸盐（Na₂CO₃/CaCO₃），任选不同两类即可。","变式2（双反应物均可能过量的检验）：如 CaCl₂＋Na₂CO₃→CaCO₃↓＋2NaCl 滤液，检验是否含 CaCl₂ 滴加 Na₂CO₃ 溶液看白沉淀；检验是否含 Na₂CO₃ 滴加稀盐酸看气泡（或 CaCl₂ 溶液看白沉淀）。","变式3（混合废液倒在一起）：将两支试管的废液倒入同一洁净烧杯中观察到“白色沉淀消失且冒气泡”或“变无色”，反推原来两管分别过量了什么物质。"],"parentGuide":{"ask":"反应后猜想滤液里有什么溶质，为什么“生成物＋两种反应物”这个猜想一定错？检验 NaCl 废液里有没有过量 HCl，为什么不能滴 AgNO₃？","key":"孩子能说出“两种反应物会继续反应不能共存”和“NaCl 里本来就有 Cl⁻，滴 AgNO₃ 照样产白沉淀，必须测 H⁺ 才行”，就能稳拿探究题满分。"},"examples":[{"title":"经典母题：Ca(OH)₂ 与 Na₂CO₃ 反应后滤液溶质探究","q":"将一定量 Ca(OH)₂ 溶液与 Na₂CO₃ 溶液混合过滤，对滤液溶质猜想：① NaOH；② NaOH 和 Ca(OH)₂；③ NaOH 和 Na₂CO₃；④ NaOH、Ca(OH)₂ 和 Na₂CO₃。指出不合理猜想，并设计一步实验区分猜想①②③。","eye":"Ca(OH)₂ 和 Na₂CO₃ 会立刻反应生 CaCO₃↓，绝不能同在滤液里！且滤液本来就有 NaOH，不能用酚酞检验！","method":"踢掉共存矛盾项；检验 Ca²⁺ 加 Na₂CO₃，检验 CO₃²⁻ 加稀盐酸或 CaCl₂。","steps":["第一步：猜想④不合理，因为 Ca(OH)₂ 与 Na₂CO₃ 会发生复分解反应生成 CaCO₃ 沉淀，不能共存。","第二步：取滤液分装两支试管：向第一支滴加 Na₂CO₃ 溶液，若产生白色沉淀则猜想②成立。","第三步：向第二支滴加足量稀盐酸（或 CaCl₂ 溶液），若产生气泡（或白色沉淀）则猜想③成立；若两支试管均无明显现象，则猜想①成立。"]},{"title":"高频变式：酸碱废液混合现象反推溶质","q":"甲组做完 NaOH 与 HCl 中和实验后溶液呈红色（含酚酞），乙组做完后溶液呈无色。将两杯废液混合后变为无色，向混合液加碳酸钠溶液产生气泡。推断乙组原废液的溶质成分。","eye":"甲红（含 NaOH）＋乙无色 → 混合后仍无色且加 Na₂CO₃ 冒气泡（说明 HCl 还有剩！），故乙组里 HCl 大量过量。","method":"从最终混合液的检验现象倒推过量方。","steps":["第一步：甲组溶液呈红色，说明甲组含 NaCl 和过量的 NaOH。","第二步：混合后加 Na₂CO₃ 产生气泡，说明混合液中仍有剩余 HCl，证明乙组中的 HCl 不仅中和了甲组的 NaOH 还有盈余。","第三步：因此乙组原废液的溶质一定是 NaCl 和 HCl。"]}]},"card":{"concept":["溶质猜想黄金模型（A＋B → C＋沉淀/气体/水）：反应后溶液中“一定有生成物 C”，且反应物 A 和 B “绝不能同时剩余”（因为会继续反应！）。","故合理猜想只有三种：① 恰好完全反应（只有 C）；② A 过量（C＋A）；③ B 过量（C＋B）。","检验策略：不必再检验必有的生成物 C！只需选特征试剂分别检验“可能过量的 A”或“可能过量的 B”即可！"],"formula":["例：Ca(OH)2＋Na2CO3→CaCO3↓＋2NaOH，过滤后滤液溶质 3 猜想：① NaOH；② NaOH＋Ca(OH)2；③ NaOH＋Na2CO3。"],"pitfall":["检验 HCl＋NaOH 反应后是否剩余 HCl，不能用 AgNO3 溶液（因为生成的 NaCl 也含 Cl⁻，同样产生 AgCl 白沉淀！）——必须检验 H⁺（紫色石蕊、Zn 粒、Na2CO3、CuO）！"],"example":{"q":"CaCl2 溶液与 Na2CO3 溶液反应过滤后，某同学猜想滤液溶质为 NaCl、CaCl2 和 Na2CO3，该猜想合理吗？","a":"不合理！CaCl2 和 Na2CO3 在溶液中会继续反应生成 CaCO3 沉淀，不能共存。","img":"./assets/knowledge/chemistry/sp/p08-solute.svg"}},"qids":["kp-chemistry-sp-p08-01","kp-chemistry-sp-p08-02","kp-chemistry-sp-p08-03","kp-chemistry-sp-p08-04","kp-chemistry-sp-p08-05","kp-chemistry-sp-p08-06","kp-chemistry-sp-p08-07","kp-chemistry-sp-p08-08","kp-chemistry-sp-p08-09"],"refs":[]},{"id":"chemistry-sp-p09","name":"多步除杂、无试剂鉴别与气体净化顺序","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题干出现“除去括号内的少量杂质”（固固、液液、气气多步除杂）","气体检验或净化串联装置（如先检验 H₂O、CO₂、CO、H₂，或净化 CO₂ 中的 HCl 和水蒸气）","出现“不另加任何其他试剂（无试剂鉴别）”或“仅用一种试剂鉴别三/四种溶液”"],"steps":["第一步（气体顺序终极口诀）：“检验先验水（无水 CuSO₄ 变蓝），除杂后除水（浓硫酸/碱石灰放最后），洗气长进短出”——检验时若先过溶液会带出水干扰验水，除杂时若先干燥过溶液又会重新变湿！","第二步（常规除杂三原则）：“不增（不引新杂质）、不减（不消耗主体物质）、易分离（沉淀过滤/气体逸出）”，优先选把杂质直接变成主体物质的试剂（转化法）。","第三步（无试剂鉴别两步走）：先看物理色（蓝 CuSO₄、黄 FeCl₃、浅绿 FeCl₂）以有色鉴无色；全无色就列两两混合现象表，按“气泡数＋沉淀数”唯一配对。"],"variants":["变式1（CO 与 CO₂ 互除）：除 CO₂ 中的少量 CO → 通过灼热 CuO（把 CO 氧化成 CO₂，不能点燃！）；除 CO 中的少量 CO₂ → 通过足量 NaOH 溶液再通过浓硫酸干燥。","变式2（浓硫酸 vs 碱石灰干燥剂避坑）：浓硫酸不能干燥碱性气体 NH₃；碱石灰（NaOH＋CaO）不能干燥酸性气体 CO₂、HCl、SO₂。","变式3（一剂鉴别三/四种无色溶液）：① 酸、碱、中性三液 → 紫色石蕊；② 含 H⁺、Ba²⁺、CO₃²⁻ 或多种阳离子盐 → 优先试 Na₂CO₃ 溶液或 Ba(OH)₂ 溶液（看能否出“气泡、沉淀、无现象”互不相同的结果）。"],"parentGuide":{"ask":"为什么气体检验要“先验水”，而气体除杂却要“后除水”？用一句话讲给我听。","key":"孩子能说明白“检验时如果先经过石灰水等溶液，气体会被润湿，后面就分不清原来的水还是带出来的水；除杂时如果先干燥再过洗气瓶，气体出来又湿了，所以干燥必须放最后”，即满分掌握。"},"examples":[{"title":"经典母题：CO₂ 中混有 HCl 和水蒸气的净化与尾气","q":"制得的 CO₂ 混有 HCl 和 H₂O，需依次通过哪两种试剂？为什么除 HCl 不能用 NaOH 溶液，也不能用饱和 Na₂CO₃ 溶液？","eye":"除杂不仅要除掉 HCl，还绝不能吸收主体 CO₂！NaOH 和 Na₂CO₃ 都会吃掉 CO₂。","method":"除杂后除水：先饱和 NaHCO₃ 溶液（除 HCl 还产 CO₂），后浓硫酸（吸水）。","steps":["第一步：连接顺序为：混合气体 → 饱和 NaHCO₃ 溶液（长进短出，除 HCl：NaHCO₃＋HCl＝NaCl＋H₂O＋CO₂↑）→ 浓硫酸（长进短出，除水蒸气）。","第二步：不能用 NaOH 溶液，因为 2NaOH＋CO₂＝Na₂CO₃＋H₂O 会消耗主体气体 CO₂。","第三步：不能用 Na₂CO₃ 溶液，因为 Na₂CO₃＋CO₂＋H₂O＝2NaHCO₃ 同样会吸收主体气体 CO₂。"]},{"title":"高频变式：有色切入＋无试剂鉴别四溶液","q":"不用任何其他试剂，鉴别 ①CuSO₄、②NaOH、③MgCl₂、④Ba(NO₃)₂ 四种溶液，写出最简鉴别顺序及现象。","eye":"先凭肉眼锁定蓝色的 ①CuSO₄，再把 ① 分别滴进剩下三瓶，直接把 ② 和 ④ 一次全捞出来！","method":"无试剂鉴别先看色，以有色当试剂层层推进。","steps":["第一步：观察颜色，呈蓝色的是 ①CuSO₄ 溶液。","第二步：将 ①CuSO₄ 分别滴入其余三种无色溶液中：产生蓝色沉淀的是 ②NaOH 溶液；产生白色沉淀的是 ④Ba(NO₃)₂ 溶液（BaSO₄↓）；无明显现象的是 ③MgCl₂ 溶液。","第三步：无需再测，一步即全部鉴别完毕（也可把 ②NaOH 滴入 ③ 验证产生白色沉淀 Mg(OH)₂↓）。"]}]},"card":{"concept":["气体检验与除杂终极铁律：“检验先验水（无水 CuSO4 变蓝），除杂后除水（浓硫酸/碱石灰最后干燥）！”","气体净化洗气瓶口诀：“长进短出”！常见吸收剂：除 HCl 用饱和 NaHCO3（制 CO2 时）或水；除 CO2 用 NaOH 溶液；除 H2O 用浓硫酸（酸性/中性气体）或碱石灰（碱性/中性气体）。","无试剂鉴别法（两两混合法）：先看颜色（CuSO4 蓝、FeCl3 黄），再用已知色溶液去鉴别其他无色溶液（生成蓝色/红褐色沉淀或气体）。"],"formula":["CO2 中混有 HCl 和 H2O：先通饱和 NaHCO3 溶液除 HCl，再通浓硫酸干燥！"],"pitfall":["除去 CO2 中的 HCl 气体绝不能用 NaOH 溶液（会把 CO2 也吸收掉！），必须用饱和 NaHCO3 溶液（HCl＋NaHCO3＝NaCl＋H2O＋CO2↑）！"],"example":{"q":"如图，用大理石和浓盐酸制得的 CO2 中混有 HCl 气体和水蒸气，应先除 HCl 还是先除水蒸气？为什么？","a":"先通过饱和 NaHCO3 溶液除 HCl，再通过浓硫酸除水蒸气；若顺序颠倒，气体通过水溶液后又会重新带出水蒸气。","img":"./assets/knowledge/chemistry/sp/p09-gas.svg"}},"qids":["kp-chemistry-sp-p09-01","kp-chemistry-sp-p09-02","kp-chemistry-sp-p09-03","kp-chemistry-sp-p09-04","kp-chemistry-sp-p09-05","kp-chemistry-sp-p09-06","kp-chemistry-sp-p09-07","kp-chemistry-sp-p09-08","kp-chemistry-sp-p09-09"],"refs":[]},{"id":"chemistry-sp-p13","name":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题干出现“压强传感器、pH 传感器、温度传感器、氧气/二氧化碳浓度传感器”并配实时折线图","考查红磷测氧压强曲线三段变化原因，或酸碱中和 pH 与温度同步曲线找恰好完全反应点","推断题、除杂鉴别题中频繁出现俗名（纯碱、小苏打、烧碱、生/熟石灰）和八大沉淀特征"],"steps":["第一步（读传感图四看口诀）：一看纵横坐标明确物理量；二看起点判断原液酸碱性或初始大气压；三看拐点/峰值对应“反应开始、恰好完全反应、打开止水夹”；四看变化趋势归因于“产气/耗气”或“放热/吸热”。","第二步（吃透两大母图）：① 测氧压强图：先升（燃烧放热压倒耗氧）→骤降（耗氧冷却低于常压）→开夹回升（进水恢复常压）；② 酸碱中和双图：pH 起点＞7 为碱加酸、＜7 为酸加碱，温度最高点与 pH＝7 垂直对齐，为恰好中和点。","第三步（俗名沉淀条件反射）：牢记三碱一盐陷阱（烧碱 NaOH、熟石灰 Ca(OH)₂ 是碱，纯碱 Na₂CO₃、小苏打 NaHCO₃ 是盐）及沉淀三梯队（红褐 Fe(OH)₃、蓝 Cu(OH)₂；不溶酸白沉 BaSO₄/AgCl；溶酸冒泡 CaCO₃/BaCO₃）。"],"variants":["变式1（CO₂ 与 NaOH 反应压强对比）：向两瓶充满 CO₂ 的密闭瓶分别注入等体积水和 NaOH 溶液，NaOH 组压强下降幅度远大于水组，从而证明 CO₂ 与 NaOH 确实发生了化学反应而非仅溶于水。","变式2（氧化钙/氢氧化钠/硝酸铵溶于水温度与压强曲线）：密闭瓶加水，CaO 和 NaOH 放热导致温度压强双升，NH₄NO₃ 吸热导致温度压强双降，NaCl 几乎水平不变。","变式3（酸碱中和后溶质区间判定）：碱加酸图像中，pH＞7 区间溶质为“盐＋剩余碱”，pH＝7 仅“盐”，pH＜7 为“盐＋过量酸”。"],"parentGuide":{"ask":"数字化传感实验的曲线看着很高级，其实怎么读？比如红磷测氧曲线为什么一开始压强反而往上飙？","key":"孩子能讲清楚“传感器曲线就是把看不见的吸放热和产耗气画成了折线；红磷燃烧虽然消耗氧气，但瞬间放出大量热让空气受热膨胀，升温升压压过了耗氧降压，所以先飙升再下降”，说明已经打通底层逻辑。"},"examples":[{"title":"经典母题：CO₂ 与 NaOH 反应的压强传感对比验证","q":"用两个相同密闭集气瓶收集满 CO₂，分别注入 20 mL 水和 20 mL NaOH 溶液，用压强传感器测得两条下降曲线，其中一条压强几乎降至接近 0，另一条仅小幅下降。说明设置水对照实验的目的，并写出压强降得更多的曲线对应的化学方程式。","eye":"单测 NaOH 组压强下降不能直接证明发生了反应，因为 CO₂ 本身能溶于水且与水反应，必须靠等体积水做空白对照排除干扰！","method":"控制变量做对照，降压幅度差即为 NaOH 化学吸收的铁证。","steps":["第一步：注入等体积水的实验作对照，排除“CO₂ 溶于水及与水反应导致压强减小”的干扰。","第二步：注入 NaOH 溶液的曲线压强下降幅度远大于水组，且最终压强更低，说明 NaOH 溶液吸收了更多 CO₂，证明两者发生了化学反应。","第三步：写出化学方程式：2NaOH＋CO₂＝Na₂CO₃＋H₂O。"]},{"title":"高频变式：稀盐酸滴入 NaOH 溶液的 pH-温度联判","q":"向一定量 NaOH 溶液中逐滴加入稀盐酸，温度传感器显示滴加 10 mL 时温度最高，滴加 15 mL 时温度明显回落。问：滴加 5 mL、10 mL、15 mL 时溶液的 pH 分别与 7 有何关系？此时分别滴加无色酚酞各显什么颜色？","eye":"温度最高点（10 mL）就是恰好完全中和的界碑，小于 10 mL 碱过量，大于 10 mL 酸过量。","method":"以温度峰值体积为分界线，秒分三区间溶质、pH 与指示剂颜色。","steps":["第一步：滴加 5 mL（＜10 mL）：NaOH 未反应完，溶液呈碱性，pH＞7，滴加酚酞溶液变红色。","第二步：滴加 10 mL（温度最高点）：恰好完全中和生成 NaCl 和 H₂O，pH＝7，滴加酚酞呈无色。","第三步：滴加 15 mL（＞10 mL）：稀盐酸过量，溶液呈酸性，pH＜7，滴加酚酞仍呈无色（且溶质为 NaCl 和 HCl）。"]}]},"card":{"concept":["压强曲线破题：密闭容器中“放热或产气→压强增大，耗气或吸热→压强减小”。测氧实验（红磷燃烧）三段曲：先急升（燃烧放热影响大于耗氧）→再骤降（耗氧冷却至室温，压强低于大气压）→开止水夹回升（水倒吸恢复常压）。","酸碱中和 pH 与温度双曲线：向碱中滴酸 pH 从＞7 降至＜7，向酸中滴碱 pH 从＜7 升至＞7；酸碱中和放热，温度曲线的最高点恰好对应 pH＝7（完全中和点），之后继续滴加室温溶液温度下降。","高频俗名与八大沉淀速记：烧碱/火碱/苛性钠(NaOH)、纯碱/苏打(Na2CO3)、小苏打(NaHCO3)、生石灰(CaO)、熟石灰/消石灰(Ca(OH)2)、干冰(固体CO2)；沉淀：红褐 Fe(OH)3、蓝 Cu(OH)2，不溶于酸的白沉淀 BaSO4、AgCl，溶于酸且冒泡的 CaCO3、BaCO3，溶于酸不冒泡的 Mg(OH)2、Al(OH)3。"],"formula":["传感读图口诀：“起点定原液，拐点定恰反，峰值看放热，气压看温气！”"],"pitfall":["纯碱（Na2CO3）和小苏打（NaHCO3）名字带“碱”但都是盐！测氧实验压强先上升绝不是生成了气体，而是燃烧剧烈放热使气体热膨胀！"],"example":{"q":"如图为红磷测氧压强曲线和稀盐酸滴入 NaOH 溶液的 pH/温度曲线，为什么测氧初期压强不降反升？中和反应温度最高点对应的 pH 是多少？","a":"红磷燃烧虽消耗氧气，但放出大量热使瓶内气体受热膨胀，升温升压效应大于耗氧降压效应，故压强先升；酸碱中和放热，恰好完全中和时放热最多，温度最高点对应 pH＝7。","img":"./assets/knowledge/chemistry/sp/p13-sensor.svg"}},"qids":["kp-chemistry-sp-p13-01","kp-chemistry-sp-p13-02","kp-chemistry-sp-p13-03","kp-chemistry-sp-p13-04","kp-chemistry-sp-p13-05","kp-chemistry-sp-p13-06","kp-chemistry-sp-p13-07","kp-chemistry-sp-p13-08","kp-chemistry-sp-p13-09"],"refs":[]}]},{"id":"chemistry-sp-c4","name":"化学图像与综合计算压轴","unit":"专题·图像分析与综合计算","points":[{"id":"chemistry-sp-p10","name":"复分解反应先后顺序与沉淀/气体拐点图像","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["图像题横坐标为“加入某试剂质量”，纵坐标为“沉淀质量、气体质量或溶液 pH”，且曲线起点不在原点（在横轴上躺平一段后才上升）","题干出现向“酸＋盐”混合液滴加碱/碳酸盐，或向“碱＋碳酸盐”混合液滴加酸","要求判断曲线上 a、b、c、d 各点对应的溶质成分及拐点含义"],"steps":["第一步（背熟三大“优先反应”模型）：① HCl＋CuCl₂(或 FeCl₃/MgCl₂) 中滴 NaOH → 先中和 HCl（无沉淀），再产碱沉淀；② HCl＋CaCl₂ 中滴 Na₂CO₃ → 先与 HCl 产 CO₂（无沉淀），再产 CaCO₃↓；③ NaOH＋Na₂CO₃ 中滴稀盐酸 → 先中和 NaOH（无气泡），再与 Na₂CO₃ 产 CO₂↑。","第二步（抓四点拆三段）：看“起点（0）、折点1（前反应刚完）、折点2（后反应刚完）、平台段（试剂过量）”，记住一句话——“每过一个折点，刚被消耗的反应物清零，新生成物到位”。","第三步（关联 pH 阶梯图）：HCl＋CaCl₂ 滴 Na₂CO₃ 时，pH 呈“上升到 7（消耗 HCl）→ 保持 7 不变（生成 CaCO₃↓ 和中性 NaCl）→ 继续升至＞7（Na₂CO₃ 过量）”三段式。"],"variants":["变式1（无延迟例外！）：向 H₂SO₄＋CuSO₄ 混合液中滴加 Ba(OH)₂ 溶液 → 沉淀从原点立刻产生！因为 Ba²⁺ 与 SO₄²⁻ 生成不溶于酸的 BaSO₄↓，不受 H⁺ 干扰，不会延迟！","变式2（沉淀先升后降型）：向澄清石灰水 Ca(OH)₂ 中持续通 CO₂ 至过量，沉淀先增加（生 CaCO₃↓）后减少至 0（变可溶 Ca(HCO₃)₂）。","变式3（坐标纵轴换成“溶液总质量”或“溶剂质量”）：注意折点斜率变化——有气体或沉淀脱离溶液时斜率变缓，反应完继续加试剂斜率变陡（45°）。"],"parentGuide":{"ask":"往稀盐酸和氯化铜的混合液里滴氢氧化钠，为什么沉淀曲线不是从原点开始上升，而是先在横轴上走一段平路？","key":"孩子能讲清楚“因为中和优先（或者即使生成 Cu(OH)₂ 也会马上被盐酸溶解），必须先把盐酸消耗光，后面再滴 NaOH 才会长出蓝色沉淀”，而且知道如果换成 H₂SO₄＋Ba(OH)₂ 就不会延迟，就是顶尖水平。"},"examples":[{"title":"经典母题：酸＋盐滴碱的延迟沉淀图像","q":"向 HCl 和 CuCl₂ 的混合溶液中逐滴加入 NaOH 溶液，沉淀质量在 0→a 段为 0，a→b 段上升，b 点后水平。写出 a 点和 b 点的溶质，以及 b→c 段的溶液 pH 范围。","eye":"0→a 段中和 HCl，a 点 HCl 恰好清零；a→b 段沉淀 CuCl₂，b 点 CuCl₂ 恰好清零。","method":"第一折点“酸清零、盐尚全”，第二折点“盐清零、独留生成盐”。","steps":["第一步：0→a 段发生 NaOH＋HCl＝NaCl＋H₂O，到 a 点 HCl 耗尽，CuCl₂ 尚未开始反应，故 a 点溶质为 NaCl 和 CuCl₂。","第二步：a→b 段发生 2NaOH＋CuCl₂＝Cu(OH)₂↓＋2NaCl，到 b 点 CuCl₂ 耗尽，溶质只有 NaCl（pH＝7）。","第三步：b→c 段继续滴加的 NaOH 过量，溶质为 NaCl 和 NaOH，溶液显碱性（pH＞7）。"]},{"title":"高频变式：不溶于酸沉淀的“零延迟”陷阱","q":"向一定量稀硫酸和 MgSO₄ 的混合溶液中逐滴加入 Ba(OH)₂ 溶液，生成沉淀的质量随 Ba(OH)₂ 溶液质量变化的曲线起点是否在原点？请说明理由。","eye":"别机械背“有酸就延迟”！BaSO₄ 不溶于酸，一滴 Ba(OH)₂ 进去立刻出白沉淀！","method":"先看沉淀怕不怕酸：CaCO₃/Cu(OH)₂/Mg(OH)₂ 怕酸必延迟；BaSO₄/AgCl 不怕酸，起点必在原点！","steps":["第一步：曲线起点在原点（立刻产生沉淀）。","第二步：开始阶段发生 H₂SO₄＋Ba(OH)₂＝BaSO₄↓＋2H₂O，生成的 BaSO₄ 不溶于稀硫酸，故从 0 点起沉淀立刻增加。","第三步：待 H₂SO₄ 耗尽后，发生 MgSO₄＋Ba(OH)₂＝BaSO₄↓＋Mg(OH)₂↓（双沉淀，斜率更陡），直到 MgSO₄ 耗尽后沉淀保持不变。"]}]},"card":{"concept":["酸碱盐混合液滴加试剂“酸碱中和优先”铁律：① 向 HCl＋CuCl2（或 FeCl3/MgCl2）中滴加 NaOH → 先中和 HCl（无沉淀，起点延迟在横轴上！），HCl 耗尽后才生成 Cu(OH)2 沉淀！","② 向 HCl＋CaCl2 中滴加 Na2CO3 → 先与 HCl 反应产生 CO2 气体（无沉淀），HCl 耗尽后才生成 CaCO3 沉淀！","③ 向 NaOH＋Na2CO3 中滴加稀盐酸 → 先中和 NaOH（无气泡），NaOH 耗尽后才产生 CO2 气体！"],"formula":["图像三看：看起点（是否从原点出发）、看拐点（代表某反应恰好完全）、看平台（代表反应彻底结束）！"],"pitfall":["特例提醒：向 H2SO4＋HCl 中滴加 Ba(OH)2（或 BaCl2），由于 BaSO4 不溶于酸，白色沉淀会“立刻从原点（0 点）开始产生”，不会延迟！"],"example":{"q":"如图为向 HCl 和 CuCl2 混合溶液中逐滴加入 NaOH 溶液的沉淀质量变化曲线，ab 段和 bc 段分别发生什么反应？","a":"ab 段：NaOH＋HCl＝NaCl＋H2O（无沉淀）；bc 段：2NaOH＋CuCl2＝Cu(OH)2↓＋2NaCl。","img":"./assets/knowledge/chemistry/sp/p10-graph.svg"}},"qids":["kp-chemistry-sp-p10-01","kp-chemistry-sp-p10-02","kp-chemistry-sp-p10-03","kp-chemistry-sp-p10-04","kp-chemistry-sp-p10-05","kp-chemistry-sp-p10-06","kp-chemistry-sp-p10-07","kp-chemistry-sp-p10-08","kp-chemistry-sp-p10-09"],"refs":[]},{"id":"chemistry-sp-p11","name":"元素守恒法与差量法巧解化学计算","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["计算题涉及“多种同类物质混合”（如 FeO、Fe₂O₃、Fe₃O₄ 混合物，或 Na₂CO₃、K₂CO₃ 混合物），无法按单个方程式逐一求解","题干出现“经过多步复杂转化最终全部变为某单一产物”，但中间过程繁琐","题干给出“反应前总质量与反应后总质量”或“金属片浸入盐溶液取出烘干后增重/减重 Δm”"],"steps":["第一步（元素守恒掐头去尾）：锁定某核心元素（如 Fe、C、O、Cl），只要它从起点 100% 转移到终点，直接写守恒关系式（如 Fe₂O₃～2Fe～2FeSO₄，或 CO＋O(氧化物)→CO₂ 即 O～CO₂），跳过全部中间方程式！","第二步（差量法盯质量差 Δm）：① 固液产气：m(气体)＝m反应前总－m反应后总；② 气体还原氧化物：减少的固体质量 Δm＝氧化物中氧元素质量；③ 金属置换盐：固体质量差 Δm 与反应的金属/盐质量成正比。","第三步（平均值法/极值法判混合物组成）：两种金属与酸反应算“平均相对原子质量”（统一按＋2 价折算：Mg-24, Al-18, Fe-56, Zn-65, Cu-∞），混合结果必介于两者之间。"],"variants":["变式1（铁的多种氧化物混合还原）：无论 FeO、Fe₂O₃、Fe₃O₄ 比例如何，CO 还原减少的固体质量全是 O，生成 CO₂ 质量恒等于 m(O)×44/16。","变式2（金属片置换增重/减重）：Fe 片放入 CuSO₄ 溶液，56 g Fe 换出 64 g Cu，固体增重 8 g；Zn 片放入 CuSO₄ 溶液，65 g Zn 换出 64 g Cu，固体减重 1 g！","变式3（硫酸盐/碳酸盐混合物加酸求产气量）：若已知消耗 HCl 的质量，因每个 CO₃²⁻ 配 2H⁺ 生 1CO₂（2HCl～CO₂，73:44），根本不用管金属是 Na 还是 K 或 Ca，直接用 HCl 质量一步算出 CO₂！"],"parentGuide":{"ask":"题目给了 FeO、Fe₂O₃、Fe₃O₄ 三种氧化物混在一起，连各自多少克都不知道，怎么还能算出 CO 还原后生成了多少 CO₂？","key":"孩子能说出“不用分别列三个方程式！固体减少的质量就是氧元素质量，每夺走 1 个 O（16）就生成 1 个 CO₂（44），用氧质量乘 44/16 一步搞定”，就真正掌握了化学巧算思维。"},"examples":[{"title":"经典母题：铁的混合氧化物用差量＋氧守恒秒算 CO₂","q":"某 FeO、Fe₂O₃、Fe₃O₄ 混合物共 10 g，用足量 CO 高温完全还原后得纯铁 7.6 g。求反应生成 CO₂ 的质量。","eye":"三种氧化物未知比例，绝不能列三个方程式；抓“减重＝氧质量”＋“O～CO₂（16:44）”秒杀！","method":"差量求氧 → 16:44 换算 CO₂，两行出答案。","steps":["第一步：固体由铁的氧化物全部变为纯铁，减少的质量即为氧化物中氧元素质量：m(O)＝10 g－7.6 g＝2.4 g。","第二步：CO 夺取氧化物中 1 个 O 变为 1 个 CO₂（CO＋O→CO₂），对应质量关系 O ～ CO₂ 为 16 : 44。","第三步：m(CO₂)＝2.4 g × (44 / 16)＝6.6 g。"]},{"title":"高频变式：金属片浸入盐溶液固体差量法","q":"将一根洁净的铁丝浸入足量 CuSO₄ 溶液中，一段时间后取出、洗净、烘干，称得固体质量比原来增加了 0.8 g。求析出金属铜的质量（Fe-56，Cu-64）。","eye":"每溶解 56 份 Fe 就附着 64 份 Cu，固体净增重 8 份——直接把 Δm＝8 放进方程式下方列比例！","method":"方程下面加一列“固体质量差 Δm”，一步求出析出铜质量。","steps":["第一步：写方程式并列差量：Fe ＋ CuSO₄ ＝ FeSO₄ ＋ Cu   Δm(固增)。","第二步：标相对质量：Fe 为 56，Cu 为 64，Δm＝64－56＝8。","第三步：列比例 64/m(Cu)＝8/0.8 g，解得析出铜的质量 m(Cu)＝6.4 g（同时消耗铁 5.6 g）。"]}]},"card":{"concept":["元素守恒法（极速秒杀多步复杂反应！）：若某元素全部从反应物转移到最终产物中，无需写中间每一步方程式，直接列“元素质量相等”即可！","例：Fe2O3 经多步反应全部转化为 FeSO4，铁元素守恒：Fe2O3 ～ 2Fe ～ 2FeSO4。","差量法：固液反应放出气体时，m(气体)＝m反应前总－m反应后总；金属置换盐溶液时，固体质量差 Δm 与金属质量成正比！"],"formula":["守恒核心：某元素质量＝化合物质量×该元素质量分数，反应前后恒等！"],"pitfall":["使用元素守恒必须确认该元素“100% 全部转移”到目标产物中，没有损耗或分配到其他副产物！"],"example":{"q":"某 FeO、Fe2O3、Fe3O4 的混合物共 10 g，用足量 CO 高温完全还原后得到纯铁 7.2 g，求反应中生成的 CO2 中所含来自氧化物的氧元素质量。","a":"混合物只含铁和氧，氧元素全部被 CO 夺走，故 m(O)＝10－7.2＝2.8 g。"}},"qids":["kp-chemistry-sp-p11-01","kp-chemistry-sp-p11-02","kp-chemistry-sp-p11-03","kp-chemistry-sp-p11-04","kp-chemistry-sp-p11-05","kp-chemistry-sp-p11-06","kp-chemistry-sp-p11-07","kp-chemistry-sp-p11-08","kp-chemistry-sp-p11-09"],"refs":["national-fj-2026-chemistry-q18","national-jx-2026-chemistry-q20"]},{"id":"chemistry-sp-p12","name":"溶液反应后所得溶液溶质质量分数综合计算","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["中考最后一题压轴计算：固液或液液反应后，求“所得溶液（或滤液）中溶质的质量分数”","题干附带“样品含不溶性杂质”“原混合物里已有相同溶质（如 NaCl 和 Na₂CO₃ 混合加稀盐酸）”","结合实验数据表格（分多次加稀盐酸测剩余固体或生成气体）或折线图像求溶质质量分数"],"steps":["第一步（求纯量定溶质）：先用差量法或拐点数据求出气体/沉淀质量，代入配平的化学方程式求出生成的溶质质量 m(生)；若原样品中本来就含有同种可溶物（如原 NaCl），分子务必加上 m(原)！","第二步（质量守恒算分母）：反应后溶液总质量绝不能漏减任何脱离溶液的物质！牢记万能公式：m(溶液)＝反应前加入全部物质总质量－不溶性杂质－生成沉淀－生成气体（或＝参加反应的纯净固体＋加入的液体－气体－沉淀）。","第三步（代入计算并验算）：ω＝[m(溶质) / m(反应后溶液)]×100%，按题目要求保留小数位（通常精确到 0.1%），并检查最终数值是否在合理区间（如常见盐溶液多在 5%～30%）。"],"variants":["变式1（原混合物含同种溶质）：Na₂CO₃ 与 NaCl 固体混合物加稀盐酸反应后求 NaCl 质量分数 → 分子＝反应生成的 NaCl＋原有的 NaCl！（全班一半人会漏加原有 NaCl！）","变式2（多次加酸表格找完全反应点）：每次加 20 g 稀盐酸固体减少 5 g，最后一次只减少 2 g → 说明最后一次固体已耗尽，酸过量，须按前一次或总减少量找纯净物质量，切忌拿过量酸数据代算！","变式3（稀释配液衔接）：求完反应后溶质质量分数，再问“若加水稀释到 5%，需加水多少克”，用稀释前后溶质质量不变 m₁ω₁＝(m₁＋m水)ω₂ 即可。"],"parentGuide":{"ask":"算“反应后所得溶液的溶质质量分数”时，分子和分母各有一个最容易掉进去的大坑，分别是什么？","key":"孩子能精准答出“分母容易忘减不溶杂质、沉淀或气体；分子如果原混合物里本来就有同种溶质，容易忘加上原来的那部分”，就避开了压轴计算 90% 的失分点。"},"examples":[{"title":"经典母题：金属与酸反应后求溶质质量分数","q":"将 13 g 锌粒投入 100 g 稀硫酸中恰好完全反应（Zn-65，H₂SO₄-98，ZnSO₄-161，H₂-2），求反应后所得溶液的质量及溶质质量分数（精确到 0.1%）。","eye":"恰好完全反应无不溶杂质、无沉淀，分母只需减去逸出的 H₂ 质量！","method":"方程同求溶质与气体 → 总重减气得液重 → 相除乘 100%。","steps":["第一步：写方程式 Zn＋H₂SO₄＝ZnSO₄＋H₂↑，相对质量 Zn:65、ZnSO₄:161、H₂:2。","第二步：由 13 g Zn 算得 m(ZnSO₄)＝13×161/65＝32.2 g，m(H₂)＝13×2/65＝0.4 g。","第三步：反应后溶液质量＝13 g＋100 g－0.4 g＝112.6 g；溶质质量分数＝(32.2 g / 112.6 g)×100%≈28.6%。"]},{"title":"高频变式：含同种溶质混合物＋沉淀扣减双坑题","q":"将 20 g 含 NaCl 的 Na₂CO₃ 固体溶于 80 g 水中，加入 111 g CaCl₂ 溶液恰好完全反应，产生 10 g CaCO₃ 沉淀（Na₂CO₃-106，CaCO₃-100，NaCl-58.5）。求过滤后所得滤液中溶质的质量分数（精确到 0.1%）。","eye":"双坑齐发：① 分子必须＝生成的 NaCl＋原有的 NaCl；② 分母必须减去 10 g CaCO₃ 沉淀！","method":"沉淀反求碳酸钠与新盐 → 样品减碳酸钠得原盐 → 分子相加、分母减沉淀。","steps":["第一步：由 Na₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl，10 g CaCO₃ 对应参加反应的 Na₂CO₃ 为 10.6 g，新生成 NaCl 为 11.7 g。","第二步：原混合物中原有 NaCl＝20 g－10.6 g＝9.4 g，故滤液中总溶质 m(NaCl)＝11.7 g＋9.4 g＝21.1 g。","第三步：滤液总质量＝20 g＋80 g＋111 g－10 g＝201 g；溶质质量分数＝(21.1 g / 201 g)×100%≈10.5%。"]}]},"card":{"concept":["中考最后一道压轴大题终极模板：求反应后所得溶液的溶质质量分数 ω＝[m(溶质)/m(反应后溶液)]×100%！","最容易算错的分母 m(反应后溶液) 必须用“质量守恒减法”：m(反应后溶液)＝反应前所有加入物质总质量 － 难溶杂质质量 － 生成的沉淀质量 － 生成的气体质量！","若生成物就是原有溶质（如 Na2CO3＋CaCl2 混有原 NaCl），分子别忘了加上原有的那部分溶质！"],"formula":["m液后＝m加入总 － m不溶杂 － m↓ － m↑；ω＝(m质后/m液后)×100%。"],"pitfall":["计算反应后溶液质量时，千万别忘了减去“不溶于水的杂质质量”以及“逸出的气体或生成的沉淀质量”！"],"example":{"q":"将 13 g 锌粒投入 100 g 稀硫酸中恰好完全反应（Zn-65, H2SO4-98, ZnSO4-161, H2-2），求反应后所得溶液的质量及溶质质量分数。","a":"13 g Zn（0.2 份）生成 0.4 g H2 和 32.2 g ZnSO4；m液后＝13＋100－0.4＝112.6 g；ω＝32.2/112.6≈28.6%。"}},"qids":["kp-chemistry-sp-p12-01","kp-chemistry-sp-p12-02","kp-chemistry-sp-p12-03","kp-chemistry-sp-p12-04","kp-chemistry-sp-p12-05","kp-chemistry-sp-p12-06","kp-chemistry-sp-p12-07","kp-chemistry-sp-p12-08","kp-chemistry-sp-p12-09"],"refs":[]}]}],"questions":[{"id":"kp-chemistry-sp-p01-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p01-flow.svg","type":"single","stem":"如图粗盐精制除去 CaCl2、MgCl2、Na2SO4 的流程中，所加过量试剂的顺序错误的是（ ）","options":[{"key":"A","text":"Na2CO3 → BaCl2 → NaOH"},{"key":"B","text":"NaOH → BaCl2 → Na2CO3"},{"key":"C","text":"BaCl2 → Na2CO3 → NaOH"},{"key":"D","text":"BaCl2 → NaOH → Na2CO3"}],"answer":["A"],"explanation":"Na2CO3 必须在 BaCl2 之后加入才能除去过量 Ba²⁺，A 顺序错误。"},{"id":"kp-chemistry-sp-p01-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p01-flow.svg","type":"single","stem":"如图粗盐精制流程，向滤液中加入适量稀盐酸的作用是（ ）","options":[{"key":"A","text":"除去过量的 BaCl2"},{"key":"B","text":"除去过量的 NaOH 和 Na2CO3"},{"key":"C","text":"除去泥沙"},{"key":"D","text":"增加氯离子"}],"answer":["B"],"explanation":"过滤后滤液中含过量 NaOH 和 Na2CO3，加稀盐酸反应转化为 NaCl、H2O 和 CO2。"},{"id":"kp-chemistry-sp-p01-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（基础）","level":1,"kpFree":true,"type":"blank","stem":"粗盐精制加过量 BaCl2、NaOH、Na2CO3 充分反应后过滤，得到的滤渣中共有______种难溶沉淀。","blanks":[["4","四"]],"answer":["4"],"explanation":"沉淀共有 4 种：BaSO4、Mg(OH)2、CaCO3、BaCO3。"},{"id":"kp-chemistry-sp-p01-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"海水提镁流程：海水 → 加石灰乳沉淀 → 过滤 → 加稀盐酸溶解 → 浓缩结晶 → 电解熔融 MgCl2。加入石灰乳后生成的白色沉淀是（ ）","options":[{"key":"A","text":"CaCO3"},{"key":"B","text":"MgCO3"},{"key":"C","text":"Mg(OH)2"},{"key":"D","text":"BaSO4"}],"answer":["C"],"explanation":"MgCl2＋Ca(OH)2＝Mg(OH)2↓＋CaCl2。"},{"id":"kp-chemistry-sp-p01-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":false,"type":"single","stem":"工业上粗盐精制时，如果把“过滤”和“加稀盐酸”两个步骤颠倒，造成的后果是（ ）","options":[{"key":"A","text":"BaSO4 沉淀溶解"},{"key":"B","text":"NaCl 质量减少"},{"key":"C","text":"没有影响"},{"key":"D","text":"CaCO3、BaCO3 和 Mg(OH)2 沉淀重新溶解，除杂失败"}],"answer":["D"],"explanation":"碳酸盐和氢氧化物沉淀均溶于稀盐酸，会导致杂质离子重新进入溶液。"},{"id":"kp-chemistry-sp-p01-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（提高）","level":2,"kpFree":false,"type":"blank","stem":"在工业流程中，原料粉碎成细粉的目的是增大反应物之间的______，加快反应速率并使反应更充分。","blanks":[["接触面积"]],"answer":["接触面积"],"explanation":"固体粉碎可增大接触面积，提高反应速率和原料利用率。"},{"id":"kp-chemistry-sp-p01-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（拓展）","level":3,"kpFree":false,"type":"single","stem":"若将粗盐精制中的“加过量 NaOH 和 BaCl2”合二为一，改用一种过量试剂即可同时除去 Mg²⁺ 和 SO4²⁻，该试剂是（ ）","options":[{"key":"A","text":"Ba(OH)2"},{"key":"B","text":"Ca(OH)2"},{"key":"C","text":"K2CO3"},{"key":"D","text":"AgNO3"}],"answer":["A"],"explanation":"Ba(OH)2 提供 Ba²⁺ 沉淀 SO4²⁻、提供 OH⁻ 沉淀 Mg²⁺，且过量 Ba²⁺ 可被后续 Na2CO3 除去。"},{"id":"kp-chemistry-sp-p01-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（拓展）","level":3,"kpFree":false,"type":"single","stem":"海水提镁第一步将 MgCl2 转化为 Mg(OH)2 沉淀，第二步又加盐酸转回 MgCl2，看似多此一举，其实目的是（ ）","options":[{"key":"A","text":"产生氢气"},{"key":"B","text":"富集并提纯镁元素（将低浓度 MgCl2 从大量 NaCl 中分离出来）"},{"key":"C","text":"降低成本"},{"key":"D","text":"改变镁元素化合价"}],"answer":["B"],"explanation":"海水中 MgCl2 浓度极低且混有大量 NaCl，通过沉淀再溶解实现富集和提纯。"},{"id":"kp-chemistry-sp-p01-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p01","kp":"粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 粗盐除可溶性杂质（Ca²⁺/Mg²⁺/SO4²⁻）与海水提镁（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"工业工艺流程大题","stem":"粗盐中含有可溶性杂质 CaCl₂、MgCl₂、Na₂SO₄，精制流程如下：粗盐溶解 → 依次加入过量 BaCl₂ 溶液、过量 NaOH 溶液、过量 Na₂CO₃ 溶液 → 过滤 → 向滤液中加适量稀盐酸 → 蒸发结晶得精盐。（1）写出加入 Na₂CO₃ 溶液时发生的两个化学方程式；（2）向滤液中加适量稀盐酸的作用是什么？（3）为什么 Na₂CO₃ 溶液必须在 BaCl₂ 溶液之后加入？","score":10,"points":[{"text":"（1）CaCl₂＋Na₂CO₃＝CaCO₃↓＋2NaCl；BaCl₂＋Na₂CO₃＝BaCO₃↓＋2NaCl","score":4,"keys":["CaCO₃","CaCO3","BaCO₃","BaCO3"]},{"text":"（2）除去滤液中过量的 NaOH 和 Na₂CO₃（转化为 NaCl）","score":3,"keys":["NaOH","Na₂CO₃","Na2CO3","过量"]},{"text":"（3）Na₂CO₃ 可同时除去原杂质 Ca²⁺ 和前面过量的 Ba²⁺，若先加 Na₂CO₃ 则过量 BaCl₂ 无法除去，引入新杂质","score":3,"keys":["过量","Ba²⁺","BaCl₂","BaCl2","新杂质"]}],"method":"① 除杂试剂一一对应：BaCl₂ 除 SO₄²⁻，NaOH 除 Mg²⁺，Na₂CO₃ 同时除 Ca²⁺ 和过量 Ba²⁺；② 过滤后滤液里残留过量的 OH⁻ 和 CO₃²⁻，用稀盐酸一次中和成 NaCl、H₂O 和 CO₂；③ 试剂顺序唯一铁律：Na₂CO₃ 在 BaCl₂ 之后、稀盐酸在过滤之后。","sample":"解：（1）加入过量 Na₂CO₃ 溶液发生两个反应：\n① CaCl₂＋Na₂CO₃＝CaCO₃↓＋2NaCl；\n② BaCl₂＋Na₂CO₃＝BaCO₃↓＋2NaCl。\n（2）向滤液中加入适量稀盐酸的作用：除去滤液中过量的 NaOH 和 Na₂CO₃（得到纯净的 NaCl 溶液）。\n（3）原因：因为所加 BaCl₂ 是过量的，只有将 Na₂CO₃ 放在 BaCl₂ 之后加入，才能用 CO₃²⁻ 把过量的 Ba²⁺ 转化为 BaCO₃ 沉淀除去；若颠倒顺序，过量的 BaCl₂ 将无法除去，引入新的杂质。","explanation":"工艺流程常考加问：“蒸发结晶时盐酸稍过量有没有关系？”答：没关系，因为 HCl 易挥发，蒸发时会随水蒸气挥发除去。"},{"id":"national-js-suzhou-2026-chemistry-q23","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"js-suzhou-2026-chemistry","number":23,"section":"非选择题","chapter":"2026 年苏州中考化学","grade":"九下","stage":"9-down","source":"2026 年苏州中考化学 第 23 题","type":"essay","meta":"非选择题","material":"","stem":"（10 分）以某废酸（主要含 FeSO₄、H₂SO₄）为原料制磁性铁黑（Fe₃O₄）的流程：废酸 →（加碳酸钙）除酸 → 过滤 1（得滤渣）→（加熟石灰）沉铁 →（加 NaClO₃）氧化 → 过滤 2（得滤液）→ 磁选 → 磁性铁黑。已知：Fe(OH)₂、Fe(OH)₃ 难溶于水；CaSO₄ 微溶于水。\n(1) 若用 xFeO·yFe₂O₃ 表示 Fe₃O₄，则 x∶y＝______。\n(2)“除酸”步骤主要发生碳酸钙与 H₂SO₄ 的反应，充分反应后溶液 pH 约为 3。写出该反应的化学方程式：______。\n(3)“沉铁”步骤控制溶液 pH 在 8 左右，将 FeSO₄ 转化为 Fe(OH)₂。① FeSO₄ 与熟石灰反应的基本类型为______反应。② 熟石灰的作用除与 FeSO₄ 反应外，还有______。\n(4)“氧化”步骤发生两个反应：反应Ⅰ：6Fe(OH)₂＋NaClO₃＋3H₂O ═ 6Fe(OH)₃＋NaCl；反应Ⅱ：Fe(OH)₂＋2Fe(OH)₃ ═90 ℃═ Fe₃O₄＋4H₂O。溶液 pH 影响产品颜色与产率：pH 6.0 黄褐 43.9%；6.5 黄褐 50.6%；7.0 较黑 86.2%；7.5 很黑 93.0%；8.0 很黑 92.3%；9.0 灰黑 91.6%。① 该步骤最适宜的 pH 为______。② 保持最适宜的 pH，若增大“氧化”步骤 NaClO₃ 的用量（与理论用量相比），可提高磁性铁黑的产率。判断该说法是否合理，并说明理由：______。\n(5)“磁选”的目的是将 Fe₃O₄ 与其他杂质分离，该杂质主要为______。","points":[{"text":"(1) 1∶1","score":1,"keys":[]},{"text":"(2) CaCO₃＋H₂SO₄ ═ CaSO₄＋H₂O＋CO₂↑","score":2,"keys":[]},{"text":"(3)① 复分解","score":1,"keys":[]},{"text":"② 与残留的 H₂SO₄ 反应（或调节溶液 pH）","score":1,"keys":[]},{"text":"(4)① 7.5","score":1,"keys":[]},{"text":"② 否：NaClO₃ 增多，反应Ⅰ消耗的 Fe(OH)₂ 多、生成的 Fe(OH)₃ 多，参与反应Ⅱ的两者比例不当，产率下降","score":2,"keys":[]},{"text":"(5) CaSO₄","score":2,"keys":[]}],"score":10,"sample":"(1) 1∶1；(2) CaCO₃＋H₂SO₄ ═ CaSO₄＋H₂O＋CO₂↑；(3) ① 复分解；② 与残留的 H₂SO₄ 反应（或调节溶液 pH）；(4) ① 7.5；② 不合理。NaClO₃ 用量增大，反应Ⅰ消耗的 Fe(OH)₂ 多，生成的 Fe(OH)₃ 多，参与反应Ⅱ的 Fe(OH)₂ 与 Fe(OH)₃ 比例不当，磁性铁黑产率下降；(5) CaSO₄","method":"先写已知和所求，再列式计算，每一步写清依据，最后写结论。","answer":[],"explanation":"Fe₃O₄＝FeO·Fe₂O₃。除酸后 pH 约 3，仍有硫酸，熟石灰先中和它。反应Ⅱ需要 Fe(OH)₂∶Fe(OH)₃＝1∶2，氧化剂过量会把 Fe(OH)₂ 氧化得太多。CaSO₄ 微溶，会混在沉淀里，磁选把它分开。","kp":"工艺流程","image":"./assets/national/js-suzhou-2026-chemistry/q23.webp","kpId":"chemistry-sp-p01","kpRef":true},{"id":"national-jx-2026-chemistry-q17","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"jx-2026-chemistry","number":17,"section":"填空与说明题","chapter":"2026 年江西中考化学","grade":"九下","stage":"9-down","source":"2026 年江西中考化学 第 17 题","type":"essay","meta":"填空与说明题","material":"","stem":"（5 分）柠檬酸钙微溶于水，是一种安全的食品补钙剂。某学习小组以蛋壳为原料制备柠檬酸钙，主要过程：蛋壳（主要成分 CaCO₃）→ 研磨 → 蛋壳粉 →（加适量稀醋酸）操作① → 醋酸钙 (CH₃COO)₂Ca 溶液和滤渣；醋酸钙中加适量柠檬酸 → 过滤 → 柠檬酸钙（洗涤、干燥得产品）和物质 X。已知：醋酸的化学式为 CH₃COOH；柠檬酸与醋酸钙能发生复分解反应。\n(1) 研磨蛋壳的主要目的是______。\n(2) 将稀醋酸加入蛋壳粉中，反应生成醋酸钙、水和二氧化碳，该反应的化学方程式为______。\n(3) 进行操作①时，需使用的玻璃仪器有烧杯、玻璃棒和______。\n(4) 该实验中，可循环使用的物质是______。","points":[{"text":"(1) 增大反应物接触面积，加快反应速率","score":1,"keys":[]},{"text":"(2) 2CH₃COOH＋CaCO₃ ═ (CH₃COO)₂Ca＋CO₂↑＋H₂O","score":2,"keys":[]},{"text":"(3) 漏斗","score":1,"keys":[]},{"text":"(4) 稀醋酸","score":1,"keys":[]}],"score":5,"sample":"(1) 增大反应物接触面积，加快反应速率；(2) 2CH₃COOH＋CaCO₃ ═ (CH₃COO)₂Ca＋CO₂↑＋H₂O；(3) 漏斗；(4) 稀醋酸","method":"先写已知和所求，再列式计算，每一步写清依据，最后写结论。","answer":[],"explanation":"操作①把溶液和滤渣分开，是过滤。柠檬酸与醋酸钙复分解，生成柠檬酸钙和醋酸，物质 X 就是醋酸，可以回到第一步再用。","kp":"工艺流程","image":"./assets/national/jx-2026-chemistry/q17.webp","kpId":"chemistry-sp-p01","kpRef":true},{"id":"kp-chemistry-sp-p02-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"single","stem":"从含有 CuSO4 和 FeSO4 的工业废液中回收纯铜和绿矾（FeSO4·7H2O），第一步应向废液中加入过量的（ ）","options":[{"key":"A","text":"锌粉"},{"key":"B","text":"铜粉"},{"key":"C","text":"铁粉"},{"key":"D","text":"氢氧化钠"}],"answer":["C"],"explanation":"加过量铁粉把 Cu²⁺ 全部置换为 Cu，同时生成目标产物 FeSO4，不引入新杂质。"},{"id":"kp-chemistry-sp-p02-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"single","stem":"从含 CuSO4 和 FeSO4 的废液中加入过量铁粉充分反应后过滤，所得滤渣（含 Cu 和过量 Fe）应加入足量哪种试剂以得到纯净铜且滤液仍为 FeSO4（ ）","options":[{"key":"A","text":"硝酸银溶液"},{"key":"B","text":"水"},{"key":"C","text":"稀盐酸"},{"key":"D","text":"稀硫酸"}],"answer":["D"],"explanation":"稀硫酸与过量铁反应生成 FeSO4，既提纯了铜又回收了 FeSO4 溶液。"},{"id":"kp-chemistry-sp-p02-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（基础）","level":1,"kpFree":true,"type":"blank","stem":"在湿法炼铜工艺中，向铁矿废渣加稀硫酸浸出时，常常采取“搅拌”和“适当加热”的措施，目的是加快______。","blanks":[["反应速率","浸出速率"]],"answer":["反应速率"],"explanation":"搅拌与升温均可加快固液反应速率。"},{"id":"kp-chemistry-sp-p02-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某废旧电路板浸出液含 CuCl2、FeCl2，为回收金属铜并制取纯净 FeCl2 溶液，除过量铁粉时应选用的酸是（ ）","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"稀硫酸"},{"key":"C","text":"稀硝酸"},{"key":"D","text":"碳酸"}],"answer":["A"],"explanation":"目标溶质是 FeCl2，故选用稀盐酸避免引入 SO4²⁻ 杂质。"},{"id":"kp-chemistry-sp-p02-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":false,"type":"single","stem":"工业上用菱镁矿（主要含 MgCO3，杂质 SiO2 不溶于水也不溶于酸）制 MgSO4：先加过量稀硫酸酸浸再过滤，滤渣的主要成分是（ ）","options":[{"key":"A","text":"MgSO4"},{"key":"B","text":"SiO2"},{"key":"C","text":"MgCO3"},{"key":"D","text":"H2SO4"}],"answer":["B"],"explanation":"MgCO3 溶于稀硫酸生成可溶 MgSO4，不反应的 SiO2 留在滤渣中。"},{"id":"kp-chemistry-sp-p02-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（提高）","level":2,"kpFree":false,"type":"blank","stem":"工业上用含 AgNO3、Cu(NO3)2、Zn(NO3)2 的废液回收 Ag 和 Cu，先加过量铁粉过滤，则滤液中一定含有的两种溶质是 Zn(NO3)2 和______（填化学式）。","blanks":[["Fe(NO3)2"]],"answer":["Fe(NO3)2"],"explanation":"铁不能置换 Zn，能置换 Ag 和 Cu 并生成 Fe(NO3)2。"},{"id":"kp-chemistry-sp-p02-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（拓展）","level":3,"kpFree":false,"type":"single","stem":"从溶液中提取溶解度受温度变化影响较大的硫酸铜晶体，常用的结晶操作是（ ）","options":[{"key":"A","text":"加活性炭吸附"},{"key":"B","text":"直接过滤"},{"key":"C","text":"蒸发浓缩、降温结晶、过滤"},{"key":"D","text":"直接蒸干"}],"answer":["C"],"explanation":"蒸发浓缩、降温结晶可析出纯净大颗粒晶体且防止结晶水合物分解。"},{"id":"kp-chemistry-sp-p02-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（拓展）","level":3,"kpFree":false,"type":"single","stem":"工业流程中常把滤渣用蒸馏水“洗涤 2～3 次”，其主要目的是（ ）","options":[{"key":"A","text":"使滤渣溶解"},{"key":"B","text":"降低温度"},{"key":"C","text":"增加滤渣质量"},{"key":"D","text":"洗去滤渣表面附着的可溶性杂质离子"}],"answer":["D"],"explanation":"洗涤除去滤渣表面残留的母液杂质，提高产品纯度。"},{"id":"kp-chemistry-sp-p02-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p02","kp":"废液回收金属与矿石综合利用流程","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 废液回收金属与矿石综合利用流程（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"金属回收流程大题","stem":"某工厂废液中含有 CuSO₄、FeSO₄ 和少量 H₂SO₄，现回收金属铜并制得 FeSO₄ 晶体：向废液中加入过量铁粉，充分反应后过滤，得滤液 A 和滤渣 B；向滤渣 B 中加入适量稀硫酸，充分反应后过滤，得金属铜和滤液 C。（1）滤渣 B 的成分是什么？（2）写出向废液中加入过量铁粉时发生的两个化学方程式；（3）将滤液 A 和滤液 C 合并后，经什么操作可得到 FeSO₄ 晶体？","score":10,"points":[{"text":"（1）滤渣 B 含有 Cu 和过量的 Fe（铜和铁）","score":2,"keys":["Cu","Fe","铜","铁"]},{"text":"（2）Fe＋CuSO₄＝FeSO₄＋Cu；Fe＋H₂SO₄＝FeSO₄＋H₂↑","score":5,"keys":["FeSO₄＋Cu","FeSO4+Cu","H₂↑","H2"]},{"text":"（3）蒸发浓缩、降温结晶、过滤（或蒸发结晶）","score":3,"keys":["结晶","蒸发"]}],"method":"① 加过量铁粉目的：把废液中的 CuSO₄ 全部置换为 Cu，同时消耗掉 H₂SO₄，且只生成目标溶质 FeSO₄ 不引入新杂质；② 滤渣里一定含置换出的 Cu 和过量的 Fe，用稀硫酸溶解多余的 Fe（铜不与稀硫酸反应）；③ 合并后均为 FeSO₄ 溶液，蒸发浓缩、降温结晶即可。","sample":"解：（1）因为加入的铁粉是过量的，所以滤渣 B 的成分是：铜和铁（Cu、Fe）。\n（2）加入过量铁粉时发生的两个化学方程式：\n① Fe＋CuSO₄＝FeSO₄＋Cu；\n② Fe＋H₂SO₄＝FeSO₄＋H₂↑。\n（3）滤液 A 和滤液 C 均为 FeSO₄ 溶液，合并后经蒸发浓缩、降温结晶、过滤（洗涤、干燥）即可得到 FeSO₄ 晶体。","explanation":"阅卷提醒：第二问千万别漏写铁与废液中少量 H₂SO₄ 的反应，且气体符号 ↑ 必须标全！"},{"id":"kp-chemistry-sp-p03-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p03-carbon.svg","type":"single","stem":"如图“碳捕捉”工艺流程中，可以循环利用的两种物质是（ ）","options":[{"key":"A","text":"NaOH 和 CaO"},{"key":"B","text":"只有 NaOH"},{"key":"C","text":"CaCO3 和 Na2CO3"},{"key":"D","text":"CO2 和 H2O"}],"answer":["A"],"explanation":"反应室再生 NaOH 回捕捉室，煅烧炉再生 CaO 回反应室，两者循环利用。"},{"id":"kp-chemistry-sp-p03-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p03-carbon.svg","type":"single","stem":"如图碳捕捉室中，工业上常将 NaOH 溶液从塔顶以雾状“喷淋”而下，其主要目的是（ ）","options":[{"key":"A","text":"减少水蒸发"},{"key":"B","text":"增大气液接触面积，使 CO2 吸收更充分"},{"key":"C","text":"降低反应温度"},{"key":"D","text":"节约氢氧化钠"}],"answer":["B"],"explanation":"喷淋把液体分散成细小液滴，极大增大接触面积，提高吸收效率。"},{"id":"kp-chemistry-sp-p03-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（基础）","level":1,"kpFree":true,"type":"blank","stem":"在碳捕捉工艺的高温煅烧炉中，发生反应的化学方程式为 CaCO3＝(高温)CaO＋______↑。","blanks":[["CO2"]],"answer":["CO2"],"explanation":"高温煅烧碳酸钙生成氧化钙和二氧化碳。"},{"id":"kp-chemistry-sp-p03-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"我国科学家实现二氧化碳催化加氢制甲醇：CO2＋3H2＝(催化剂)CH3OH＋X，则 X 的化学式为（ ）","options":[{"key":"A","text":"O2"},{"key":"B","text":"CO"},{"key":"C","text":"H2O"},{"key":"D","text":"CH4"}],"answer":["C"],"explanation":"根据原子守恒，左 1C、2O、6H，右已有 1C、1O、4H，故 X 为 H2O。"},{"id":"kp-chemistry-sp-p03-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":false,"type":"single","stem":"碳捕捉工艺中，“反应室”内发生两个反应：CaO＋H2O＝Ca(OH)2 和 Ca(OH)2＋Na2CO3＝CaCO3↓＋2NaOH，将生成的 CaCO3 固体与 NaOH 溶液分离的操作是（ ）","options":[{"key":"A","text":"蒸发"},{"key":"B","text":"吸附"},{"key":"C","text":"蒸馏"},{"key":"D","text":"过滤"}],"answer":["D"],"explanation":"分离难溶固体和液体用过滤操作。"},{"id":"kp-chemistry-sp-p03-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（提高）","level":2,"kpFree":false,"type":"single","stem":"下列做法不利于推进“碳中和”目标的是（ ）","options":[{"key":"A","text":"大力新建燃煤火电厂替代水电"},{"key":"B","text":"推广新能源汽车和公共交通"},{"key":"C","text":"研发 CO2 捕集与资源化利用技术"},{"key":"D","text":"发展绿氢和风电光伏发电"}],"answer":["A"],"explanation":"燃煤电厂排放大量 CO2，违背减碳方向。"},{"id":"kp-chemistry-sp-p03-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（拓展）","level":3,"kpFree":false,"type":"blank","stem":"二氧化碳加氢制甲烷（CO2＋4H2＝CH4＋2H2O）中，若转化 44 t CO2，理论上需要消耗氢气______t（C-12, O-16, H-1）。","blanks":[["8"]],"answer":["8"],"explanation":"CO2∶4H2＝44∶8，故需 8 t 氢气。"},{"id":"kp-chemistry-sp-p03-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（拓展）","level":3,"kpFree":false,"type":"single","stem":"评价“NaOH 碳捕捉”工艺，其实际推广中面临的最大缺点是（ ）","options":[{"key":"A","text":"不能吸收 CO2"},{"key":"B","text":"高温煅烧 CaCO3 耗能大、成本高"},{"key":"C","text":"产品无用"},{"key":"D","text":"NaOH 难溶于水"}],"answer":["B"],"explanation":"高温分解 CaCO3 需要消耗大量能源，能耗偏高。"},{"id":"kp-chemistry-sp-p03-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p03","kp":"碳捕集、双碳工艺与物质循环利用","unit":"专题·工业工艺流程压轴","chapter":"专题与压轴 · 工业工艺流程压轴","source":"知识点精练 · 专题与压轴 · 碳捕集、双碳工艺与物质循环利用（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"工艺流程大题","stem":"为助力实现“碳达峰、碳中和”目标，某工厂设计了“碳捕捉”并合成绿色燃料甲醇（CH₃OH）的联合工艺流程：工业尾气中的 CO₂ 进入捕捉室，与喷淋的 NaOH 溶液反应生成 Na₂CO₃ 溶液；随后送入反应室加入 CaO，生成 CaCO₃ 沉淀和 NaOH 溶液；过滤所得 CaCO₃ 经高温煅烧炉分解生成 CaO 和高纯度 CO₂；高纯度 CO₂ 与绿氢（H₂）在催化剂作用下合成甲醇（CH₃OH）和水。（1）捕捉室中将 NaOH 溶液喷成雾状的目的是什么？写出捕捉室发生反应的化学方程式；（2）写出高温煅烧炉中发生反应的化学方程式，并写出整个“碳捕捉”流程中可循环利用的两种物质（填化学式）；（3）写出高纯度 CO₂ 与 H₂ 合成甲醇和水的化学方程式，并从“双碳”角度说出该联合工艺的一条重要意义。","score":10,"points":[{"text":"（1）增大气液接触面积，使 CO₂ 吸收更充分（加快吸收速率）；2NaOH＋CO₂＝Na₂CO₃＋H₂O","score":3,"keys":["接触面积","2NaOH","Na₂CO₃","CO₂"]},{"text":"（2）CaCO₃ ＝高温＝ CaO＋CO₂↑；可循环利用的物质为 NaOH 和 CaO","score":4,"keys":["高温","CO₂↑","NaOH","CaO"]},{"text":"（3）CO₂＋3H₂ ＝催化剂＝ CH₃OH＋H₂O；意义：减少 CO₂ 排放（减缓温室效应），同时实现碳资源化利用","score":3,"keys":["3H₂","CH₃OH","催化剂","温室效应"]}],"method":"① 工艺操作“喷雾/粉碎/搅拌”一律答“增大反应物接触面积，使反应更快更充分”；② 找循环物质看箭头回头——既是后续步骤生成物、又是前面步骤反应物的物质（NaOH 与 CaO）；③ 写未知有机反应方程式时直接根据题干给出的反应物、生成物和条件配平（CO₂＋3H₂→CH₃OH＋H₂O）。","sample":"解：（1）将 NaOH 溶液喷成雾状的目的：增大气液接触面积，使 CO₂ 被更快、更充分地吸收。\n捕捉室反应的化学方程式：2NaOH＋CO₂＝Na₂CO₃＋H₂O。\n（2）高温煅烧炉中反应的化学方程式：CaCO₃ ＝高温＝ CaO＋CO₂↑。\n整个“碳捕捉”流程中，捕捉室消耗的 NaOH 在反应室重新生成，反应室消耗的 CaO 在高温煅烧炉中重新生成，因此可循环利用的两种物质是 NaOH 和 CaO。\n（3）合成甲醇的化学方程式：CO₂＋3H₂ ＝催化剂＝ CH₃OH＋H₂O。\n重要意义：既能减少大气中 CO₂ 排放、减缓温室效应，又能将 CO₂ 转化为清洁燃料，实现碳的资源化利用。","explanation":"阅卷易错红线：① CaCO₃ 分解条件必须写“高温”不能写“加热（△）”，且不能漏标气体符号 ↑；② 题干要求填“化学式”时不能写成汉字名称；③ 合成甲醇方程式中 H₂ 前系数 3 和“催化剂”条件常被漏写。"},{"id":"kp-chemistry-sp-p04-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"type":"single","stem":"初中化学常见物质 A、B 组成元素完全相同，常温下均为无色液体，且 A 在 MnO2 催化下可分解生成 B 和气体 C，则 A、B 分别是（ ）","options":[{"key":"A","text":"HCl 和 H2SO4"},{"key":"B","text":"O2 和 O3"},{"key":"C","text":"H2O2 和 H2O"},{"key":"D","text":"CO2 和 CO"}],"answer":["C"],"explanation":"常温无色液体且元素相同，H2O2 分解生成 H2O 和 O2。"},{"id":"kp-chemistry-sp-p04-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p04-infer.svg","type":"single","stem":"如图钙三角转化中，A 为大理石主要成分，B 为常用食品干燥剂，C 可改良酸性土壤，则 B 转化为 C 的反应类型是（ ）","options":[{"key":"A","text":"置换反应"},{"key":"B","text":"复分解反应"},{"key":"C","text":"分解反应"},{"key":"D","text":"化合反应"}],"answer":["D"],"explanation":"CaO＋H2O＝Ca(OH)2，符合“多变一”化合反应。"},{"id":"kp-chemistry-sp-p04-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（基础）","level":1,"kpFree":true,"type":"blank","stem":"某红棕色固体粉末 A 在高温下与有毒气体 B 反应，生成黑色金属单质 C 和能使澄清石灰水变浑浊的气体 D，则红棕色粉末 A 的化学式为______。","blanks":[["Fe2O3"]],"answer":["Fe2O3"],"explanation":"3CO＋Fe2O3＝(高温)2Fe＋3CO2，红棕色固体为 Fe2O3。"},{"id":"kp-chemistry-sp-p04-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"黑色固体甲与黑色固体乙在高温下反应，生成红色金属单质丙和能灭火的气体丁，则甲、乙分别是（ ）","options":[{"key":"A","text":"C 和 CuO"},{"key":"B","text":"Fe3O4 和 MnO2"},{"key":"C","text":"Fe 和 CuO"},{"key":"D","text":"C 和 Fe2O3"}],"answer":["A"],"explanation":"C 和 CuO 均为黑色固体，高温生成红色 Cu 和 CO2（灭火）。"},{"id":"kp-chemistry-sp-p04-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":false,"type":"blank","stem":"A、B 为组成元素相同的无色气体，A 有剧毒且可用于冶炼金属，B 可用于光合作用，则 A 转化为 B 可通过燃烧，B 转化为 A 需与______（填化学式）在高温下反应。","blanks":[["C"]],"answer":["C"],"explanation":"CO2＋C＝(高温)2CO。"},{"id":"kp-chemistry-sp-p04-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（提高）","level":2,"kpFree":false,"type":"single","stem":"某蓝色溶液 X 与无色溶液 Y 反应生成蓝色沉淀和硫酸钠，则 X 和 Y 最可能是（ ）","options":[{"key":"A","text":"CuCl2 和 NaOH"},{"key":"B","text":"CuSO4 和 NaOH"},{"key":"C","text":"FeCl3 和 NaOH"},{"key":"D","text":"CuSO4 和 BaCl2"}],"answer":["B"],"explanation":"CuSO4＋2NaOH＝Cu(OH)2↓＋Na2SO4。"},{"id":"kp-chemistry-sp-p04-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某白色固体甲受热分解生成三种物质，其中一种是黑色固体乙（可作双氧水分解催化剂），一种是能使带火星木条复燃的气体丙，则白色或暗紫色固体甲应为高锰酸钾，黑色固体乙化学式为______。","blanks":[["MnO2"]],"answer":["MnO2"],"explanation":"2KMnO4＝(△)K2MnO4＋MnO2＋O2↑，催化剂乙是 MnO2。"},{"id":"kp-chemistry-sp-p04-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（拓展）","level":3,"kpFree":false,"type":"single","stem":"已知 A→B→C→A 为循环转化：A 是人体胃液中的酸，B 是蓝色溶液，C 是浅绿色溶液，下列推断合理的是（ ）","options":[{"key":"A","text":"A 为 HCl，B 为 FeCl3，C 为 CuCl2"},{"key":"B","text":"A 为 H2SO4，B 为 FeCl3，C 为 CuSO4"},{"key":"C","text":"A 为 HCl，B 为 CuCl2，C 为 FeCl2"},{"key":"D","text":"A 为 NaOH，B 为 CuSO4，C 为 FeSO4"}],"answer":["C"],"explanation":"HCl＋CuO→CuCl2(蓝)；CuCl2＋Fe→FeCl2(浅绿)。"},{"id":"kp-chemistry-sp-p04-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p04","kp":"题眼突破与初中常见“三角”转化框图推断","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 题眼突破与初中常见“三角”转化框图推断（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"框图推断压轴大题","stem":"A、B、C、D、E 是初中化学常见物质。已知 A 是大理石的主要成分，B、D 组成元素相同且均为无色气体，C 是黑色固体单质，E 俗称熟石灰。它们存在如下转化：A 高温分解生成 B 和一种氧化物；B 与 C 在高温下反应生成 D；B 与 E 反应生成 A 和水。（1）写出 A、B、C、D 的化学式；（2）写出 B 与 C 反应的化学方程式；（3）写出 B 与 E 反应的化学方程式，并说出该反应在实验室的常见用途。","score":10,"points":[{"text":"（1）A：CaCO₃，B：CO₂，C：C，D：CO","score":4,"keys":["CaCO₃","CaCO3","CO₂","CO2","CO"]},{"text":"（2）CO₂＋C ＝高温＝ 2CO","score":3,"keys":["高温","2CO"]},{"text":"（3）CO₂＋Ca(OH)₂＝CaCO₃↓＋H₂O；用途：检验二氧化碳气体","score":3,"keys":["Ca(OH)₂","Ca(OH)2","CaCO₃↓","检验"]}],"method":"① 抓四大“题眼”：大理石主要成分＝CaCO₃，组成元素相同的无色气体＝CO₂/CO，黑色固体单质＝C，熟石灰＝Ca(OH)₂；② 顺藤摸瓜代入所有转化逐一验通；③ 注意反应条件（高温）和沉淀符号（↓）。","sample":"解：（1）各物质化学式：A 为 CaCO₃，B 为 CO₂，C 为 C，D 为 CO。\n（2）B 与 C 在高温下反应的化学方程式：\nCO₂＋C ＝高温＝ 2CO（该反应为吸热反应）。\n（3）B 与 E 反应的化学方程式：\nCO₂＋Ca(OH)₂＝CaCO₃↓＋H₂O。\n在实验室中常利用该反应（澄清石灰水变浑浊）来检验二氧化碳气体。","explanation":"推断题防扣分三件事：看清问的是“名称”还是“化学式”、高温条件别漏写、CaCO₃ 沉淀符号 ↓ 别漏标。"},{"id":"kp-chemistry-sp-p05-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"在 pH＝13 的强碱性溶液中，下列各组离子能大量共存的是（ ）","options":[{"key":"A","text":"H⁺、Na⁺、NO3⁻"},{"key":"B","text":"NH4⁺、K⁺、Cl⁻"},{"key":"C","text":"Cu²⁺、Na⁺、SO4²⁻"},{"key":"D","text":"K⁺、Na⁺、NO3⁻、CO3²⁻"}],"answer":["D"],"explanation":"pH＝13 含大量 OH⁻，与 H⁺、NH4⁺、Cu²⁺ 均不能共存，只有 C 能共存。"},{"id":"kp-chemistry-sp-p05-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"在无色透明的溶液中，下列各组离子能大量共存的是（ ）","options":[{"key":"A","text":"Na⁺、K⁺、Cl⁻、NO3⁻"},{"key":"B","text":"Fe³⁺、K⁺、NO3⁻、Cl⁻"},{"key":"C","text":"Cu²⁺、Na⁺、SO4²⁻、Cl⁻"},{"key":"D","text":"Ba²⁺、Na⁺、SO4²⁻、NO3⁻"}],"answer":["A"],"explanation":"A 蓝色，B 黄色，D 生成 BaSO4 沉淀，只有 C 无色且互不反应。"},{"id":"kp-chemistry-sp-p05-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向某溶液中加入紫色石蕊试液显红色，则该溶液中一定不能大量存在的离子是（ ）","options":[{"key":"A","text":"SO4²⁻"},{"key":"B","text":"CO3²⁻"},{"key":"C","text":"Cl⁻"},{"key":"D","text":"Na⁺"}],"answer":["B"],"explanation":"石蕊变红说明含大量 H⁺，H⁺ 与 CO3²⁻ 反应生成 CO2 和 H2O 不能共存。"},{"id":"kp-chemistry-sp-p05-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某工厂废水中含有大量 Ba²⁺、Cl⁻、NO3⁻，现需加入一种物质使 Ba²⁺ 沉淀，且不能引入难以共存的 Ag⁺，应选用的离子是（ ）","options":[{"key":"A","text":"Na⁺"},{"key":"B","text":"K⁺"},{"key":"C","text":"SO4²⁻（如 Na2SO4）"},{"key":"D","text":"H⁺"}],"answer":["C"],"explanation":"Ba²⁺ 与 SO4²⁻ 生成难溶 BaSO4 沉淀。"},{"id":"kp-chemistry-sp-p05-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"将甲、乙两种各含两种不同离子的澄清溶液混合，若甲含 Ag⁺、NO3⁻，则乙中一定不可能含有的离子是（ ）","options":[{"key":"A","text":"Mg²⁺"},{"key":"B","text":"K⁺"},{"key":"C","text":"Na⁺"},{"key":"D","text":"Cl⁻"}],"answer":["D"],"explanation":"Ag⁺ 与 Cl⁻ 结合生成白色 AgCl 沉淀。"},{"id":"kp-chemistry-sp-p05-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"在含有大量 H⁺、Na⁺、Cl⁻ 的溶液中，还可以大量共存的离子是（ ）","options":[{"key":"A","text":"Mg²⁺"},{"key":"B","text":"OH⁻"},{"key":"C","text":"HCO3⁻"},{"key":"D","text":"Ag⁺"}],"answer":["A"],"explanation":"H⁺ 排斥 OH⁻ 和 HCO3⁻，Cl⁻ 排斥 Ag⁺，只有 Mg²⁺ 可以共存。"},{"id":"kp-chemistry-sp-p05-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某无色溶液可能含 Na⁺、Cu²⁺、Ba²⁺、SO4²⁻、CO3²⁻ 中的几种，先由“无色”直接排除______（填离子符号）。","blanks":[["Cu²⁺","Cu2+","Cu^2⁺"]],"answer":["Cu²⁺"],"explanation":"Cu²⁺ 在水溶液中呈蓝色，无色溶液必不含 Cu²⁺。"},{"id":"kp-chemistry-sp-p05-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"向某待测液中先加足量稀硝酸无气泡，再滴加硝酸钡溶液产生白色沉淀，说明原溶液中一定含有（ ）","options":[{"key":"A","text":"OH⁻"},{"key":"B","text":"SO4²⁻"},{"key":"C","text":"Cl⁻"},{"key":"D","text":"CO3²⁻"}],"answer":["B"],"explanation":"加稀硝酸排除了 CO3²⁻ 干扰，再加 Ba(NO3)2 产生不溶于稀硝酸的白色沉淀必为 BaSO4，证明含 SO4²⁻。"},{"id":"kp-chemistry-sp-p05-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p05","kp":"酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 酸碱盐隐含条件（无色/pH/气体沉淀）离子共存压轴（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"离子共存探究大题","stem":"某工厂排出的无色透明废液中，可能含有 H⁺、Na⁺、Cu²⁺、Ba²⁺、CO₃²⁻、SO₄²⁻、Cl⁻ 中的几种离子。环保小组进行了如下三步检验：① 测得该无色透明废液的 pH＝1；② 取少量废液滴加适量 BaCl₂ 溶液，立即产生大量白色沉淀，静置过滤；③ 向步骤②所得滤液中滴加 AgNO₃ 溶液和稀硝酸，又产生白色沉淀。（1）仅根据“无色透明”和“pH＝1”，可直接排除原废液中的哪两种离子？请分别说明理由；（2）根据步骤②判断原废液中一定含有哪种离子、一定不含哪种离子，并写出 H₂SO₄ 与 BaCl₂ 反应的化学方程式；（3）仅凭步骤③能否确定原废液中一定含有 Cl⁻？请说明理由，并写出改进步骤②应选用的试剂名称或化学式。","score":10,"points":[{"text":"（1）排除 Cu²⁺（含 Cu²⁺ 溶液呈蓝色，与无色矛盾）和 CO₃²⁻（pH＝1 含大量 H⁺，H⁺ 与 CO₃²⁻ 反应生成 CO₂↑ 和 H₂O 不能共存）","score":4,"keys":["Cu²⁺","蓝色","CO₃²⁻","H⁺"]},{"text":"（2）一定含有 SO₄²⁻，一定不含 Ba²⁺；H₂SO₄＋BaCl₂＝BaSO₄↓＋2HCl","score":3,"keys":["SO₄²⁻","Ba²⁺","BaSO₄↓","2HCl"]},{"text":"（3）不能确定；因为步骤②加入的 BaCl₂ 溶液引入了 Cl⁻，会干扰原废液中 Cl⁻ 的检验；应将 BaCl₂ 改为 Ba(NO₃)₂（硝酸钡）溶液","score":3,"keys":["不能","引入","Cl⁻","Ba(NO₃)₂"]}],"method":"① 先挖题干隐含条件：“无色”排有色离子（Cu²⁺ 蓝），“pH＝1”隐含大量 H⁺，立刻排除与 H⁺ 反应生气体/水的 CO₃²⁻；② 步骤②在强酸性下加 BaCl₂ 产白沉淀，沉淀必为不溶于酸的 BaSO₄，故一定含 SO₄²⁻，由离子不共存反推一定不含 Ba²⁺；③ 查试剂干扰：步骤②加入的 BaCl₂ 本身带入了 Cl⁻，必须换成 Ba(NO₃)₂ 才能续检 Cl⁻。","sample":"解：（1）可直接排除 Cu²⁺ 和 CO₃²⁻。\n理由：① 含 Cu²⁺ 的溶液呈蓝色，而原废液无色透明，故一定不含 Cu²⁺；② pH＝1 说明溶液中含有大量 H⁺，H⁺ 与 CO₃²⁻ 会结合生成水和二氧化碳气体，不能大量共存，故一定不含 CO₃²⁻。\n（2）步骤②在强酸性条件下加入 BaCl₂ 溶液产生白色沉淀，该沉淀为不溶于酸的 BaSO₄，因此原废液中一定含有 SO₄²⁻；由于 Ba²⁺ 与 SO₄²⁻ 会生成 BaSO₄ 沉淀不能共存，故原废液中一定不含 Ba²⁺。\n化学方程式：H₂SO₄＋BaCl₂＝BaSO₄↓＋2HCl。\n（3）不能确定。理由：步骤②滴加的 BaCl₂ 溶液中本身含有 Cl⁻，向滤液中引入了新 Cl⁻，因此步骤③产生 AgCl 白色沉淀不能证明原废液中含 Cl⁻。\n改进方案：将步骤②中的 BaCl₂ 溶液改用 Ba(NO₃)₂（硝酸钡）溶液。","explanation":"阅卷易错红线：① 离子符号电荷数与正负号位置写反（如写成 Cu⁺²、SO₄⁻²）直接扣分；② H₂SO₄＋BaCl₂ 方程式漏标 BaSO₄↓ 或忘记配平 2HCl；③ 只答“不能”未点出“BaCl₂ 引入了 Cl⁻ 造成干扰”扣分。"},{"id":"kp-chemistry-sp-p06-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 的混合溶液中加入一定量锌粉，充分反应后过滤，滤渣中一定含有的金属是（ ）","options":[{"key":"A","text":"Zn"},{"key":"B","text":"Cu"},{"key":"C","text":"Ag"},{"key":"D","text":"Ag 和 Cu"}],"answer":["C"],"explanation":"Zn 最先置换出最不活泼的 Ag，无论锌量多少，滤渣必含 Ag。"},{"id":"kp-chemistry-sp-p06-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 混合溶液中加入一定量铁粉，过滤后向滤液中滴加稀盐酸产生白色沉淀，则滤渣的成分是（ ）","options":[{"key":"A","text":"只有 Cu"},{"key":"B","text":"Ag 和 Cu"},{"key":"C","text":"Ag、Cu 和 Fe"},{"key":"D","text":"只有 Ag"}],"answer":["D"],"explanation":"加盐酸产生 AgCl 白沉淀说明 AgNO3 还有剩余，故 Cu(NO3)2 尚未反应，滤渣只有 Ag。"},{"id":"kp-chemistry-sp-p06-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（基础）","level":1,"kpFree":true,"type":"single","stem":"向 AgNO3 和 Cu(NO3)2 混合液加铁粉过滤，若滤液呈蓝色，则滤渣中一定不含有的金属是（ ）","options":[{"key":"A","text":"Fe"},{"key":"B","text":"Cu"},{"key":"C","text":"Ag"},{"key":"D","text":"无法判断"}],"answer":["A"],"explanation":"滤液呈蓝色说明含 Cu²⁺，只要溶液还有 Cu²⁺ 就不可能剩余铁粉（Fe 会继续与 Cu²⁺ 反应）。"},{"id":"kp-chemistry-sp-p06-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向 AgNO3、Cu(NO3)2 和 Mg(NO3)2 的混合溶液中加入过量铁粉，充分反应后过滤，滤液中含有的溶质是（ ）","options":[{"key":"A","text":"只有 Fe(NO3)2"},{"key":"B","text":"Fe(NO3)2 和 Mg(NO3)2"},{"key":"C","text":"Cu(NO3)2 和 Mg(NO3)2"},{"key":"D","text":"Mg(NO3)2"}],"answer":["B"],"explanation":"Fe 比 Mg 弱不能置换 Mg(NO3)2，过量铁把 Ag⁺、Cu²⁺ 全换完，故滤液含 Fe(NO3)2 和 Mg(NO3)2。"},{"id":"kp-chemistry-sp-p06-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":false,"type":"blank","stem":"将一定量锌粉投入 Cu(NO3)2 和 AgNO3 混合液中，充分反应后过滤，若测得滤渣质量小于加入锌粉的质量，该情况______（填“可能”或“不可能”）发生。","blanks":[["可能"]],"answer":["可能"],"explanation":"Zn(65)换Cu(64)固体质量减轻，Zn(65)换2Ag(216)固体增重；若换出的 Cu 足够多而 Ag 很少，总质量可减轻。"},{"id":"kp-chemistry-sp-p06-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（提高）","level":2,"kpFree":false,"type":"single","stem":"向含 Cu(NO3)2 和 AgNO3 的混合液中加入一定量铁粉，充分反应后发现溶液质量比反应前减轻了，这是因为主要发生了（ ）","options":[{"key":"A","text":"蒸发水分"},{"key":"B","text":"Fe＋Cu(NO3)2＝Fe(NO3)2＋Cu"},{"key":"C","text":"Fe＋2AgNO3＝Fe(NO3)2＋2Ag（56 份铁换 216 份银，溶液变轻）"},{"key":"D","text":"铁与水反应"}],"answer":["C"],"explanation":"每 56 份 Fe 进溶液换出 216 份 Ag，溶液质量显著减轻。"},{"id":"kp-chemistry-sp-p06-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"向 Cu(NO3)2、AgNO3 混合液中加入一定量铁粉，过滤后向滤渣滴加稀盐酸有气泡产生，则滤液中含有的金属阳离子只有（ ）","options":[{"key":"A","text":"Ag⁺"},{"key":"B","text":"Cu²⁺"},{"key":"C","text":"Fe³⁺"},{"key":"D","text":"Fe²⁺"}],"answer":["D"],"explanation":"滤渣加盐酸有气泡说明铁粉过量，Ag⁺ 和 Cu²⁺ 均被彻底置换，滤液只剩 Fe²⁺。"},{"id":"kp-chemistry-sp-p06-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（拓展）","level":3,"kpFree":false,"type":"single","stem":"将铁粉和铜粉的混合物投入足量 AgNO3 溶液中，充分反应后过滤，滤渣中含有的金属是（ ）","options":[{"key":"A","text":"只有 Ag"},{"key":"B","text":"只有 Cu"},{"key":"C","text":"Ag、Cu 和 Fe"},{"key":"D","text":"Ag 和 Cu"}],"answer":["A"],"explanation":"AgNO3 足量，Fe 和 Cu 均排在 Ag 前面，会全部反应完，滤渣只有 Ag。"},{"id":"kp-chemistry-sp-p06-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p06","kp":"金属与混合盐溶液滤渣滤液成分压轴","unit":"专题·框图推断与离子共存","chapter":"专题与压轴 · 框图推断与离子共存压轴","source":"知识点精练 · 专题与压轴 · 金属与混合盐溶液滤渣滤液成分压轴（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"金属滤渣滤液压轴","stem":"向含有 AgNO₃ 和 Cu(NO₃)₂ 的混合溶液中加入一定量铁粉，充分反应后过滤，得到滤渣和滤液。（1）写出最先发生的化学方程式；（2）若向滤渣中滴加稀盐酸有气泡产生，请判断滤渣的成分和滤液中的溶质；（3）若观察到滤液呈蓝色，判断滤渣中一定有什么、可能有什么？","score":10,"points":[{"text":"（1）最先发生：Fe＋2AgNO₃＝Fe(NO₃)₂＋2Ag","score":3,"keys":["2AgNO₃","2AgNO3","Fe(NO₃)₂","2Ag"]},{"text":"（2）有气泡说明铁过量：滤渣含 Ag、Cu、Fe；滤液溶质只有 Fe(NO₃)₂","score":4,"keys":["Ag","Cu","Fe","Fe(NO₃)₂","Fe(NO3)2"]},{"text":"（3）滤液呈蓝色说明含 Cu(NO₃)₂：滤渣中一定有 Ag，可能有 Cu（一定没有 Fe）","score":3,"keys":["一定有Ag","一定有 Ag","可能有Cu","可能有 Cu"]}],"method":"① 遵循“远距离先置换”原则：活动性 Fe＞Cu＞Ag，Fe 先与 AgNO₃ 反应，AgNO₃ 耗尽后再与 Cu(NO₃)₂ 反应；② 滤渣加盐酸有气泡→必含过量 Fe→两种盐都被完全置换；③ 滤液呈蓝色→含 Cu(NO₃)₂→Fe 一定完全耗尽，Cu 可能部分置换出也可能尚未置换。","sample":"解：（1）在金属活动性顺序中 Fe＞Cu＞Ag，铁先与活动性最弱的银的盐溶液反应：\nFe＋2AgNO₃＝Fe(NO₃)₂＋2Ag。\n（2）向滤渣中滴加稀盐酸有气泡产生，说明滤渣中含有过量的铁粉，原溶液中的 AgNO₃ 和 Cu(NO₃)₂ 均已完全反应。\n因此，滤渣成分为 Ag、Cu、Fe；滤液中的溶质只有 Fe(NO₃)₂。\n（3）滤液呈蓝色，说明滤液中含有 Cu(NO₃)₂，则铁粉一定已完全反应。\n由于铁先置换出银，再置换铜（可能刚好耗尽在第一步，也可能部分置换了铜），\n故滤渣中一定有 Ag，可能有 Cu，一定没有 Fe。","explanation":"经典易错点：铁与盐溶液发生置换反应生成的都是亚铁盐 Fe(NO₃)₂，千万不能写成 Fe(NO₃)₃！"},{"id":"national-js-suzhou-2026-chemistry-q19","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"js-suzhou-2026-chemistry","number":19,"section":"单项选择","chapter":"2026 年苏州中考化学","grade":"九下","stage":"9-down","source":"2026 年苏州中考化学 第 19 题","type":"single","options":[{"key":"A","text":"CaO →(H₂O) Ca(OH)₂"},{"key":"B","text":"Fe₂O₃ →(稀盐酸) FeCl₃"},{"key":"C","text":"Ag →(MgSO₄ 溶液) Mg"},{"key":"D","text":"Zn →(稀硫酸) ZnSO₄"}],"answer":["C"],"explanation":"银的活动性比镁弱，不能把镁从它的盐溶液中置换出来。","kp":"金属活动性顺序","stem":"在给定条件下，下列选项所示的物质转化【不能】实现的是（ ）","paperScore":2,"kpId":"chemistry-sp-p06","kpRef":true},{"id":"kp-chemistry-sp-p07-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"type":"single","stem":"检验一瓶久置的氢氧化钠溶液是否已经变质，下列试剂中不能使用的是（ ）","options":[{"key":"A","text":"过量稀盐酸"},{"key":"B","text":"无色酚酞溶液"},{"key":"C","text":"澄清石灰水"},{"key":"D","text":"氯化钙溶液"}],"answer":["B"],"explanation":"NaOH 和变质生成的 Na2CO3 溶液都呈碱性，都能使酚酞变红，故酚酞无法判断是否变质。"},{"id":"kp-chemistry-sp-p07-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p07-naoh.svg","type":"single","stem":"如图探究久置 NaOH 溶液是“部分变质”还是“完全变质”时，第一步加入过量 CaCl2 溶液后产生白色沉淀，静置取上层清液滴加酚酞溶液变红，说明该 NaOH 溶液（ ）","options":[{"key":"A","text":"无法判断"},{"key":"B","text":"完全变质"},{"key":"C","text":"部分变质"},{"key":"D","text":"没有变质"}],"answer":["C"],"explanation":"白沉淀说明含 Na2CO3（已变质），除尽 Na2CO3 后清液仍使酚酞变红说明还含 NaOH，故为部分变质。"},{"id":"kp-chemistry-sp-p07-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p07-naoh.svg","type":"single","stem":"如图实验第一步中，不能用过量 Ca(OH)2 溶液代替过量 CaCl2 溶液的原因是（ ）","options":[{"key":"A","text":"Ca(OH)2 价格太贵"},{"key":"B","text":"会产生气体"},{"key":"C","text":"Ca(OH)2 不与 Na2CO3 反应"},{"key":"D","text":"Ca(OH)2 与 Na2CO3 反应会生成新的 NaOH（且自身显碱性），干扰原 NaOH 的检验"}],"answer":["D"],"explanation":"生成新 NaOH 且过量 Ca(OH)2 也会使酚酞变红，无法确定原样品是否含 NaOH。"},{"id":"kp-chemistry-sp-p07-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"若要除去 NaOH 溶液中混有的少量 Na2CO3 杂质以提纯 NaOH，应选用的试剂是（ ）","options":[{"key":"A","text":"适量氢氧化钙溶液，再过滤"},{"key":"B","text":"二氧化碳"},{"key":"C","text":"适量稀盐酸"},{"key":"D","text":"适量氯化钙溶液"}],"answer":["A"],"explanation":"Na2CO3＋Ca(OH)2＝CaCO3↓＋2NaOH，过滤即可得纯净 NaOH 溶液；用 CaCl2 会引入 NaCl 杂质。"},{"id":"kp-chemistry-sp-p07-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":false,"type":"blank","stem":"检验 NaOH 溶液是否变质时，若滴加的稀盐酸量太少，可能观察不到气泡，因为稀盐酸先与未变质的______发生中和反应。","blanks":[["NaOH","氢氧化钠"]],"answer":["NaOH"],"explanation":"酸碱中和优先于酸与碳酸盐反应，必须加足量/过量稀盐酸。"},{"id":"kp-chemistry-sp-p07-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（提高）","level":2,"kpFree":false,"type":"single","stem":"一包久置的生石灰（CaO）食品干燥剂，加水搅拌后放出大量热，过滤后向滤渣滴加稀盐酸产生气泡，说明该干燥剂中一定含有（ ）","options":[{"key":"A","text":"只有 CaO"},{"key":"B","text":"CaO 和 CaCO3（可能还含 Ca(OH)2）"},{"key":"C","text":"只有 CaCO3"},{"key":"D","text":"只有 Ca(OH)2"}],"answer":["B"],"explanation":"加水放大量热说明含 CaO；滤渣加酸产气说明含 CaCO3。"},{"id":"kp-chemistry-sp-p07-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（拓展）","level":3,"kpFree":false,"type":"single","stem":"在“探究 NaOH 变质程度”第二步中，向除尽 Na2CO3 后的上层清液中，还可以滴加哪种试剂来代替酚酞检验 NaOH 的存在（ ）","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"氯化钡溶液"},{"key":"C","text":"硫酸铜溶液（看是否产生蓝色沉淀）"},{"key":"D","text":"氯化钠溶液"}],"answer":["C"],"explanation":"CuSO4 与 NaOH 反应生成蓝色 Cu(OH)2 沉淀，可证明 OH⁻ 存在。"},{"id":"kp-chemistry-sp-p07-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"为防止氢氧化钠和生石灰在空气中变质，实验室必须______保存。","blanks":[["密封"]],"answer":["密封"],"explanation":"隔绝空气中的水蒸气和二氧化碳。"},{"id":"kp-chemistry-sp-p07-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p07","kp":"氢氧化钠与生石灰变质程度探究（未变/部分/完全）","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 氢氧化钠与生石灰变质程度探究（未变/部分/完全）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"变质程度实验探究","stem":"实验室有一瓶敞口放置一段时间的 NaOH 溶液，同学们探究其变质情况。（1）写出 NaOH 溶液在空气中变质的化学方程式；（2）关于该溶液的变质程度，有哪三种合理猜想？（3）请设计实验证明该溶液为“部分变质”（写出步骤、试剂、现象和结论），并说明为什么不能用 Ca(OH)₂ 溶液代替 CaCl₂ 溶液。","score":10,"points":[{"text":"（1）2NaOH＋CO₂＝Na₂CO₃＋H₂O","score":2,"keys":["2NaOH","Na₂CO₃","Na2CO3"]},{"text":"（2）三种猜想：未变质（只有 NaOH）、部分变质（NaOH 和 Na₂CO₃）、完全变质（只有 Na₂CO₃）","score":2,"keys":["未变质","部分变质","完全变质"]},{"text":"（3）取样加过量 CaCl₂（或 BaCl₂）溶液产生白色沉淀（证含 Na₂CO₃ 并除尽），静置取清液滴酚酞变红（证含 NaOH）","score":4,"keys":["过量","CaCl₂","BaCl₂","白色沉淀","酚酞","变红"]},{"text":"不能用 Ca(OH)₂ 原因：Ca(OH)₂ 与 Na₂CO₃ 反应会生成 NaOH（引入 OH⁻），干扰原溶液中 NaOH 的检验","score":2,"keys":["生成NaOH","生成 NaOH","OH⁻","干扰"]}],"method":"① 检验部分变质＝同时证明“含 Na₂CO₃”和“含 NaOH”；② 关键难点：Na₂CO₃ 溶液也显碱性，会干扰 NaOH 检验！必须先加过量中性钙盐/钡盐（CaCl₂ 或 BaCl₂）把 CO₃²⁻ 彻底沉淀除尽，再用酚酞测上层清液是否仍显碱性；③ 不能加 Ca(OH)₂ 是因为反应会生成新的 NaOH 造成干扰。","sample":"解：（1）2NaOH＋CO₂＝Na₂CO₃＋H₂O。\n（2）三种猜想：\n① 未变质：溶质只有 NaOH；\n② 部分变质：溶质为 NaOH 和 Na₂CO₃；\n③ 完全变质：溶质只有 Na₂CO₃。\n（3）实验方案：\n取少量待测液于试管中，加入过量的 CaCl₂（或 BaCl₂）溶液，观察到有白色沉淀产生，证明含有 Na₂CO₃（且将 CO₃²⁻ 完全除去）；\n静置（或过滤）后，向上层清液中滴加无色酚酞溶液，溶液变红，证明含有 NaOH。\n由此得出结论：该 NaOH 溶液部分变质。\n不能用 Ca(OH)₂ 代替 CaCl₂ 的原因：Ca(OH)₂＋Na₂CO₃＝CaCO₃↓＋2NaOH，会生成新的 NaOH（且自身含 OH⁻），无法判断原溶液中是否含有 NaOH。","explanation":"阅卷必查的两个字：“过量”！写 CaCl₂ 溶液时如果不写“过量（或足量）”，无法保证 CO₃²⁻ 除尽，必扣 1～2 分。"},{"id":"kp-chemistry-sp-p08-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"将稀盐酸与氢氧化钠溶液混合反应后，想检验反应后溶液中稀盐酸是否过量，下列试剂不可行的是（ ）","options":[{"key":"A","text":"碳酸钠溶液"},{"key":"B","text":"锌粒"},{"key":"C","text":"紫色石蕊溶液"},{"key":"D","text":"硝酸银溶液"}],"answer":["D"],"explanation":"生成物 NaCl 中也含有 Cl⁻，无论盐酸是否过量，滴加 AgNO3 都会产生 AgCl 白沉淀！"},{"id":"kp-chemistry-sp-p08-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"向澄清石灰水中加入一定量碳酸钠溶液，充分反应后过滤。关于滤液中溶质成分的下列猜想，一定不合理的是（ ）","options":[{"key":"A","text":"NaOH、Ca(OH)2 和 Na2CO3"},{"key":"B","text":"只有 NaOH"},{"key":"C","text":"NaOH 和 Na2CO3"},{"key":"D","text":"NaOH 和 Ca(OH)2"}],"answer":["A"],"explanation":"Ca(OH)2 和 Na2CO3 会发生反应生成沉淀，绝不能同时存在于滤液中。"},{"id":"kp-chemistry-sp-p08-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（基础）","level":1,"kpFree":true,"type":"single","stem":"要检验 Ca(OH)2 与 Na2CO3 反应过滤后的滤液中是否含有过量 Na2CO3，可向滤液中滴加足量（ ）","options":[{"key":"A","text":"无色酚酞"},{"key":"B","text":"稀盐酸（观察是否有气泡产生）"},{"key":"C","text":"氯化钠溶液"},{"key":"D","text":"氢氧化钠溶液"}],"answer":["B"],"explanation":"Na2CO3 遇足量稀盐酸产生 CO2 气泡，而 NaOH 和 Ca(OH)2 加酸无气泡。"},{"id":"kp-chemistry-sp-p08-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"实验室制取二氧化碳（CaCO3＋2HCl）反应结束后，向残留废液中滴加几滴紫色石蕊试液变红，则废液中含有的溶质是（ ）","options":[{"key":"A","text":"只有 HCl"},{"key":"B","text":"CaCl2 和 CaCO3"},{"key":"C","text":"CaCl2 和 HCl"},{"key":"D","text":"只有 CaCl2"}],"answer":["C"],"explanation":"石蕊变红说明稀盐酸过量，故溶质为生成物 CaCl2 和过量 HCl。"},{"id":"kp-chemistry-sp-p08-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":false,"type":"blank","stem":"检验稀硫酸与 NaOH 反应后溶液中是否剩余 NaOH，可滴加无色酚酞溶液，若溶液变______色，说明 NaOH 过量。","blanks":[["红"]],"answer":["红"],"explanation":"Na2SO4 呈中性，酚酞变红即证明含过量 NaOH。"},{"id":"kp-chemistry-sp-p08-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（提高）","level":2,"kpFree":false,"type":"single","stem":"若向反应后可能含 HCl 和 CaCl2 的废液中逐滴加入 Na2CO3 溶液，先观察到有气泡产生，过一会儿才产生白色沉淀，说明原废液中溶质为（ ）","options":[{"key":"A","text":"只有 CaCl2"},{"key":"B","text":"只有 HCl"},{"key":"C","text":"NaCl 和 CaCl2"},{"key":"D","text":"CaCl2 和 HCl"}],"answer":["D"],"explanation":"先与 HCl 反应产气，再与 CaCl2 反应生成 CaCO3 白沉淀，证明两者均存在。"},{"id":"kp-chemistry-sp-p08-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（拓展）","level":3,"kpFree":false,"type":"single","stem":"用铁粉与稀硫酸反应制氢气后过滤，要证明滤液中稀硫酸有剩余，最直接且不引入新金属离子的试剂是（ ）","options":[{"key":"A","text":"氧化铜粉末或碳酸钠溶液"},{"key":"B","text":"无色酚酞"},{"key":"C","text":"氯化钡溶液"},{"key":"D","text":"硫酸铜溶液"}],"answer":["A"],"explanation":"BaCl2 会与 FeSO4 中的 SO4²⁻ 沉淀无法证明 H⁺；CuO 溶解变蓝或 Na2CO3 产气均可证明 H⁺ 剩余。"},{"id":"kp-chemistry-sp-p08-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（拓展）","level":3,"kpFree":false,"type":"single","stem":"设计实验验证某猜想时，所选试剂必须能产生“唯一对应现象”。若检验某溶液中是否同时含 OH⁻ 和 CO3²⁻，应先加过量（ ）除去 CO3²⁻，再检验 OH⁻。","options":[{"key":"A","text":"稀盐酸"},{"key":"B","text":"氯化钡或氯化钙溶液"},{"key":"C","text":"氢氧化钡溶液"},{"key":"D","text":"酚酞溶液"}],"answer":["B"],"explanation":"用中性钡/钙盐沉淀除尽 CO3²⁻ 且不引入 OH⁻，再用酚酞检验原 OH⁻。"},{"id":"kp-chemistry-sp-p08-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p08","kp":"反应后溶液中溶质成分猜想与验证","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 反应后溶液中溶质成分猜想与验证（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"溶质成分实验探究","stem":"同学们做稀盐酸与氢氧化钠溶液中和反应实验，向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸至溶液恰好变为无色，再多滴了几滴。对反应后无色废液中的溶质成分展开探究：（1）写出反应后无色废液中溶质成分的两种合理猜想；（2）请选用两种不同类别的试剂，验证废液中含有稀盐酸（写出试剂名称与预期现象）；（3）有同学提出滴加 AgNO₃ 溶液产生白色沉淀就能证明含稀盐酸，请评价该方案是否正确并说明理由。","score":10,"points":[{"text":"（1）猜想一：只有 NaCl；猜想二：NaCl 和 HCl","score":3,"keys":["NaCl","HCl"]},{"text":"（2）任选两类不同试剂（如紫色石蕊变红、锌粒/铁粉冒气泡、Na₂CO₃/CaCO₃ 冒气泡、CuO 溶解变蓝等）且现象对应正确","score":4,"keys":["石蕊","锌","铁","碳酸钠","碳酸钙","气泡","变红"]},{"text":"（3）不正确；因为生成物 NaCl 中也含有 Cl⁻，滴加 AgNO₃ 溶液同样会产生 AgCl 白色沉淀，无法证明含 HCl","score":3,"keys":["不正确","错误","NaCl","Cl⁻","白色沉淀"]}],"method":"① 反应后溶质猜想铁律：一定有生成物 NaCl，可能有过量的某一种反应物（因为酚酞无色，排除 NaOH 过量，只剩恰好反应或 HCl 过量两种可能）；② 检验 HCl 本质是检验 H⁺，不同类别试剂可从指示剂、活泼金属、碳酸盐、金属氧化物中任选两类；③ AgNO₃ 检验的是 Cl⁻，生成物 NaCl 也含 Cl⁻。","sample":"解：（1）因酚酞呈无色，溶液中不含 NaOH，故合理猜想为：\n猜想一：只有 NaCl（恰好完全反应）；\n猜想二：NaCl 和 HCl（稀盐酸过量）。\n（2）验证含 HCl（即检验 H⁺）的两种不同类别试剂（任选其二）：\n① 酸碱指示剂：滴加紫色石蕊溶液，溶液变红；\n② 活泼金属：加入锌粒（或铁粉），有气泡产生；\n③ 碳酸盐：加入碳酸钠溶液（或大理石），有气泡产生；\n④ 金属氧化物：加入氧化铜粉末并微热，黑色固体溶解、溶液变蓝。\n（3）该方案不正确。因为无论是否含有稀盐酸，废液中一定含有生成物 NaCl，其中的 Cl⁻ 都会与 AgNO₃ 溶液反应生成白色的 AgCl 沉淀，不能证明 H⁺（即 HCl）的存在。","explanation":"审题抓关键词：“两种不同类别的试剂”！如果同时写锌粒和镁条（都属于金属）会被扣一半分数。"},{"id":"kp-chemistry-sp-p09-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p09-gas.svg","type":"single","stem":"如图，要得到纯净干燥的 CO2（原气体混有 HCl 和 H2O），正确的试剂连接顺序是（ ）","options":[{"key":"A","text":"先通过浓硫酸，再通过饱和 NaHCO3 溶液"},{"key":"B","text":"先通过 NaOH 溶液，再通过浓硫酸"},{"key":"C","text":"先通过饱和 NaHCO3 溶液，再通过浓硫酸"},{"key":"D","text":"只通过澄清石灰水"}],"answer":["C"],"explanation":"除杂后除水；不能用 NaOH 否则吸收 CO2，先用饱和 NaHCO3 除 HCl 再用浓硫酸干燥。"},{"id":"kp-chemistry-sp-p09-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"type":"single","stem":"要检验某混合气体中是否同时含有水蒸气和二氧化碳，气体通过试剂的正确顺序是（ ）","options":[{"key":"A","text":"任意顺序均可"},{"key":"B","text":"先通过浓硫酸，再通过澄清石灰水"},{"key":"C","text":"先通过澄清石灰水，再通过无水硫酸铜"},{"key":"D","text":"先通过无水硫酸铜，再通过澄清石灰水"}],"answer":["D"],"explanation":"检验先验水！若先通澄清石灰水，气体会带出水蒸气干扰无水硫酸铜检验。"},{"id":"kp-chemistry-sp-p09-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（基础）","level":1,"kpFree":true,"type":"single","stem":"不另加任何其他试剂，就能将下列四瓶失去标签的溶液一一鉴别出来的是（ ）","options":[{"key":"A","text":"CuSO4、NaOH、BaCl2、HCl"},{"key":"B","text":"H2SO4、HCl、NaCl、KNO3"},{"key":"C","text":"NaOH、KOH、NaCl、KCl"},{"key":"D","text":"NaCl、KCl、NaNO3、KNO3"}],"answer":["A"],"explanation":"先看颜色挑出蓝色 CuSO4；用 CuSO4 滴入其余三瓶，产生蓝沉淀是 NaOH、白沉淀是 BaCl2、无现象是 HCl！"},{"id":"kp-chemistry-sp-p09-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"除去下列物质中少量杂质（括号内为杂质），所选试剂和方法完全正确的是（ ）","options":[{"key":"A","text":"CaO（CaCO3）— 加足量水，过滤"},{"key":"B","text":"Cu 粉（Fe 粉）— 加足量稀盐酸，过滤"},{"key":"C","text":"CO2（CO）— 通入足量氧气点燃"},{"key":"D","text":"KCl 溶液（K2SO4）— 加过量 BaCl2 溶液，过滤"}],"answer":["B"],"explanation":"Fe 溶于稀盐酸而 Cu 不反应，过滤得纯 Cu；B 中 CaO 会与水反应；C 点不着；D 过量 BaCl2 引入新杂质。"},{"id":"kp-chemistry-sp-p09-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":false,"type":"single","stem":"除去 CaO 中混有的少量 CaCO3，最简便合理的工业方法是（ ）","options":[{"key":"A","text":"加氢氧化钠溶液"},{"key":"B","text":"加稀盐酸"},{"key":"C","text":"高温煅烧"},{"key":"D","text":"加水过滤"}],"answer":["C"],"explanation":"CaCO3＝(高温)CaO＋CO2↑，直接转化为目标物 CaO 且无任何杂质残留。"},{"id":"kp-chemistry-sp-p09-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（提高）","level":2,"kpFree":false,"type":"blank","stem":"用装有浓硫酸的洗气瓶干燥氧气时，气体应从______（填“长”或“短”）导管通入。","blanks":[["长"]],"answer":["长"],"explanation":"洗气遵循“长进短出”，让气体充分穿过干燥液。"},{"id":"kp-chemistry-sp-p09-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（拓展）","level":3,"kpFree":false,"type":"single","stem":"要除去 FeSO4 溶液中混有的少量 CuSO4，最合适的操作是（ ）","options":[{"key":"A","text":"加入过量锌粉后过滤"},{"key":"B","text":"加入过量铜粉后过滤"},{"key":"C","text":"加入适量氢氧化钠溶液后过滤"},{"key":"D","text":"加入过量铁粉后过滤"}],"answer":["D"],"explanation":"Fe＋CuSO4＝FeSO4＋Cu，过量铁粉过滤即除，不引新杂。"},{"id":"kp-chemistry-sp-p09-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（拓展）","level":3,"kpFree":false,"type":"single","stem":"下列各组白色固体，只用“水”就能一次性鉴别出来的是（ ）","options":[{"key":"A","text":"CaCO3、NaOH、NH4NO3、NaCl"},{"key":"B","text":"NaCl、KCl、KNO3"},{"key":"C","text":"Na2CO3、NaHCO3、NaOH"},{"key":"D","text":"BaSO4、CaCO3、AgCl"}],"answer":["A"],"explanation":"加水：CaCO3 不溶；NaOH 溶解剧烈放热；NH4NO3 溶解明显吸热降温；NaCl 溶解温度几乎不变。"},{"id":"kp-chemistry-sp-p09-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p09","kp":"多步除杂、无试剂鉴别与气体净化顺序","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 多步除杂、无试剂鉴别与气体净化顺序（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"除杂鉴别与净化大题","stem":"（1）实验室用大理石和浓盐酸反应制得的 CO₂ 中混有少量 HCl 气体和水蒸气。现提供盛有饱和 NaHCO₃ 溶液和浓硫酸的两个洗气瓶，欲得到纯净、干燥的 CO₂，请写出两个洗气瓶的先后连接顺序、导管进出方式及理由，并写出除 HCl 时发生反应的化学方程式；（2）能否用 NaOH 溶液代替饱和 NaHCO₃ 溶液除去 CO₂ 中的 HCl？为什么？（3）实验室有四瓶失去标签的无色溶液：Na₂CO₃ 溶液、BaCl₂ 溶液、稀 HCl 和 NaCl 溶液。不另加任何其他试剂，仅用两两混合的方法即可将它们一一鉴别出来，请写出具体的判断依据。","score":10,"points":[{"text":"（1）先通过饱和 NaHCO₃ 溶液，再通过浓硫酸；导管长进短出；理由：若先干燥再过水溶液会重新带出水蒸气；NaHCO₃＋HCl＝NaCl＋H₂O＋CO₂↑","score":4,"keys":["NaHCO₃","浓硫酸","长进短出","CO₂↑"]},{"text":"（2）不能；因为 NaOH 溶液不仅能与 HCl 反应，还会与主体气体 CO₂ 反应（消耗原物质 CO₂）","score":2,"keys":["不能","CO₂","反应","消耗"]},{"text":"（3）两两混合：既产生气泡又产生白色沉淀的是 Na₂CO₃；只产生气泡的是稀 HCl；只产生白色沉淀的是 BaCl₂；均无明显现象的是 NaCl","score":4,"keys":["既","气泡","白色沉淀","无明显现象"]}],"method":"① 气体净化铁律：“除杂后除水，洗气长进短出”——先用饱和 NaHCO₃ 溶液吸收 HCl（还顺带生成 CO₂），再用浓硫酸吸水干燥；② 除杂三原则“不增、不减、易分离”，NaOH 会吸收主体气体 CO₂ 违背“不减”；③ 无试剂鉴别画 4×4 两两混合现象表，按“气泡数、沉淀数”精准锁定每瓶溶液。","sample":"解：（1）连接顺序：混合气体先通过盛有饱和 NaHCO₃ 溶液的洗气瓶，再通过盛有浓硫酸的洗气瓶；洗气瓶导管应“长进短出”。\n理由：若先用浓硫酸干燥再通过饱和 NaHCO₃ 溶液，气体从水溶液中出来时会重新混入水蒸气，无法得到干燥的 CO₂。\n除 HCl 的化学方程式：NaHCO₃＋HCl＝NaCl＋H₂O＋CO₂↑。\n（2）不能。因为 NaOH 溶液既会与杂质 HCl 反应，也会与主体气体 CO₂ 发生反应（2NaOH＋CO₂＝Na₂CO₃＋H₂O），把需要制取的 CO₂ 一并吸收了，违背除杂“不减少原物质”的原则。\n（3）将四瓶溶液分别编号后各取少量两两混合，观察现象：\n① 与另外三种溶液混合时，既能产生气泡（与稀 HCl）又能产生白色沉淀（与 BaCl₂）的是 Na₂CO₃ 溶液；\n② 只产生一次气泡、无沉淀的是稀 HCl；\n③ 只产生一次白色沉淀、无气泡的是 BaCl₂ 溶液；\n④ 与其余三种溶液混合均无明显现象的是 NaCl 溶液。","explanation":"阅卷易错红线：① 混淆“检验先验水，除杂后除水”导致先后顺序写反；② 洗气瓶写成“短进长出”会把液体压出；③ 无试剂鉴别表述不清，必须把“既有气泡又有沉淀”“只有气泡”“只有沉淀”“均无现象”四种特征一一对应写明。"},{"id":"kp-chemistry-sp-p13-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p13-sensor.svg","type":"single","stem":"如图测氧压强曲线中，红磷点燃后密闭集气瓶内压强在初期迅速上升，其主要原因是（ ）","options":[{"key":"A","text":"红磷燃烧生成了大量气体"},{"key":"B","text":"红磷燃烧放出大量热，气体受热膨胀使压强增大"},{"key":"C","text":"外界空气不断涌入瓶内"},{"key":"D","text":"压强传感器发生故障"}],"answer":["B"],"explanation":"【思路依据】红磷燃烧生成五氧化二磷固体并放热，升温引起的气压增大远超耗氧降压。 【避坑提醒】切忌误认为燃烧产生了气体，五氧化二磷是白色固体白烟。"},{"id":"kp-chemistry-sp-p13-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p13-sensor.svg","type":"single","stem":"如图为稀盐酸与氢氧化钠溶液反应时的 pH 变化曲线，由曲线起点（pH＞7）可判断该实验的操作是（ ）","options":[{"key":"A","text":"将氢氧化钠溶液逐滴加入稀盐酸中"},{"key":"B","text":"将水逐滴加入稀盐酸中"},{"key":"C","text":"将稀盐酸逐滴加入氢氧化钠溶液中"},{"key":"D","text":"将氯化钠溶液滴入水中"}],"answer":["C"],"explanation":"【思路依据】起点 pH 大于 7 说明烧杯中原液呈碱性，随滴加 pH 降低，故为向碱中滴加酸。 【避坑提醒】判断滴加方向只看纵轴起点，切勿看终点而倒推错。"},{"id":"kp-chemistry-sp-p13-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（基础）","level":1,"kpFree":true,"type":"blank","stem":"俗称“纯碱”“苏打”，水溶液呈碱性但物质分类属于盐的物质，其化学式为____。","blanks":[["Na2CO3"]],"answer":["Na2CO3"],"explanation":"【思路依据】碳酸钠俗称纯碱、苏打，由钠离子和碳酸根构成，属于盐类。 【避坑提醒】注意区分纯碱 Na2CO3、小苏打 NaHCO3 与烧碱 NaOH 的化学式。"},{"id":"kp-chemistry-sp-p13-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（提高）","level":2,"kpFree":true,"kpDiag":true,"image":"./assets/knowledge/chemistry/sp/p13-sensor.svg","type":"single","stem":"如图中和反应温度与 pH 双曲线所示，当温度传感器示数达到最高点时，此时溶液中的溶质成分为（ ）","options":[{"key":"A","text":"只有 NaOH"},{"key":"B","text":"HCl 和 NaCl"},{"key":"C","text":"NaOH 和 NaCl"},{"key":"D","text":"只有 NaCl"}],"answer":["D"],"explanation":"【思路依据】中和反应放热，温度最高点代表酸碱恰好完全反应，对应 pH 等于 7，溶质仅剩氯化钠。 【避坑提醒】过最高点后继续滴加室温酸液，降温且溶质变为氯化钠和氯化氢。"},{"id":"kp-chemistry-sp-p13-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（提高）","level":2,"kpFree":false,"type":"single","stem":"下列常见沉淀中，既呈现白色又完全不溶于稀硝酸的一组是（ ）","options":[{"key":"A","text":"BaSO4 和 AgCl"},{"key":"B","text":"Mg(OH)2 和 CaCO3"},{"key":"C","text":"Cu(OH)2 和 Fe(OH)3"},{"key":"D","text":"CaCO3 和 BaCO3"}],"answer":["A"],"explanation":"【思路依据】初中化学八大沉淀中，只有硫酸钡和氯化银不溶于稀硝酸，是检验硫酸根和氯离子的金标准。 【避坑提醒】碳酸钡与碳酸钙虽为白沉淀，但均溶于酸并冒气泡。"},{"id":"kp-chemistry-sp-p13-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（提高）","level":2,"kpFree":false,"type":"blank","stem":"在密闭容器中加入一定量硝酸铵（NH4NO3）固体和水，用压强传感器测得容器内气压会明显____（填“增大”或“减小”）。","blanks":[["减小"]],"answer":["减小"],"explanation":"【思路依据】硝酸铵溶于水明显吸热，导致密闭容器内温度降低、气体收缩，压强减小。 【避坑提醒】牢记溶解吸放热特例：氢氧化钠和浓硫酸放热升压，硝酸铵吸热降压。"},{"id":"kp-chemistry-sp-p13-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/chemistry/sp/p13-sensor.svg","type":"single","stem":"用压强传感器监测密闭瓶中红磷测氧实验，若打开止水夹前瓶内气压已降至最低且保持稳定，打开止水夹后瓶内气压迅速回升至初始大气压，主要原因是（ ）","options":[{"key":"A","text":"瓶内红磷再次自燃放热"},{"key":"B","text":"外界大气压将烧杯中的水压入瓶内，压缩瓶内剩余气体"},{"key":"C","text":"氮气与水发生剧烈反应生成新气体"},{"key":"D","text":"烧杯中的水在瓶内瞬间汽化"}],"answer":["B"],"explanation":"【思路依据】打开止水夹后外界大气压把水压入集气瓶，占据消耗氧气的体积使气压恢复常压。 【避坑提醒】若未等冷却就开夹，气压尚未降到最低，进水量会偏小导致测氧偏低。"},{"id":"kp-chemistry-sp-p13-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（拓展）","level":3,"kpFree":false,"type":"single","stem":"向盛有少量 NaOH 溶液的密闭烧瓶中先注入适量稀盐酸，待反应完全后再注入过量 Na2CO3 溶液，若烧瓶内压强先不变、后急剧增大，则首次加入的稀盐酸（ ）","options":[{"key":"A","text":"量不足，NaOH 有剩余"},{"key":"B","text":"恰好与 NaOH 完全反应"},{"key":"C","text":"过量，反应后溶液呈酸性"},{"key":"D","text":"已完全挥发"}],"answer":["C"],"explanation":"【思路依据】中和反应无气体生成故压强基本不变；后续加碳酸钠压强急增，说明有二氧化碳生成，即盐酸过量。 【避坑提醒】把压强突变转化为是否产气或吸放热，是数字化传感题核心思路。"},{"id":"kp-chemistry-sp-p13-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p13","kp":"数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表","unit":"专题·实验探究与除杂鉴别","chapter":"专题与压轴 · 实验探究（变质/成分/除杂鉴别）压轴","source":"知识点精练 · 专题与压轴 · 数字化传感实验（压强/pH/温度曲线）与常见物质俗名沉淀总表（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"数字化传感探究大题","stem":"数字化传感器能实时精准记录反应中的压强、pH 和温度变化。请分析以下两个传感实验：（一）用红磷在密闭集气瓶中测定空气中氧气含量，压强传感器记录的曲线呈现“先迅速上升至峰值→随后大幅下降至低于初始大气压并保持平稳→打开止水夹后迅速回升至初始大气压”三段特征。（二）向盛有 20 mL 某稀氢氧化钠溶液的烧杯中逐滴加入稀盐酸，同时用 pH 传感器和温度传感器监测，发现溶液 pH 从 13 逐渐下降至 2，溶液温度先由 22 ℃ 升至最高点 28 ℃ 后逐渐回落。（1）实验（一）中，集气瓶内压强先迅速上升的主要原因是什么？为什么必须待压强降至最低并冷却至室温后才能打开止水夹？（2）实验（二）中，写出反应的化学方程式；当温度传感器显示最高温度 28 ℃ 时，对应的 pH 约为多少？此时烧杯溶液中的溶质是什么？若继续滴加稀盐酸至 pH＝2，此时溶液中的溶质又是什么？（3）若实验（二）中错把久置变质的 NaOH 溶液（含少量纯碱杂质）拿来做实验，滴加足量稀盐酸时会额外观察到什么现象？写出纯碱的化学式并写出一个检验其存在且生成白色沉淀的化学方程式。","score":10,"points":[{"text":"（1）红磷燃烧放出大量热，使集气瓶内气体受热膨胀，升温增压的影响大于耗氧降压的影响；若未冷却至室温就打开止水夹，瓶内温度偏高、气压偏大，会导致倒吸入集气瓶的水偏少（测定氧气含量结果偏小）","score":3,"keys":["放","膨胀","偏小"]},{"text":"（2）NaOH＋HCl＝NaCl＋H₂O；温度最高点 28 ℃ 对应 pH 约为 7，此时恰好完全中和，溶质只有 NaCl；滴至 pH＝2 时稀盐酸过量，溶质为 NaCl 和 HCl","score":4,"keys":["NaOH＋HCl","7","NaCl","HCl"]},{"text":"（3）额外观察到有气泡产生；纯碱化学式为 Na₂CO₃；检验方程式：Na₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl（或与 Ca(OH)₂/BaCl₂ 反应生成白沉淀）","score":3,"keys":["气泡","Na₂CO₃","CaCO₃↓"]}],"method":"① 压强曲线双因素分析：温度升高（放热）和气体增多使压强升，冷却和耗气使压强降，测氧先升是因为燃烧放热压倒耗氧；② 酸碱中和双曲线锚点：温度最高点＝放热最多点＝恰好完全中和点（pH＝7，溶质仅盐）；pH＜7 时酸过量（溶质为盐＋酸）；③ 俗名与沉淀速连：纯碱＝Na₂CO₃，遇酸冒气泡，遇 CaCl₂/Ca(OH)₂/BaCl₂ 均生成白色沉淀。","sample":"解：（1）压强先迅速上升的原因：红磷燃烧虽然消耗氧气，但同时放出大量热，使瓶内气体剧烈受热膨胀，升温导致的压强增大效应远大于耗氧导致的压强减小效应。\n必须冷却至室温再打开止水夹的原因：若未充分冷却，瓶内气体仍处于受热膨胀状态、压强偏大，打开止水夹后进入瓶内的水体积偏少，会导致测得的空气中氧气体积分数偏小。\n（2）酸碱中和反应的化学方程式：NaOH＋HCl＝NaCl＋H₂O。\n酸碱中和属于放热反应，温度达到最高点 28 ℃ 时说明酸碱恰好完全反应，此时溶液呈中性，pH 约为 7，烧杯中溶质只有 NaCl。\n继续滴加稀盐酸至 pH＝2 时，稀盐酸过量，此时溶液中的溶质为 NaCl 和 HCl。\n（3）久置变质的 NaOH 中含有纯碱（化学式为 Na₂CO₃），滴加足量稀盐酸时会与 Na₂CO₃ 反应，额外观察到有气泡产生。\n生成白色沉淀检验纯碱的化学方程式：Na₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl（或 Na₂CO₃＋Ca(OH)₂＝CaCO₃↓＋2NaOH）。","explanation":"阅卷易错红线：① 测氧初期升压错答“红磷燃烧产生了大量白烟气体”（P₂O₅ 是固体不是气体）；② pH＝2 时溶质错写成“NaCl 和稀盐酸”（溶质应写 HCl 而非溶液名称）；③ 沉淀方程式漏标沉淀符号 ↓ 或忘记配平 2NaCl。"},{"id":"kp-chemistry-sp-p10-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"如图为向含有 HCl 和 CuCl2 的混合溶液中逐滴加入 NaOH 溶液的沉淀质量曲线，当滴加至 b 点时，溶液中的溶质是（ ）","options":[{"key":"A","text":"只有 NaCl"},{"key":"B","text":"NaCl、HCl 和 CuCl2"},{"key":"C","text":"NaCl 和 NaOH"},{"key":"D","text":"NaCl 和 CuCl2"}],"answer":["D"],"explanation":"b 点 HCl 恰好被中和完，CuCl2 尚未开始反应，故溶质为 NaCl 和 CuCl2。"},{"id":"kp-chemistry-sp-p10-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"如图曲线中，当滴加 NaOH 溶液至 c 点（沉淀恰好达到最大）时，溶液的 pH 和溶质分别是（ ）","options":[{"key":"A","text":"pH＝7，只有 NaCl"},{"key":"B","text":"pH＜7，NaCl 和 HCl"},{"key":"C","text":"pH＞7，NaCl 和 NaOH"},{"key":"D","text":"pH＝7，NaCl 和 CuCl2"}],"answer":["A"],"explanation":"c 点 HCl 和 CuCl2 均恰好完全反应，溶质只有中性的 NaCl，pH＝7。"},{"id":"kp-chemistry-sp-p10-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（基础）","level":1,"kpFree":true,"type":"single","stem":"向含有 HCl 和 H2SO4 的混合溶液中逐滴加入 Ba(OH)2 溶液，产生白色沉淀的质量曲线起点在（ ）","options":[{"key":"A","text":"无沉淀产生"},{"key":"B","text":"原点（0 点，立刻产生沉淀）"},{"key":"C","text":"横轴正半轴（延迟产生）"},{"key":"D","text":"纵轴正半轴"}],"answer":["B"],"explanation":"BaSO4 沉淀不溶于强酸，故一滴入 Ba(OH)2 就立刻从原点开始生成白色沉淀。"},{"id":"kp-chemistry-sp-p10-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向一定量 NaOH 和 Na2CO3 混合溶液中逐滴加入稀盐酸，产生 CO2 气体的质量随加入稀盐酸质量变化的图像特点是（ ）","options":[{"key":"A","text":"从原点立刻上升"},{"key":"B","text":"先上升后下降"},{"key":"C","text":"先在横轴走一段水平线（0 气体），再斜向上升，最后变水平平台"},{"key":"D","text":"始终为 0"}],"answer":["C"],"explanation":"稀盐酸先中和 NaOH 无气体产生，中和完后才与 Na2CO3 反应产生 CO2。"},{"id":"kp-chemistry-sp-p10-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/chemistry/sp/p10-graph.svg","type":"single","stem":"在如图的 d 点（NaOH 已过量），向此时溶液中滴加无色酚酞试液，溶液呈（ ）","options":[{"key":"A","text":"黄色"},{"key":"B","text":"蓝色"},{"key":"C","text":"无色"},{"key":"D","text":"红色"}],"answer":["D"],"explanation":"d 点含过量 NaOH，溶液显碱性，酚酞变红。"},{"id":"kp-chemistry-sp-p10-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（提高）","level":2,"kpFree":false,"type":"single","stem":"向盛有一定量 CaCl2 和 HCl 混合液的烧杯中逐滴加入 Na2CO3 溶液，溶液的 pH 变化趋势是（ ）","options":[{"key":"A","text":"先上升至 7（中和 HCl），在 7 处保持水平（与 CaCl2 沉淀），最后再上升大于 7（Na2CO3 过量）"},{"key":"B","text":"一直上升"},{"key":"C","text":"一直下降"},{"key":"D","text":"先降后升"}],"answer":["A"],"explanation":"中和 HCl 时 pH 升至 7；与 CaCl2 反应生成中性 NaCl 和沉淀，pH 维持在 7 平台；最后 Na2CO3 过量显碱性 pH＞7。"},{"id":"kp-chemistry-sp-p10-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（拓展）","level":3,"kpFree":false,"type":"single","stem":"向一定量氧化铁（Fe2O3）固体中逐滴加入稀盐酸至过量，溶液中铁元素质量随稀盐酸加入量的变化图像是（ ）","options":[{"key":"A","text":"先升后降"},{"key":"B","text":"从 0 上升到定值后保持水平"},{"key":"C","text":"从某正值开始下降"},{"key":"D","text":"始终为 0"}],"answer":["B"],"explanation":"原固体未溶解溶液含铁 0，加稀盐酸 Fe2O3 逐渐溶解为 FeCl3 溶液，完全溶解后铁元素质量不变。"},{"id":"kp-chemistry-sp-p10-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在电解水实验中，生成氢气和氧气的质量比恒为 1∶8，若以通电时间为横坐标、气体质量为纵坐标，斜率较大的直线代表的是______（填“氧气”或“氢气”）。","blanks":[["氧气"]],"answer":["氧气"],"explanation":"相同时间内生成氧气质量是氢气的 8 倍，故氧气的质量曲线斜率更大。"},{"id":"kp-chemistry-sp-p10-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p10","kp":"复分解反应先后顺序与沉淀/气体拐点图像","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 复分解反应先后顺序与沉淀/气体拐点图像（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"复分解顺序与图像","stem":"向一定量 HCl 和 CaCl₂ 的混合溶液中逐滴加入 Na₂CO₃ 溶液至过量，测得生成沉淀的质量随加入 Na₂CO₃ 溶液质量变化分为三段：0→a 段无沉淀，a→b 段沉淀质量不断增加，b 点之后沉淀质量保持不变。（1）解释 0→a 段为什么没有沉淀产生，并写出该段反应的化学方程式；（2）写出 a→b 段反应的化学方程式；（3）指出 b 点时溶液的溶质成分，并描述从 0 到 b 点之后溶液 pH 的变化趋势。","score":10,"points":[{"text":"（1）0→a 段 Na₂CO₃ 先与 HCl 反应（即使生成 CaCO₃ 也会被 HCl 溶解），方程式 Na₂CO₃＋2HCl＝2NaCl＋H₂O＋CO₂↑","score":4,"keys":["HCl","2NaCl","CO₂↑","CO2"]},{"text":"（2）a→b 段：Na₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl","score":3,"keys":["CaCO₃↓","CaCO3","2NaCl"]},{"text":"（3）b 点溶质只有 NaCl；pH 变化：0→a 段由＜7 增大到 7，a→b 段保持 7 不变，b 点后继续增大至＞7","score":3,"keys":["NaCl","7","不变","增大"]}],"method":"① 混合溶液加碱或碳酸盐遵循“酸碱中和/酸反应优先”：0→a 段 Na₂CO₃ 先消耗 HCl 产生气体；② a 点 HCl 耗尽后，a→b 段 Na₂CO₃ 与 CaCl₂ 反应生成 CaCO₃ 沉淀；③ pH 变化呈“上升 → 平台（pH＝7）→ 再上升”三段阶梯。","sample":"解：（1）0→a 段 Na₂CO₃ 优先与混合液中的 HCl 发生反应（即便有 CaCO₃ 生成也会立刻被 HCl 溶解），因此此阶段只有气泡而无沉淀产生。\n化学方程式：Na₂CO₃＋2HCl＝2NaCl＋H₂O＋CO₂↑。\n（2）a 点时 HCl 恰好耗尽，a→b 段 Na₂CO₃ 与 CaCl₂ 反应产生沉淀：\nNa₂CO₃＋CaCl₂＝CaCO₃↓＋2NaCl。\n（3）b 点时 CaCl₂ 恰好完全反应，溶液中溶质只有 NaCl（溶液呈中性，pH＝7）。\n溶液 pH 变化趋势：0→a 段随盐酸消耗 pH 从小于 7 逐渐升高至 7；a→b 段生成中性 NaCl 与沉淀，pH 保持 7 不变（呈水平平台）；b 点之后过量 Na₂CO₃ 显碱性，pH 继续升高至大于 7。","explanation":"该模型几乎是各地中考图像题必考原型，牢记“三段对应关系”：0→a 产气 pH 升，a→b 产沉淀 pH 平，b 后过量 pH 再升！"},{"id":"kp-chemistry-sp-p11-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"某氧化铁（Fe2O3）和四氧化三铁（Fe3O4）的混合物 20 g，经足量 CO 高温完全还原后得到 14.4 g 纯铁，则原混合物中氧元素的质量为______g。","blanks":[["5.6"]],"answer":["5.6"],"explanation":"混合物仅含 Fe 和 O，故 m(O)＝20－14.4＝5.6 g。"},{"id":"kp-chemistry-sp-p11-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 25 g 石灰石样品（杂质不反应）放入 100 g 足量稀盐酸中充分反应，称得烧杯内剩余物质总质量为 116.2 g，则生成二氧化碳的质量为______g。","blanks":[["8.8"]],"answer":["8.8"],"explanation":"由差量法，m(CO2)＝25＋100－116.2＝8.8 g。"},{"id":"kp-chemistry-sp-p11-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"某镁粉和氧化镁的混合物共 10 g，其中氧元素质量分数为 20%，将它与足量稀硫酸完全反应后蒸发，最终得到硫酸镁（MgSO4）的质量为______g（Mg-24, S-32, O-16）。","blanks":[["40"]],"answer":["40"],"explanation":"镁元素质量＝10×(1－20%)＝8 g；MgSO4 中 Mg 占 24/120＝20%，故 m(MgSO4)＝8÷20%＝40 g！"},{"id":"kp-chemistry-sp-p11-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"某样品由 CaCO3 和 CaO 组成，测得其中钙元素的质量分数为 50%，取 20 g 该样品高温充分煅烧至质量不再变化，最终剩余固体（CaO）的质量为（ ）","options":[{"key":"A","text":"18 g"},{"key":"B","text":"16 g"},{"key":"C","text":"14 g"},{"key":"D","text":"10 g"}],"answer":["C"],"explanation":"钙元素质量＝20×50%＝10 g；最终全为 CaO（含钙 40/56＝5/7），故 m(CaO)＝10÷(5/7)＝14 g！"},{"id":"kp-chemistry-sp-p11-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将一根质量为 50 g 的铁棒插入足量 CuSO4 溶液中，一段时间后取出洗净烘干称重为 50.8 g，则析出金属铜的质量为______g（Fe-56, Cu-64）。","blanks":[["6.4"]],"answer":["6.4"],"explanation":"Fe(56)换Cu(64)每析出 64 g Cu 增重 8 g；现增重 0.8 g，故析出铜 6.4 g。"},{"id":"kp-chemistry-sp-p11-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（提高）","level":2,"kpFree":false,"type":"single","stem":"在 10 g 碳酸钙和碳酸钠的混合物中加入足量稀盐酸，完全反应后可能生成 CO2 的质量是（CaCO3-100, Na2CO3-106, CO2-44）（ ）","options":[{"key":"A","text":"4.0 g"},{"key":"B","text":"4.5 g"},{"key":"C","text":"5.0 g"},{"key":"D","text":"4.3 g"}],"answer":["D"],"explanation":"极值法：10 g 纯 CaCO3 产 4.4 g CO2，10 g 纯 Na2CO3 产 4.15 g CO2，混合物必介于 4.15～4.4 g 之间，选 4.3 g。"},{"id":"kp-chemistry-sp-p11-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"某有机物 3.2 g 完全燃烧生成 4.4 g CO2 和 3.6 g H2O，则该有机物中碳、氢、氧三种元素的质量比为______（最简整数比）。","blanks":[["3:1:4","3∶1∶4"]],"answer":["3:1:4"],"explanation":"m(C)＝1.2 g，m(H)＝0.4 g，m(O)＝3.2－1.2－0.4＝1.6 g，比值 1.2∶0.4∶1.6＝3∶1∶4。"},{"id":"kp-chemistry-sp-p11-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（拓展）","level":3,"kpFree":false,"type":"single","stem":"5.6 g 含杂质的铁粉与足量稀硫酸反应，生成 0.22 g 氢气（纯 5.6 g 铁只产 0.2 g 氢气），则所含杂质可能是（ ）","options":[{"key":"A","text":"铝或镁（等质量产氢比铁多）"},{"key":"B","text":"碳（不反应）"},{"key":"C","text":"锌（相对原子质量 65）"},{"key":"D","text":"铜（不反应）"}],"answer":["A"],"explanation":"杂质必须比铁产氢能力更强，Mg(24)和 Al(27/3×2＝18)等质量产氢均多于 Fe(56)。"},{"id":"kp-chemistry-sp-p11-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p11","kp":"元素守恒法与差量法巧解化学计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 元素守恒法与差量法巧解化学计算（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"守恒与差量计算大题","stem":"称取 20 g 由 Fe₂O₃ 和 CuO 组成的固体混合物，在高温下通入足量 CO 充分还原，完全反应后冷却，测得剩余金属固体总质量为 14.4 g；再将这 14.4 g 剩余固体全部投入足量稀硫酸中充分反应，过滤、洗涤、干燥后称得剩余不溶固体质量为 3.2 g。（相对原子质量：Fe-56，Cu-64，O-16，C-12，H-1）求：（1）利用差量法计算原混合物中氧元素的总质量，并利用元素守恒计算 CO 还原过程中生成 CO₂ 的总质量；（2）原混合物中 CuO 和 Fe₂O₃ 的质量分数；（3）14.4 g 金属固体与足量稀硫酸反应生成 H₂ 的质量。","score":10,"points":[{"text":"（1）差量法得 m(O)＝20 g－14.4 g＝5.6 g；由 O～CO₂（16:44）得 m(CO₂)＝5.6 g×44/16＝15.4 g","score":4,"keys":["5.6","16","44","15.4"]},{"text":"（2）不溶固体 3.2 g 为 Cu，由 Cu～CuO 得 m(CuO)＝3.2 g÷(64/80)＝4 g，质量分数为 20%；m(Fe₂O₃)＝16 g，质量分数为 80%","score":3,"keys":["4","20%","16","80%"]},{"text":"（3）m(Fe)＝14.4 g－3.2 g＝11.2 g，列方程式 Fe＋H₂SO₄＝FeSO₄＋H₂↑，解得 m(H₂)＝0.4 g","score":3,"keys":["11.2","FeSO₄","0.4"]}],"method":"① 差量法秒算氧元素质量：CO 还原金属氧化物实质是夺走氧化物中的氧，固体减少的质量 Δm＝20 g－14.4 g＝5.6 g 即为氧元素质量；② 元素守恒秒算 CO₂：每个 CO 分子结合 1 个 O 变成 1 个 CO₂（对应关系 O～CO₂，质量比 16:44），无需分别列两个还原方程式；③ 金属加稀硫酸：Cu 不反应，不溶物 3.2 g 即为 Cu，先用 Cu 元素守恒反推 CuO 质量，再用差值求 Fe 质量算 H₂。","sample":"解：（1）CO 还原 Fe₂O₃ 和 CuO 生成 Fe、Cu 和 CO₂，固体减少的质量即为原氧化物中氧元素的质量：\nm(O)＝20 g－14.4 g＝5.6 g。\n反应中每 1 个 CO 分子夺取氧化物中 1 个 O 原子生成 1 个 CO₂ 分子，对应关系为 O ～ CO₂（相对质量比 16 : 44）：\nm(CO₂)＝5.6 g × (44 / 16)＝15.4 g。\n（2）剩余金属固体（Fe 和 Cu）加入足量稀硫酸后，Fe 溶解而 Cu 不反应，故 3.2 g 不溶固体为 Cu。\n由铜元素守恒，原混合物中 CuO 的质量：\nm(CuO)＝3.2 g ÷ (64 / 80)＝4 g。\nCuO 的质量分数＝(4 g / 20 g)×100%＝20%；\nFe₂O₃ 的质量＝20 g－4 g＝16 g，质量分数＝(16 g / 20 g)×100%＝80%。\n（3）14.4 g 剩余固体中铁的质量：m(Fe)＝14.4 g－3.2 g＝11.2 g。\n设生成 H₂ 的质量为 x。\nFe ＋ H₂SO₄ ＝ FeSO₄ ＋ H₂↑\n56                       2\n11.2 g                   x\n56 / 11.2 g ＝ 2 / x，解得 x＝0.4 g。\n答：（1）氧元素质量为 5.6 g，生成 CO₂ 质量为 15.4 g；（2）CuO 占 20%，Fe₂O₃ 占 80%；（3）生成 H₂ 的质量为 0.4 g。","explanation":"阅卷易错红线：① 误以为 O～CO₂ 质量比是 32:44（实际 CO₂ 中只有 1 个 O 来自氧化物，另 1 个 O 来自 CO，必须是 16:44！）；② 计算 H₂ 时错把 14.4 g（Fe＋Cu 混合物）直接代入方程式计算，忘记减去不反应的 3.2 g Cu。"},{"id":"national-fj-2026-chemistry-q18","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"fj-2026-chemistry","number":18,"section":"非选择题","chapter":"2026 年福建中考化学","grade":"九下","stage":"9-down","source":"2026 年福建中考化学 第 18 题","type":"essay","meta":"非选择题","material":"","stem":"（6 分）某检测机构利用下列反应测定食品添加剂葡萄糖酸钙样品中氯化物（以 NaCl 计）的含量：NaCl＋AgNO₃ ═ AgCl↓＋NaNO₃。结果表明，2.00 g 样品参加反应，生成 AgCl 2.87 mg。（相对原子质量：Na 23，Cl 35.5，Ag 108）\n(1) 计算 2.00 g 样品中 NaCl 的质量（写出计算过程）。\n(2) 依据食品安全国家标准，葡萄糖酸钙中氯化物（以 NaCl 计）的含量应低于 0.08%。结合计算结果判断，该样品中氯化物的含量______（填“符合”或“不符合”）国家标准。","points":[{"text":"(1) 设 NaCl 质量为 x，写对比例式 58.5/143.5＝x/2.87 mg","score":3,"keys":[]},{"text":"解得 x＝1.17 mg，格式完整（设、写方程式、列比例、求解、答）","score":2,"keys":[]},{"text":"(2) 符合（1.17 mg÷2 000 mg×100%≈0.059%＜0.08%）","score":1,"keys":[]}],"score":6,"sample":"(1) 解：设 2.00 g 样品中 NaCl 的质量为 x。\nNaCl＋AgNO₃ ═ AgCl↓＋NaNO₃\n58.5　　　　 143.5\nx　　　　　　2.87 mg\n58.5/143.5＝x/2.87 mg，x＝1.17 mg。\n答：2.00 g 样品中 NaCl 的质量为 1.17 mg。\n(2) 符合。","method":"设未知数 → 写化学方程式 → 找相关物质的相对分子质量和已知量 → 列比例式 → 求解 → 答。","answer":[],"explanation":"NaCl 相对分子质量 23＋35.5＝58.5，AgCl 为 108＋35.5＝143.5。含量＝1.17 mg÷2 000 mg×100%≈0.059%，低于 0.08%，符合。坑点：mg 和 g 混用，2.00 g＝2 000 mg。（本题官方答案页未收入合订本，以上按题给数据演算。）","kp":"根据化学方程式的计算","kpId":"chemistry-sp-p11","kpRef":true},{"id":"national-jx-2026-chemistry-q20","national":true,"subject":"chemistry","subjectLabel":"化学","paperId":"jx-2026-chemistry","number":20,"section":"综合计算题","chapter":"2026 年江西中考化学","grade":"九下","stage":"9-down","source":"2026 年江西中考化学 第 20 题","type":"essay","meta":"综合计算题","material":"","stem":"（10 分）氢气在氯气中燃烧生成氯化氢的反应（H₂＋Cl₂ ═点燃═ 2HCl）可用于工业制备盐酸。（相对原子质量：H 1，Cl 35.5）\n(1) 该反应的基本反应类型为______。\n(2) 计算 10 kg 氢气完全反应生成氯化氢的质量（写出计算过程）。\n(3) 将 37 kg 氯化氢气体完全溶解于 63 kg 水中，所得溶液中溶质的质量分数为______。\n(4) 在实验室中，用浓盐酸配制一定溶质质量分数的稀盐酸，混匀时玻璃棒的作用是______，若操作均正确，最终得到的稀盐酸中溶质的质量分数偏小的原因可能为______。","points":[{"text":"(1) 化合反应","score":1,"keys":[]},{"text":"(2) 设未知数、写方程式、找出 2 与 73 的关系","score":2,"keys":[]},{"text":"列比例式 2/73＝10 kg/x，解得 x＝365 kg，作答","score":3,"keys":[]},{"text":"(3) 37%","score":2,"keys":[]},{"text":"(4) 搅拌，使液体混合均匀","score":1,"keys":[]},{"text":"盐酸挥发，使溶质减少","score":1,"keys":[]}],"score":10,"sample":"(1) 化合反应。\n(2) 解：设生成氯化氢的质量为 x。\nH₂＋Cl₂ ═点燃═ 2HCl\n2　　　　　　 73\n10 kg　　　　 x\n2/73＝10 kg/x，x＝365 kg。\n答：完全反应生成氯化氢的质量为 365 kg。\n(3) 37%。\n(4) 搅拌，使液体混合均匀；盐酸挥发，使溶质减少。","method":"设未知数 → 写化学方程式 → 找相关物质的质量关系 → 列比例式 → 求解 → 答。","answer":[],"explanation":"2HCl 的相对质量是 2×36.5＝73。(3) 37÷(37＋63)×100%＝37%。浓盐酸有挥发性，HCl 跑掉，浓度偏小。","kp":"根据化学方程式的计算","kpId":"chemistry-sp-p11","kpRef":true},{"id":"kp-chemistry-sp-p12-01","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 10.6 g 碳酸钠固体完全溶解在 93.8 g 稀盐酸中恰好完全反应（Na2CO3＋2HCl＝2NaCl＋H2O＋CO2↑，Na2CO3-106, NaCl-58.5, CO2-44），生成 CO2 质量为 4.4 g，则反应后所得溶液的质量为______g。","blanks":[["100"]],"answer":["100"],"explanation":"m液后＝10.6＋93.8－4.4＝100 g。"},{"id":"kp-chemistry-sp-p12-02","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"将 10.6 g 碳酸钠固体与 93.8 g 稀盐酸恰好完全反应，生成 11.7 g NaCl 和 4.4 g CO2，则反应后所得氯化钠溶液的溶质质量分数为______%。","blanks":[["11.7"]],"answer":["11.7"],"explanation":"m液后＝100 g，ω＝11.7÷100×100%＝11.7%。"},{"id":"kp-chemistry-sp-p12-03","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"把 10 g 含杂质的石灰石样品（含 CaCO3 80%，杂质不溶也不反应）加入 95.52 g 稀盐酸中恰好完全反应，生成 3.52 g CO2，则反应后滤液的质量为______g。","blanks":[["100"]],"answer":["100"],"explanation":"纯 CaCO3 8 g（杂质 2 g 不进溶液），m液后＝8＋95.52－3.52＝100 g！"},{"id":"kp-chemistry-sp-p12-04","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"向 100 g 质量分数为 10% 的 NaOH 溶液中加入 100 g 稀盐酸恰好完全中和，反应后所得溶液的质量是（ ）","options":[{"key":"A","text":"190 g"},{"key":"B","text":"200 g"},{"key":"C","text":"100 g"},{"key":"D","text":"180 g"}],"answer":["B"],"explanation":"中和反应无气体和沉淀生成，故反应后溶液质量直接等于 100＋100＝200 g。"},{"id":"kp-chemistry-sp-p12-05","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将 5.6 g 铁粉加入 94.6 g 稀硫酸中恰好完全反应，生成 0.2 g H2 和 15.2 g FeSO4，则反应后所得硫酸亚铁溶液的溶质质量分数为______%。","blanks":[["15.2"]],"answer":["15.2"],"explanation":"m液后＝5.6＋94.6－0.2＝100 g，ω＝15.2÷100×100%＝15.2%。"},{"id":"kp-chemistry-sp-p12-06","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"将含 NaCl 和 Na2CO3 的固体混合物 20 g（其中 Na2CO3 为 10.6 g）加入 84.4 g 稀盐酸中恰好完全反应，生成 11.7 g NaCl 和 4.4 g CO2，则所得溶液中 NaCl 的溶质质量分数为______%。","blanks":[["21.1"]],"answer":["21.1"],"explanation":"原有 NaCl＝20－10.6＝9.4 g，总溶质＝9.4＋11.7＝21.1 g；m液后＝20＋84.4－4.4＝100 g；ω＝21.1%。"},{"id":"kp-chemistry-sp-p12-07","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"向 100 g 质量分数为 16% 的 CuSO4 溶液中加入 109.8 g NaOH 溶液恰好完全反应（CuSO4-160, Cu(OH)2-98, Na2SO4-142），生成 9.8 g Cu(OH)2 沉淀和 14.2 g Na2SO4，则反应后滤液的溶质质量分数为______%。","blanks":[["7.1"]],"answer":["7.1"],"explanation":"m液后＝100＋109.8－9.8＝200 g，ω＝14.2÷200×100%＝7.1%。"},{"id":"kp-chemistry-sp-p12-08","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（拓展）","level":3,"kpFree":false,"type":"single","stem":"在计算“反应后所得溶液的溶质质量分数”时，下列哪一项绝对不能算入“反应后溶液质量”中（ ）","options":[{"key":"A","text":"原有且未参加反应的可溶性溶质质量"},{"key":"B","text":"溶剂水的质量"},{"key":"C","text":"原混合物中未反应的难溶性杂质质量"},{"key":"D","text":"新生成的可溶性溶质质量"}],"answer":["C"],"explanation":"难溶性杂质不溶解在水中，必须从溶液总质量中扣除。"},{"id":"kp-chemistry-sp-p12-09","subject":"chemistry","subjectLabel":"化学","knowledge":true,"kpId":"chemistry-sp-p12","kp":"溶液反应后所得溶液溶质质量分数综合计算","unit":"专题·图像分析与综合计算","chapter":"专题与压轴 · 化学图像与综合计算压轴","source":"知识点精练 · 专题与压轴 · 溶液反应后所得溶液溶质质量分数综合计算（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"溶液质量分数计算","stem":"称取 12.5 g 石灰石样品（杂质不溶于水，也不与稀盐酸反应）放入烧杯中，加入 100 g 稀盐酸恰好完全反应，测得反应后烧杯内剩余物质总质量为 108.1 g。（相对原子质量：Ca-40，C-12，O-16，Cl-35.5）求：（1）反应生成 CO₂ 的质量；（2）样品中 CaCO₃ 的质量分数；（3）反应后过滤所得滤液中溶质的质量分数（结果精确到 0.1%）。","score":10,"points":[{"text":"（1）由质量守恒得 m(CO₂)＝12.5 g＋100 g－108.1 g＝4.4 g","score":2,"keys":["4.4"]},{"text":"（2）列方程式 CaCO₃＋2HCl＝CaCl₂＋H₂O＋CO₂↑，解得 m(CaCO₃)＝10 g，质量分数 10/12.5＝80%","score":4,"keys":["10","80%"]},{"text":"（3）解得 m(CaCl₂)＝11.1 g，滤液质量＝10＋100－4.4＝105.6 g（或 108.1－2.5），溶质质量分数＝11.1/105.6≈10.5%","score":4,"keys":["11.1","105.6","10.5%"]}],"method":"① 质量守恒差量法秒算气体质量：m(CO₂)＝反应前总质量－反应后总质量；② 由化学方程式按比例同时求出参加反应的 CaCO₃ 质量和生成的 CaCl₂ 质量；③ 算滤液总质量务必减掉“不溶性杂质”和“逸出的气体”！","sample":"解：（1）根据质量守恒定律，生成 CO₂ 的质量：\nm(CO₂)＝12.5 g＋100 g－108.1 g＝4.4 g。\n（2）设样品中 CaCO₃ 的质量为 x，生成 CaCl₂ 的质量为 y。\nCaCO₃ ＋ 2HCl ＝ CaCl₂ ＋ H₂O ＋ CO₂↑\n 100              111            44\n  x                y             4.4 g\n100/x＝44/4.4 g，解得 x＝10 g；\n111/y＝44/4.4 g，解得 y＝11.1 g。\n样品中 CaCO₃ 的质量分数＝(10 g / 12.5 g)×100%＝80%。\n（3）样品中不溶性杂质质量＝12.5 g－10 g＝2.5 g。\n反应后过滤所得滤液质量＝10 g＋100 g－4.4 g＝105.6 g（或 108.1 g－2.5 g＝105.6 g）。\n滤液中溶质的质量分数＝(11.1 g / 105.6 g)×100%≈10.5%。\n答：（1）生成 CO₂ 4.4 g；（2）CaCO₃ 质量分数为 80%；（3）滤液中溶质的质量分数约为 10.5%。","explanation":"化学综合计算头号雷区：算滤液质量时错用 108.1 g（忘了减去 2.5 g 不溶杂质）！记住口诀：溶液质量＝参加反应固体＋加入液体－气体－沉淀。"}]};
